import React from 'react';
import { useSelector } from 'react-redux';
import { Link } from 'react-router-dom';
import {
  FaLinkedinIn,
  FaXTwitter,
  FaInstagram,
  FaTiktok,
  FaWhatsapp
} from 'react-icons/fa6';

const Footer = () => {
  // Get settings from Redux store
  const settings = useSelector((state) => state.settings.values);

  // Fallback values if settings not loaded
  const contactEmail = settings.contactEmail || 'richard@zyratechhub.com';
  const contactPhone = settings.contactPhone || '+233 55 955 4261';
  const contactWhatsApp = settings.contactWhatsApp || '233559554261';
  const contactAddress = settings.contactAddress || 'Koforidua, Eastern Region, Ghana';
  const tagline = settings.tagline || 'Empowering Ghana\'s Future Through Technology and Innovation.';
  const siteName = settings.siteName || 'Zyra Tech Hub';

  // Social links
  const socialLinkedIn = settings.socialLinkedIn || 'https://www.linkedin.com/company/zyratechhub/';
  const socialTwitter = settings.socialTwitter || 'https://x.com/zyratech_hub?s=21&t=T51YWSqAK0Y2P8kRclEAhQ';
  const socialInstagram = settings.socialInstagram || 'https://www.instagram.com/zyratechhub';
  const socialFacebook = settings.socialFacebook || 'https://www.tiktok.com/@zyratechhub?_r=1&_t=ZS-94KbnVr8kYj';
  const socialWhatsApp = settings.socialWhatsApp || 'https://wa.me/message/JNPRU4YUGAU5K1';

  return (
    <footer className="bg-black text-white py-8">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Main Footer Content */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6 md:gap-6 mb-6">
          {/* Zyra Tech Hub Brand */}
          <div className="col-span-2 md:col-span-1">
            <div className="mb-4">
              <img decoding="async"
                src="/zyrateclogopng.webp"
                alt={`${siteName} Logo`}
                width="160"
                height="160"
                loading="lazy"
                className="h-28 md:h-32 w-auto object-contain"
              />
            </div>
            <p className="text-sm text-gray-300 leading-relaxed">
              {tagline}
            </p>
          </div>

          {/* About & Programs */}
          <div>
            <h4 className="text-sm font-semibold text-white mb-3">About</h4>
            <ul className="space-y-1.5 mb-4">
              <li><Link to="/about" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Our Story</Link></li>
              <li><Link to="/impact" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Mission & Vision</Link></li>
              <li><Link to="/about#team" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Team</Link></li>
            </ul>

            <h4 className="text-sm font-semibold text-white mb-3">Programs</h4>
            <ul className="space-y-1.5">
              <li><Link to="/training" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Training</Link></li>
              <li><Link to="/projects" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Projects</Link></li>
              <li><Link to="/impact" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Impact</Link></li>
            </ul>
          </div>

          {/* Get Involved & Resources */}
          <div>
            <h4 className="text-sm font-semibold text-white mb-3">Get Involved</h4>
            <ul className="space-y-1.5 mb-4">
              <li><Link to="/partner" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Partner</Link></li>
              <li><Link to="/contact" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Join Us</Link></li>
            </ul>

            <h4 className="text-sm font-semibold text-white mb-3">Resources</h4>
            <ul className="space-y-1.5">
              <li><Link to="/blog" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Blog</Link></li>
              <li><Link to="/gallery" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">Gallery</Link></li>
              <li><Link to="/faq" className="text-sm text-gray-300 hover:text-[#004fa2] transition-colors">FAQ</Link></li>
            </ul>
          </div>

          {/* Contact Us & Newsletter */}
          <div className="col-span-2 md:col-span-1">
            <h4 className="text-sm font-semibold text-white mb-3">Contact Us</h4>
            <div className="space-y-1.5 mb-3">
              <p className="text-sm text-gray-300">
                <span className="font-semibold text-white">Address:</span> {contactAddress}
              </p>
              <p className="text-sm text-gray-300">
                <span className="font-semibold text-white">Email:</span> <a href={`mailto:${contactEmail}`} className="hover:text-[#004fa2] transition-colors">{contactEmail}</a>
              </p>
              <p className="text-sm text-gray-300">
                <span className="font-semibold text-white">Phone:</span> <a href={`tel:${contactPhone.replace(/\s/g, '')}`} className="hover:text-[#004fa2] transition-colors">{contactPhone}</a>
              </p>
            </div>

            {/* Social Media */}
            <div className="flex items-center space-x-3 mb-4">
              {socialLinkedIn && (
                <a href={socialLinkedIn} target="_blank" rel="noopener noreferrer" className="w-10 h-10 bg-[#004fa2] rounded-lg flex items-center justify-center hover:bg-white hover:text-[#004fa2] transition-all duration-300 hover:-translate-y-1 shadow-md hover:shadow-lg" aria-label="Visit our LinkedIn page">
                  <FaLinkedinIn className="text-lg" />
                </a>
              )}
              {socialTwitter && (
                <a href={socialTwitter} target="_blank" rel="noopener noreferrer" className="w-10 h-10 bg-[#004fa2] rounded-lg flex items-center justify-center hover:bg-white hover:text-[#004fa2] transition-all duration-300 hover:-translate-y-1 shadow-md hover:shadow-lg" aria-label="Visit our X (Twitter) page">
                  <FaXTwitter className="text-lg" />
                </a>
              )}
              {socialInstagram && (
                <a href={socialInstagram} target="_blank" rel="noopener noreferrer" className="w-10 h-10 bg-[#004fa2] rounded-lg flex items-center justify-center hover:bg-white hover:text-[#004fa2] transition-all duration-300 hover:-translate-y-1 shadow-md hover:shadow-lg" aria-label="Visit our Instagram page">
                  <FaInstagram className="text-xl" />
                </a>
              )}
              {socialFacebook && (
                <a href={socialFacebook} target="_blank" rel="noopener noreferrer" className="w-10 h-10 bg-[#004fa2] rounded-lg flex items-center justify-center hover:bg-white hover:text-[#004fa2] transition-all duration-300 hover:-translate-y-1 shadow-md hover:shadow-lg" aria-label="Visit our TikTok page">
                  <FaTiktok className="text-lg" />
                </a>
              )}
              {socialWhatsApp && (
                <a href={socialWhatsApp} target="_blank" rel="noopener noreferrer" className="w-10 h-10 bg-[#004fa2] rounded-lg flex items-center justify-center hover:bg-white hover:text-[#004fa2] transition-all duration-300 hover:-translate-y-1 shadow-md hover:shadow-lg" aria-label="Contact us on WhatsApp">
                  <FaWhatsapp className="text-xl" />
                </a>
              )}
            </div>
          </div>
        </div>

        {/* Copyright */}
        <div className="pt-6 border-t border-gray-800">
          <div className="text-center">
            <p className="text-sm text-gray-400">
              ┬⌐ {new Date().getFullYear()} {siteName}. All rights reserved.
            </p>
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;

import React, { useState } from 'react';
import { ChevronDown, ExternalLink, Link as LinkIcon } from 'lucide-react';

/**
 * LinkPicker Component - COMPLETE & VERIFIED
 * All routes verified against App.jsx route definitions
 * NO broken links - every route has been tested
 */

const LinkPicker = ({ value, onChange, placeholder = "Select or paste a link" }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [linkType, setLinkType] = useState(value?.startsWith('http') ? 'external' : 'internal');
  const [customUrl, setCustomUrl] = useState(value?.startsWith('http') ? value : '');

  // ALL VERIFIED PUBLIC ROUTES - organized by category
  // Every route has been verified to exist in App.jsx
  const internalRoutes = {
    '≡ƒÅá Core Pages': [
      { label: 'Home', value: '/' },
      { label: 'About', value: '/about' },
      { label: 'Contact', value: '/contact' },
      { label: 'FAQ', value: '/faq' },
    ],
    '≡ƒÄô Training': [
      { label: 'Training Home', value: '/training' },
      { label: 'Training Contact', value: '/training/contact' },
      { label: 'Training Programs', value: '/training/programs' },
      { label: 'Training - Basic Programs', value: '/training/programs/basic' },
      { label: 'Training - Intermediate Programs', value: '/training/programs/intermediate' },
      { label: 'Training - Advanced Programs', value: '/training/programs/advanced' },
      { label: 'Training - Matured Programs', value: '/training/programs/matured' },
      { label: 'Training - Internship Programs', value: '/training/programs/internship' },
      { label: 'Training Application Success', value: '/training/application-success' },
    ],
    '≡ƒÆ╝ Jobs & Careers': [
      { label: 'Jobs', value: '/jobs' },
    ],
    '≡ƒôè Projects': [
      { label: 'Projects', value: '/projects' },
      { label: 'Project Request', value: '/projects/request' },
    ],
    '≡ƒÄ¿ Gallery & Media': [
      { label: 'Gallery', value: '/gallery' },
    ],
    '≡ƒô░ Content': [
      { label: 'Blog', value: '/blog' },
      { label: 'Impact', value: '/impact' },
      { label: 'Partnerships', value: '/partner' },
      { label: 'Partnership Application', value: '/partner/apply' },
    ],
    '≡ƒÅó Business Pages': [
      { label: 'Our Services', value: '/our-services' },
      { label: 'Collaboration Models', value: '/collaboration-models' },
      { label: 'Work With Us', value: '/work-with-us' },
      { label: 'Quality Assurance', value: '/quality-assurance' },
    ],
  };

  const handleSelectRoute = (route) => {
    onChange(route);
    setIsOpen(false);
    setLinkType('internal');
  };

  const handleExternalLinkChange = (e) => {
    const url = e.target.value;
    setCustomUrl(url);
    // Only update parent if valid URL
    if (url && (url.startsWith('http://') || url.startsWith('https://'))) {
      onChange(url);
    }
  };

  const handleLinkTypeChange = (type) => {
    setLinkType(type);
    if (type === 'external') {
      setCustomUrl('');
    }
  };

  // Find the current label if internal link is selected
  const getCurrentLabel = () => {
    if (!value || value.startsWith('http')) return null;
    for (const category of Object.values(internalRoutes)) {
      const found = category.find(r => r.value === value);
      if (found) return found.label;
    }
    return null;
  };

  const currentLabel = getCurrentLabel();

  return (
    <div className="space-y-3">
      {/* Link Type Selector */}
      <div className="flex gap-2">
        <button
          type="button"
          onClick={() => handleLinkTypeChange('internal')}
          className={`flex-1 px-3 py-2 rounded-lg font-medium text-sm transition-all ${
            linkType === 'internal'
              ? 'bg-[#004fa2] text-white shadow-sm'
              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
          }`}
        >
          <LinkIcon size={14} className="inline mr-1.5" />
          Page
        </button>
        <button
          type="button"
          onClick={() => handleLinkTypeChange('external')}
          className={`flex-1 px-3 py-2 rounded-lg font-medium text-sm transition-all ${
            linkType === 'external'
              ? 'bg-[#004fa2] text-white shadow-sm'
              : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
          }`}
        >
          <ExternalLink size={14} className="inline mr-1.5" />
          External
        </button>
      </div>

      {/* Internal Link Dropdown */}
      {linkType === 'internal' && (
        <div className="relative">
          <button
            type="button"
            onClick={() => setIsOpen(!isOpen)}
            className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all text-left flex items-center justify-between bg-white"
          >
            <span className={currentLabel ? 'text-gray-900 font-medium' : 'text-gray-500'}>
              {currentLabel || 'Select a page...'}
            </span>
            <ChevronDown size={16} className={`transition-transform ${isOpen ? 'rotate-180' : ''}`} />
          </button>

          {/* Dropdown Menu */}
          {isOpen && (
            <div className="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-200 rounded-lg shadow-lg z-10 max-h-96 overflow-y-auto">
              {Object.entries(internalRoutes).map(([category, routes]) => (
                <div key={category}>
                  {/* Category Header */}
                  <div className="px-4 py-2.5 bg-gray-50 border-b border-gray-100 font-semibold text-sm text-gray-700">
                    {category}
                  </div>
                  {/* Routes */}
                  {routes.map((route) => (
                    <button
                      key={route.value}
                      type="button"
                      onClick={() => handleSelectRoute(route.value)}
                      className={`w-full text-left px-4 py-2.5 hover:bg-blue-50 transition-colors text-sm ${
                        value === route.value ? 'bg-blue-100 text-[#004fa2] font-medium border-l-4 border-[#004fa2]' : 'text-gray-700'
                      }`}
                    >
                      {route.label}
                    </button>
                  ))}
                </div>
              ))}
            </div>
          )}

          {/* Current Selection Display */}
          {currentLabel && (
            <div className="mt-2 p-2.5 bg-blue-50 border border-blue-100 rounded text-xs text-blue-700 flex items-center gap-2">
              <LinkIcon size={13} />
              <span className="font-medium">Selected:</span>
              <code className="bg-white px-2 py-0.5 rounded font-mono text-blue-900">{value}</code>
            </div>
          )}
        </div>
      )}

      {/* External Link Input */}
      {linkType === 'external' && (
        <div className="space-y-2">
          <input
            type="url"
            value={customUrl}
            onChange={handleExternalLinkChange}
            placeholder="https://example.com"
            className="w-full px-4 py-2 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all"
          />
          {customUrl && (customUrl.startsWith('http://') || customUrl.startsWith('https://')) ? (
            <div className="p-2.5 bg-green-50 border border-green-100 rounded text-xs text-green-700 flex items-center gap-2">
              <ExternalLink size={13} />
              <span className="font-medium">Valid:</span>
              <code className="bg-white px-2 py-0.5 rounded font-mono text-green-900 truncate">{customUrl}</code>
            </div>
          ) : customUrl ? (
            <div className="p-2.5 bg-amber-50 border border-amber-100 rounded text-xs text-amber-700 flex items-center gap-2">
              ΓÜá∩╕Å
              <span>Link must start with <code className="bg-white px-1 py-0.5 rounded font-mono">https://</code> or <code className="bg-white px-1 py-0.5 rounded font-mono">http://</code></span>
            </div>
          ) : null}
        </div>
      )}

      {/* Helper text */}
      <p className="text-xs text-gray-500 mt-2 p-2 bg-gray-50 rounded border border-gray-100">
        ≡ƒÆí <strong>Tip:</strong> Select from verified pages above or add any external link. All internal routes have been tested.
      </p>
    </div>
  );
};

export default LinkPicker;

∩╗┐/**
 * ActivityTable Component - Fixed to match dashboardService data structure
 * Recent activity table with mixed event types
 */

import React from 'react';
import { CheckCircle, Clock, XCircle, ArrowUpRight, CreditCard, MessageSquare, GraduationCap, UserPlus } from 'lucide-react';

const ActivityTable = ({ activities = [], title = "Recent Activity" }) => {
  const getTypeIcon = (type) => {
    switch (type?.toLowerCase()) {
      case 'payment':
        return <CreditCard size={14} className="text-green-600" />;
      case 'inquiry':
        return <MessageSquare size={14} className="text-blue-600" />;
      case 'enrollment':
        return <GraduationCap size={14} className="text-purple-600" />;
      case 'user':
        return <UserPlus size={14} className="text-cyan-600" />;
      default:
        return <CheckCircle size={14} className="text-gray-400" />;
    }
  };

  const getStatusColor = (status) => {
    switch (status?.toLowerCase()) {
      case 'success':
      case 'successful':
      case 'completed':
      case 'paid':
        return 'text-green-600 bg-green-50';
      case 'pending':
      case 'new':
        return 'text-amber-600 bg-amber-50';
      case 'failed':
      case 'rejected':
        return 'text-red-600 bg-red-50';
      case 'approved':
        return 'text-green-600 bg-green-50';
      default:
        return 'text-gray-600 bg-gray-50';
    }
  };

  const formatDate = (timestamp) => {
    if (!timestamp) return 'N/A';
    const date = new Date(timestamp);
    return date.toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' });
  };

  const formatTime = (timestamp) => {
    if (!timestamp) return 'N/A';
    const date = new Date(timestamp);
    return date.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit' });
  };

  return (
    <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm">
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-sm font-semibold text-gray-700">{title}</h3>
        <button className="text-gray-400 hover:text-gray-600">
          <ArrowUpRight size={18} />
        </button>
      </div>

      <div className="space-y-1">
        {/* Table Header */}
        <div className="grid grid-cols-12 gap-3 px-3 py-2 text-xs font-semibold text-gray-500 border-b border-gray-100">
          <div className="col-span-5">Activity</div>
          <div className="col-span-3">User</div>
          <div className="col-span-2">Date</div>
          <div className="col-span-2">Status</div>
        </div>

        {/* Table Rows */}
        {activities.length > 0 ? (
          activities.map((activity, index) => (
            <div
              key={index}
              className="grid grid-cols-12 gap-3 px-3 py-3 text-sm hover:bg-gray-50 rounded-lg transition-colors cursor-pointer group"
            >
              <div className="col-span-5 flex items-center gap-2">
                <div className="w-8 h-8 rounded-full bg-[#004fa2] flex items-center justify-center text-white flex-shrink-0">
                  {getTypeIcon(activity.type)}
                </div>
                <div className="min-w-0">
                  <p className="text-xs font-semibold text-gray-900 truncate group-hover:text-[#004fa2]">
                    {activity.title}
                  </p>
                  <p className="text-[10px] text-gray-500 truncate capitalize">{activity.type}</p>
                </div>
              </div>
              <div className="col-span-3 text-xs text-gray-600 flex items-center truncate">
                {activity.user || 'Unknown'}
              </div>
              <div className="col-span-2 text-xs text-gray-600 flex items-center">
                {formatDate(activity.timestamp)}
              </div>
              <div className="col-span-2 flex items-center">
                <span className={`inline-flex items-center gap-1 px-2 py-1 rounded-full text-[10px] font-semibold capitalize ${getStatusColor(activity.status)}`}>
                  {activity.status || 'Unknown'}
                </span>
              </div>
            </div>
          ))
        ) : (
          <div className="text-center py-8 text-gray-400 text-sm">
            No recent activity
          </div>
        )}
      </div>
    </div>
  );
};

export default ActivityTable;

∩╗┐/**
 * ChartCard Component - Fixed with safe defaults and solid colors
 * Revenue/Engagement chart with period toggle
 */

import React, { useState } from 'react';
import { ArrowUpRight } from 'lucide-react';

const ChartCard = ({ title = 'Revenue Trend', data = [], type = 'bar', metric = 'Revenue' }) => {
  const [period, setPeriod] = useState('monthly');

  // Safe data processing
  const safeData = Array.isArray(data) && data.length > 0 ? data : [
    { month: 'Jan', revenue: 0 },
    { month: 'Feb', revenue: 0 },
    { month: 'Mar', revenue: 0 },
    { month: 'Apr', revenue: 0 },
    { month: 'May', revenue: 0 },
    { month: 'Jun', revenue: 0 }
  ];

  const maxValue = Math.max(...safeData.map(d => Number(d.amount || d.value || d.revenue) || 0), 1);
  const peakMonth = safeData.reduce((max, d) => {
    const currentVal = Number(d.amount || d.value || d.revenue) || 0;
    const maxVal = Number(max.amount || max.value || max.revenue) || 0;
    return currentVal > maxVal ? d : max;
  }, safeData[0]);

  return (
    <div className="bg-white rounded-xl p-5 border border-gray-100 shadow-sm h-full">
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-sm font-semibold text-gray-700">{title}</h3>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={() => setPeriod('monthly')}
            className={`px-3 py-1.5 text-xs font-semibold rounded-lg transition-all ${
              period === 'monthly'
                ? 'bg-[#1a7f64] text-white'
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            Monthly
          </button>
          <button
            onClick={() => setPeriod('annually')}
            className={`px-3 py-1.5 text-xs font-semibold rounded-lg transition-all ${
              period === 'annually'
                ? 'bg-[#1a7f64] text-white'
                : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
            }`}
          >
            Annually
          </button>
          <button className="text-gray-400 hover:text-gray-600">
            <ArrowUpRight size={18} />
          </button>
        </div>
      </div>

      {/* Chart */}
      <div className="relative h-64">
        <div className="absolute inset-0 flex items-end justify-around gap-3 px-2">
          {safeData.map((item, index) => {
            const value = Number(item.amount || item.value || item.revenue) || 0;
            const percentage = maxValue > 0 ? (value / maxValue) * 100 : 0;
            const isPeak = item.month === peakMonth?.month;

            return (
              <div key={index} className="flex-1 flex flex-col items-center">
                <div className="w-full flex flex-col items-center mb-2">
                  {isPeak && value > 0 && (
                    <div className="mb-1 px-2 py-0.5 bg-[#1a7f64] text-white rounded text-[10px] font-bold">
                      {(value / 1000).toFixed(1)}k
                    </div>
                  )}
                  <div
                    className="w-full bg-[#1a7f64] rounded-t-lg transition-all duration-500 hover:opacity-80 cursor-pointer relative group"
                    style={{ height: `${percentage}%`, minHeight: '8px' }}
                  >
                    <div className="absolute -top-8 left-1/2 -translate-x-1/2 bg-gray-900 text-white px-2 py-1 rounded text-xs font-semibold opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
                      GHS {value.toLocaleString('en-US', { minimumFractionDigits: 0, maximumFractionDigits: 0 })}
                    </div>
                    <div className="absolute inset-0 bg-[repeating-linear-gradient(45deg,transparent,transparent_4px,rgba(255,255,255,0.1)_4px,rgba(255,255,255,0.1)_8px)]"></div>
                  </div>
                </div>
                <p className="text-[10px] font-medium text-gray-500 mt-2">{item.month || `M${index + 1}`}</p>
              </div>
            );
          })}
        </div>

        {/* Y-axis labels */}
        <div className="absolute left-0 top-0 bottom-8 flex flex-col justify-between text-[10px] text-gray-400 -ml-8">
          <span>{(maxValue / 1000).toFixed(0)}k</span>
          <span>{(maxValue / 2000).toFixed(0)}k</span>
          <span>0</span>
        </div>
      </div>
    </div>
  );
};

export default ChartCard;

/**
 * Admin Layout Wrapper
 * Main layout for all admin pages
 */

import React, { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import Sidebar from './Sidebar';
import Header from './Header';
import NotificationSystem from '../shared/NotificationSystem';
import { useAuth } from '../../../hooks/useAuth';
import { Navigate } from 'react-router-dom';

const AdminLayout = ({ children }) => {
  const { isAuthenticated } = useAuth();
  // const notifications = useSelector((state) => state.ui.notifications); // Internalized in NotificationSystem
  const [sidebarOpen, setSidebarOpen] = useState(true); // Default open on desktop
  const [isMobile, setIsMobile] = useState(false);

  // Detect mobile screen
  useEffect(() => {
    const checkMobile = () => {
      const mobile = window.innerWidth < 1024;
      setIsMobile(mobile);
      // Close sidebar by default on mobile
      if (mobile) {
        setSidebarOpen(false);
      } else {
        setSidebarOpen(true);
      }
    };

    checkMobile();
    window.addEventListener('resize', checkMobile);
    return () => window.removeEventListener('resize', checkMobile);
  }, []);

  // Close sidebar on route change (mobile only)
  useEffect(() => {
    if (isMobile) {
      setSidebarOpen(false);
    }
  }, [children, isMobile]);

  if (!isAuthenticated) {
    return <Navigate to="/admin/login" replace />;
  }

  const toggleSidebar = () => {
    setSidebarOpen(!sidebarOpen);
  };

  return (
    <div className="flex h-screen bg-gray-50 overflow-hidden">
      {/* Mobile Overlay */}
      {isMobile && sidebarOpen && (
        <div
          className="fixed inset-0 bg-black/50 z-40"
          onClick={() => setSidebarOpen(false)}
        />
      )}

      {/* Sidebar Container: controls width on desktop */}
      <div
        className={
          isMobile
            ? ''
            : sidebarOpen
              ? 'w-72 transition-all duration-300'
              : 'w-0 transition-all duration-300 overflow-hidden'
        }
      >
        <Sidebar isOpen={sidebarOpen} onClose={() => setSidebarOpen(false)} isMobile={isMobile} />
      </div>

      {/* Main Content */}
      <div className="flex-1 flex flex-col overflow-hidden">
        {/* Header */}
        <Header onMenuClick={toggleSidebar} sidebarOpen={sidebarOpen} />

        {/* Page Content */}
        <main className="flex-1 overflow-auto">
          <div className="p-4 md:p-6">
            {children}
          </div>
        </main>
      </div>

      {/* Notification System */}
      <NotificationSystem />
    </div>
  );
};

export default AdminLayout;

/**
 * Admin Header Component
 * Modern header with search, notifications, and user menu
 */

import React, { useState } from 'react';
import { Bell, Settings, Search, ChevronDown, User, LogOut, Menu, PanelLeftClose, PanelLeft } from 'lucide-react';
import { useAuth } from '../../../hooks/useAuth';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { logoutUser } from '../../../store/slices/authSlice';
import { useDispatch, useSelector } from 'react-redux';

import { normalizeAvatarUrl } from '../../../utils/avatar';

const Header = ({ onMenuClick, sidebarOpen }) => {
  const { user: hookUser } = useAuth();
  const reduxUser = useSelector((state) => state.auth.user);
  const user = reduxUser || hookUser;
  const { userRole } = useAuth();
  const isSuperAdmin = userRole?.toLowerCase() === 'super_admin' || userRole?.toLowerCase() === 'super admin';
  const location = useLocation();
  const navigate = useNavigate();
  const [searchQuery, setSearchQuery] = useState('');
  const [showUserMenu, setShowUserMenu] = useState(false);
  const [avatarUrl, setAvatarUrl] = useState(null);
  const [avatarLoadError, setAvatarLoadError] = useState(false);
  const [, setTick] = useState(0);

  // Listen for avatar changes from profile page or auth state
  React.useEffect(() => {
    const getActiveAvatar = () => normalizeAvatarUrl(localStorage.getItem('admin_avatar') || user?.avatar || null);
    setAvatarUrl(getActiveAvatar());
    setAvatarLoadError(false);

    const handleStorageChange = () => {
      setAvatarUrl(getActiveAvatar());
      setAvatarLoadError(false);
      setTick(t => t + 1);
    };

    window.addEventListener('avatar-updated', handleStorageChange);
    window.addEventListener('user-profile-updated', handleStorageChange);
    window.addEventListener('storage', handleStorageChange);
    return () => {
      window.removeEventListener('avatar-updated', handleStorageChange);
      window.removeEventListener('user-profile-updated', handleStorageChange);
      window.removeEventListener('storage', handleStorageChange);
    };
  }, [user?.avatar]);

  const getBreadcrumb = () => {
    const path = location.pathname;
    if (path === '/admin/dashboard') return 'Dashboard';
    if (path.includes('/admin/users')) return 'Dashboard / Users / Overview';
    if (path.includes('/admin/settings')) return 'Dashboard / Settings';
    return 'Dashboard';
  };

  const displayName = (user?.firstName && user?.lastName)
    ? `${user.firstName} ${user.lastName}`.trim()
    : (user?.name || user?.email || 'User');

  const getInitials = (name) => {
    if (user?.firstName && user?.lastName) {
      return `${user.firstName[0]}${user.lastName[0]}`.toUpperCase();
    }
    return name
      ?.split(' ')
      .map((n) => n[0])
      .join('')
      .toUpperCase() || 'U';
  };

  const dispatch = useDispatch();

  const handleLogout = () => {
    dispatch(logoutUser()).then(() => {
      navigate('/admin/login');
    });
  };

  return (
    <header className="bg-white border-b border-gray-100 sticky top-0 z-40">
      <div className="px-4 lg:px-8 py-4">
        {/* Top Row: Search, Avatar, Notifications */}
        <div className="flex items-center justify-between mb-3">
          {/* Left: Hamburger + Search Bar */}
          <div className="flex items-center gap-3 flex-1 lg:max-w-xl">
            {/* Hamburger/Toggle Menu Button - always visible */}
            <button
              onClick={onMenuClick}
              className="p-2 text-gray-600 hover:text-gray-900 hover:bg-gray-100 rounded-lg transition-colors"
              aria-label={sidebarOpen ? 'Close menu' : 'Open menu'}
              title={sidebarOpen ? 'Collapse sidebar' : 'Expand sidebar'}
            >
              {sidebarOpen ? <PanelLeftClose size={22} /> : <PanelLeft size={22} />}
            </button>

            {/* Search Bar - Hidden on mobile, visible on desktop */}
            <div className="hidden md:block flex-1">
              <div className="relative">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={20} />
                <input
                  type="text"
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  placeholder="Search anything..."
                  className="w-full pl-10 pr-4 py-2.5 bg-gray-50 border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#004fa2] focus:border-transparent text-sm"
                />
              </div>
            </div>

            {/* Mobile Search Icon */}
            <button className="md:hidden p-2 text-gray-600 hover:bg-gray-100 rounded-lg">
              <Search size={22} />
            </button>
          </div>

          {/* Right Side: Avatar, Notifications, Settings */}
          <div className="flex items-center gap-2 sm:gap-4">
            <div className="relative">
              <button
                onClick={() => setShowUserMenu(!showUserMenu)}
                className="flex items-center gap-2 px-1 sm:px-3 py-2 hover:bg-gray-100 rounded transition-colors"
              >
                <div className="w-8 h-8 bg-blue-600 text-white rounded-full flex items-center justify-center text-sm font-bold flex-shrink-0 overflow-hidden">
                  {avatarUrl && !avatarLoadError ? (
                    <img
                      key={avatarUrl}
                      src={avatarUrl}
                      alt={displayName || 'Profile'}
                      className="w-full h-full object-cover"
                      onError={() => setAvatarLoadError(true)}
                    />
                  ) : (
                    getInitials(displayName)
                  )}
                </div>
                <span className="hidden sm:block text-sm font-medium text-gray-900 truncate max-w-[100px] sm:max-w-none">{displayName}</span>
                <ChevronDown size={16} className="text-gray-600" />
              </button>

              {/* Dropdown Menu */}
              {showUserMenu && (
                <div className="absolute right-0 top-full mt-2 w-48 bg-white border border-gray-200 rounded shadow-lg z-50">
                  <div className="px-4 py-3 border-b border-gray-200">
                    <p className="text-sm font-medium text-gray-900">{displayName}</p>
                    <p className="text-xs text-gray-600">{user?.email}</p>
                  </div>

                  {isSuperAdmin && (
                    <Link
                      to="/admin/settings"
                      className="flex items-center gap-2 px-4 py-2 text-gray-700 hover:bg-gray-100"
                    >
                      <Settings size={16} />
                      Settings
                    </Link>
                  )}

                  <Link
                    to="/admin/profile"
                    className="flex items-center gap-2 px-4 py-2 text-gray-700 hover:bg-gray-100"
                  >
                    <User size={16} />
                    Profile
                  </Link>

                  <div className="border-t border-gray-200"></div>

                  <button
                    onClick={handleLogout}
                    className="w-full text-left flex items-center gap-2 px-4 py-2 text-red-600 hover:bg-red-50"
                  >
                    <LogOut size={16} />
                    Logout
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </header>
  );
};

export default Header;

