import React, { useState, useMemo, useEffect, useCallback, useRef } from 'react';
import { Play, Grid, List, X, ChevronLeft, ChevronRight, Maximize2, Minimize2, Search } from 'lucide-react';
import { useNavigate } from 'react-router-dom';
import galleryService from '../../../services/galleryService';
import api from '../../../services/api';

const MediaGrid = ({ filters = {} }) => {
  const navigate = useNavigate();
  const [viewMode, setViewMode] = useState('grid');
  const [itemsPerPage, setItemsPerPage] = useState(8);
  const [currentPage, setCurrentPage] = useState(1);
  const [selectedItem, setSelectedItem] = useState(null);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [albums, setAlbums] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const touchStartX = useRef(null);
  const touchEndX = useRef(null);

  // Fetch public albums from backend
  useEffect(() => {
    const fetchPublicAlbums = async () => {
      try {
        setIsLoading(true);
        setError(null);
        
        // Call public gallery endpoint - no authentication required
        const response = await api.get('/gallery/albums', {
          params: { page: 1, limit: 100 }
        });
        
        const data = response.data;
        let albums = [];
        
        // Backend returns: { success: true, data: { data: [...albums], pagination: {...} } }
        if (data.success && data.data && data.data.data) {
          // Correct format from backend
          albums = Array.isArray(data.data.data) ? data.data.data : [];
        } else if (data.data && Array.isArray(data.data)) {
          // Fallback: if data.data is already an array
          albums = data.data;
        } else if (Array.isArray(data)) {
          // Direct array response
          albums = data;
        }
        
        console.log('[MediaGrid] Fetched public albums:', { count: albums.length, albums });
        setAlbums(albums);
      } catch (err) {
        console.error('Error fetching gallery albums:', err);
        setError('Failed to load gallery. Please try again later.');
        setAlbums([]);
      } finally {
        setIsLoading(false);
      }
    };

    fetchPublicAlbums();
  }, []);

  // Transform albums to media items
  const allMediaItems = useMemo(() => 
    albums.map(album => ({
      id: album.id,
      title: album.title,
      type: "album",
      thumbnail: album.coverImageUrl || (album.media && album.media[0]?.url) || '/images/image1.webp',
      category: album.category,
      media: album.media || [], // Backend returns media array
      description: album.description
    })), [albums]
  );

  // Debug logging
  useEffect(() => {
    console.log('[MediaGrid] Loaded albums:', albums.length);
    console.log('[MediaGrid] Media items:', allMediaItems);
  }, [allMediaItems, albums]);

  // Optimized filtering with useCallback
  const filteredItems = useMemo(() => {
    let filtered = allMediaItems;

    if (filters.searchTerm) {
      const searchLower = filters.searchTerm.toLowerCase();
      filtered = filtered.filter(item => 
        item.title.toLowerCase().includes(searchLower) ||
        item.keywords.some(keyword => keyword.toLowerCase().includes(searchLower))
      );
    }

    if (filters.category && filters.category !== 'all') {
      filtered = filtered.filter(item => item.category === filters.category);
    }

    return filtered;
  }, [allMediaItems, filters]);

  // Pagination
  const totalPages = Math.ceil(filteredItems.length / itemsPerPage);
  const startIndex = (currentPage - 1) * itemsPerPage;
  const paginatedItems = filteredItems.slice(startIndex, startIndex + itemsPerPage);



  // Keyboard navigation
  useEffect(() => {
    if (!selectedItem) return;

    const handleKeyDown = (e) => {
      if (e.key === 'Escape') {
        setSelectedItem(null);
        setCurrentImageIndex(0);
        setIsFullscreen(false);
      } else if (e.key === 'ArrowLeft') {
        setCurrentImageIndex((prev) => (prev > 0 ? prev - 1 : selectedItem.media.length - 1));
      } else if (e.key === 'ArrowRight') {
        setCurrentImageIndex((prev) => (prev < selectedItem.media.length - 1 ? prev + 1 : 0));
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [selectedItem]);

  return (
    <section className="py-12 bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* Section Header */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6 sm:mb-8">
          <div>
            <h2 className="text-2xl sm:text-3xl lg:text-4xl xl:text-5xl font-extrabold text-black mb-2">
              Media Gallery
            </h2>
            <p className="text-sm sm:text-base text-gray-600">
              {filteredItems.length} {filteredItems.length === 1 ? 'item' : 'items'} found
              {filters.searchTerm && ` for "${filters.searchTerm}"`}
            </p>
          </div>

          {/* Controls */}
          <div className="flex items-center gap-4">
            
            {/* View Mode Toggle */}
            <div className="flex bg-gray-100 rounded-lg p-1">
              <button
                onClick={() => setViewMode('grid')}
                className={`p-2.5 sm:p-2 rounded-md transition-all ${
                  viewMode === 'grid'
                    ? 'bg-white text-[#004fa2] shadow-sm'
                    : 'text-gray-600 hover:text-gray-900'
                }`}
                title="Grid View"
                aria-label="Grid View"
              >
                <Grid size={18} className="sm:w-4 sm:h-4" />
              </button>
              <button
                onClick={() => setViewMode('list')}
                className={`p-2.5 sm:p-2 rounded-md transition-all ${
                  viewMode === 'list'
                    ? 'bg-white text-[#004fa2] shadow-sm'
                    : 'text-gray-600 hover:text-gray-900'
                }`}
                title="List View"
                aria-label="List View"
              >
                <List size={18} className="sm:w-4 sm:h-4" />
              </button>
            </div>
          </div>
        </div>

        {/* Loading State */}
        {isLoading && (
          <div className={`grid gap-6 ${
            viewMode === 'grid' 
              ? 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4' 
              : 'grid-cols-1 lg:grid-cols-2'
          }`}>
            {Array(8).fill(0).map((_, i) => (
              <div key={i} className="space-y-3">
                {/* Skeleton Card */}
                <div className={`relative overflow-hidden rounded-xl bg-gray-200 ${
                  viewMode === 'list' ? 'w-full sm:w-48 h-40 sm:h-32 flex-shrink-0' : 'aspect-video'
                } animate-pulse`} />
                
                {/* Skeleton Title */}
                <div className="space-y-2">
                  <div className="h-4 bg-gray-200 rounded w-3/4 animate-pulse" />
                  <div className="h-3 bg-gray-200 rounded w-1/2 animate-pulse" />
                </div>
              </div>
            ))}
          </div>
        )}

        {/* Error State */}
        {error && !isLoading && (
          <div className="bg-red-50 border border-red-200 rounded-lg p-6 text-center">
            <p className="text-red-700 font-medium">{error}</p>
          </div>
        )}

        {/* Results Summary or Empty State */}
        {!isLoading && !error && filteredItems.length === 0 ? (
          <div className="text-center py-12">
            <div className="text-gray-400 mb-4">
              <Search size={48} className="mx-auto" />
            </div>
            <h3 className="text-lg font-medium text-gray-900 mb-2">No media found</h3>
            <p className="text-gray-600">Try adjusting your search or filters to find what you're looking for.</p>
          </div>
        ) : (
          <>
            {/* Media Grid */}
            <div className={`grid gap-6 ${
              viewMode === 'grid' 
                ? 'grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4' 
                : 'grid-cols-1 lg:grid-cols-2'
            }`}>
            {paginatedItems.map((item) => (
              <div 
                key={item.id} 
                className={`group cursor-pointer ${
                  viewMode === 'list' ? 'flex flex-col sm:flex-row gap-3 sm:gap-4' : ''
                }`}
                onClick={() => {
                  navigate(`/gallery/album/${item.id}`);
                }}
              >
              
              {/* Media Thumbnail */}
              <div className={`relative overflow-hidden rounded-xl ${
                viewMode === 'list' ? 'w-full sm:w-48 h-40 sm:h-32 flex-shrink-0' : 'aspect-video'
              }`}>
                <img 
                  src={item.thumbnail}
                  alt={item.title}
                  className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
                  loading="lazy"
                  onError={(e) => {
                    console.error('Γ¥î Failed to load image:', item.thumbnail);
                    // Try fallback image
                    e.target.src = "/images/image1.webp";
                    e.target.onerror = () => {
                      e.target.style.backgroundColor = '#f3f4f6';
                      e.target.style.display = 'flex';
                      e.target.style.alignItems = 'center';
                      e.target.style.justifyContent = 'center';
                      e.target.innerHTML = '<div style="color: #6b7280; font-size: 12px; text-align: center;">Image not found</div>';
                    };
                  }}
                />
                
                {/* Category Badge */}
                <div className="absolute top-2 left-2">
                  <span className="bg-[#004fa2]/90 text-white px-2 py-1 rounded-full text-xs font-medium">
                    {item.category}
                  </span>
                </div>

                {/* Package Indicator */}
                <div className="absolute top-2 right-2">
                  <span className="bg-white/90 text-gray-800 px-2 py-1 rounded-full text-xs font-medium flex items-center gap-1">
                    <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20">
                      <path d="M4 3a2 2 0 00-2 2v10a2 2 0 002 2h12a2 2 0 002-2V5a2 2 0 00-2-2H4zm12 12H4l4-8 3 6 2-4 3 6z"/>
                    </svg>
                    {item.media?.length || 0}
                  </span>
                </div>
                  
                {/* Play Button for Videos */}
                {item.type === 'videos' && (
                  <div className="absolute inset-0 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                    <div className="w-12 h-12 bg-white/20 rounded-full flex items-center justify-center">
                      <Play className="text-white ml-1" size={20} />
                    </div>
                  </div>
                )}

                {/* Duration */}
                {item.duration && (
                  <div className="absolute bottom-2 right-2">
                    <span className="bg-black/70 text-white px-2 py-1 rounded text-xs">
                      {item.duration}
                    </span>
                  </div>
                )}
              </div>

              {/* Content */}
              <div className={`${viewMode === 'list' ? 'flex-1' : 'mt-3'}`}>
                <h3 className="font-bold text-black group-hover:text-[#004fa2] transition-colors mb-1 line-clamp-2">
                  {item.title}
                </h3>
                
                <p className="text-sm text-gray-600 capitalize">{item.category}</p>
              </div>
            </div>
          ))}
          </div>

          {/* Pagination */}
          {totalPages > 1 && (
            <div className="flex justify-center items-center gap-1.5 sm:gap-2 mt-8 sm:mt-12">
              <button
                onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
                disabled={currentPage === 1}
                className="px-3 sm:px-4 py-2 text-xs sm:text-sm border border-gray-200 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50 transition-colors"
              >
                <span className="hidden sm:inline">Previous</span>
                <span className="sm:hidden">Prev</span>
              </button>
              
              <div className="flex gap-1">
                {Array.from({ length: Math.min(5, totalPages) }, (_, i) => {
                  const pageNum = i + 1;
                  return (
                    <button
                      key={pageNum}
                      onClick={() => setCurrentPage(pageNum)}
                      className={`w-8 h-8 sm:w-10 sm:h-10 text-xs sm:text-sm rounded-lg transition-colors ${
                        currentPage === pageNum
                          ? 'bg-[#004fa2] text-white'
                          : 'border border-gray-200 hover:bg-gray-50'
                      }`}
                    >
                      {pageNum}
                    </button>
                  );
                })}
              </div>
              
              <button
                onClick={() => setCurrentPage(Math.min(totalPages, currentPage + 1))}
                disabled={currentPage === totalPages}
                className="px-3 sm:px-4 py-2 text-xs sm:text-sm border border-gray-200 rounded-lg disabled:opacity-50 disabled:cursor-not-allowed hover:bg-gray-50 transition-colors"
              >
                Next
              </button>
            </div>
          )}
          </>
        )}
        
        {/* Enhanced Modal for viewing */}
        {selectedItem && (
          <div 
            className="fixed inset-0 bg-black/95 flex items-center justify-center z-50" 
            onClick={() => {
              setSelectedItem(null);
              setCurrentImageIndex(0);
              setIsFullscreen(false);
            }}
            onTouchStart={(e) => { touchStartX.current = e.changedTouches[0].clientX; }}
            onTouchEnd={(e) => {
              touchEndX.current = e.changedTouches[0].clientX;
              const diff = touchStartX.current - touchEndX.current;
              if (Math.abs(diff) > 50) {
                e.stopPropagation();
                if (diff > 0) {
                  setCurrentImageIndex((prev) => prev < selectedItem.media.length - 1 ? prev + 1 : 0);
                } else {
                  setCurrentImageIndex((prev) => prev > 0 ? prev - 1 : selectedItem.media.length - 1);
                }
              }
            }}
          >
            {/* Modal Container */}
            <div 
              className={`relative w-full h-full flex flex-col ${isFullscreen ? '' : 'max-w-7xl max-h-[95vh] sm:max-h-[90vh] m-4'}`}
              onClick={(e) => e.stopPropagation()}
            >
              {/* Header Controls */}
              <div className="absolute top-0 left-0 right-0 z-20 bg-gradient-to-b from-black/60 to-transparent p-3 sm:p-4 flex items-start justify-between">
                <div className="flex-1 pr-4">
                  <h3 className="text-white text-base sm:text-lg md:text-xl font-bold line-clamp-2">
                    {selectedItem.title}
                  </h3>
                  <p className="text-white/80 text-xs sm:text-sm mt-1 capitalize">
                    {selectedItem.category} ΓÇó {selectedItem.media?.length || 0} {(selectedItem.media?.length || 0) === 1 ? 'photo' : 'photos'}
                  </p>
                </div>
                
                <div className="flex items-center gap-2">
                  {/* Fullscreen Toggle */}
                  <button
                    onClick={() => setIsFullscreen(!isFullscreen)}
                    className="w-8 h-8 sm:w-10 sm:h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm rounded-full flex items-center justify-center text-white transition-all"
                    title={isFullscreen ? "Exit fullscreen" : "Fullscreen"}
                    aria-label={isFullscreen ? "Exit fullscreen" : "Fullscreen"}
                  >
                    {isFullscreen ? <Minimize2 size={16} className="sm:w-5 sm:h-5" /> : <Maximize2 size={16} className="sm:w-5 sm:h-5" />}
                  </button>
                  
                  {/* Close Button */}
                  <button
                    onClick={() => {
                      setSelectedItem(null);
                      setCurrentImageIndex(0);
                      setIsFullscreen(false);
                    }}
                    className="w-8 h-8 sm:w-10 sm:h-10 bg-white/10 hover:bg-white/20 backdrop-blur-sm rounded-full flex items-center justify-center text-white transition-all"
                    aria-label="Close"
                  >
                    <X size={18} className="sm:w-6 sm:h-6" />
                  </button>
                </div>
              </div>

              {/* Main Image Area */}
              <div className="flex-1 flex items-center justify-center relative px-12 sm:px-16 py-16 sm:py-20">
                <img 
                  src={selectedItem.media[currentImageIndex]?.url || selectedItem.media[currentImageIndex]}
                  alt={`${selectedItem.title} - Image ${currentImageIndex + 1}`}
                  className={`max-w-full max-h-full object-contain rounded-lg ${isFullscreen ? 'rounded-none' : ''}`}
                  loading="lazy"
                />

                {/* Navigation Buttons */}
                {selectedItem.media?.length > 1 && (
                  <>
                    <button
                      onClick={() => setCurrentImageIndex((prev) => (prev > 0 ? prev - 1 : selectedItem.media.length - 1))}
                      className="absolute left-2 sm:left-4 top-1/2 -translate-y-1/2 w-10 h-10 sm:w-12 sm:h-12 bg-white/10 hover:bg-white/20 backdrop-blur-sm rounded-full flex items-center justify-center text-white transition-all"
                      aria-label="Previous image"
                    >
                      <ChevronLeft size={24} className="sm:w-7 sm:h-7" />
                    </button>
                    <button
                      onClick={() => setCurrentImageIndex((prev) => (prev < selectedItem.media.length - 1 ? prev + 1 : 0))}
                      className="absolute right-2 sm:right-4 top-1/2 -translate-y-1/2 w-10 h-10 sm:w-12 sm:h-12 bg-white/10 hover:bg-white/20 backdrop-blur-sm rounded-full flex items-center justify-center text-white transition-all"
                      aria-label="Next image"
                    >
                      <ChevronRight size={24} className="sm:w-7 sm:h-7" />
                    </button>
                  </>
                )}

                {/* Image Counter */}
                {selectedItem.media?.length > 1 && (
                  <div className="absolute bottom-4 left-1/2 -translate-x-1/2 bg-black/70 backdrop-blur-sm text-white px-3 sm:px-4 py-1.5 sm:py-2 rounded-full text-xs sm:text-sm font-medium">
                    {currentImageIndex + 1} / {selectedItem.media?.length || 0}
                  </div>
                )}
              </div>

              {/* Thumbnail Strip */}
              {selectedItem.media?.length > 1 && (
                <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/60 to-transparent p-3 sm:p-4">
                  <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-thin scrollbar-thumb-white/20 scrollbar-track-transparent">
                    {selectedItem.media?.map((image, index) => (
                      <button
                        key={index}
                        onClick={() => setCurrentImageIndex(index)}
                        className={`flex-shrink-0 w-16 h-16 sm:w-20 sm:h-20 rounded-lg overflow-hidden transition-all ${
                          currentImageIndex === index
                            ? 'ring-2 ring-white scale-105 opacity-100'
                            : 'opacity-50 hover:opacity-80'
                        }`}
                      >
                        <img 
                          src={image.url || image}
                          alt={`Thumbnail ${index + 1}`}
                          className="w-full h-full object-cover"
                          loading="lazy"
                        />
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>
        )}
        
      </div>
    </section>
  );
};

export default MediaGrid;

import React, { useMemo, useState, useEffect } from 'react';

const OrganizedContentGrid = ({ activeFilter, searchTerm }) => {
  const [galleryImages, setGalleryImages] = useState([]);
  const [selectedImage, setSelectedImage] = useState(null);

  // Gallery images list - dynamically loaded
  const galleryImageNames = [
    "p1.webp", "p2.webp", "p3.webp", "p4.webp", "p10.jpeg", "p11.jpeg", "p12.jpeg", "p13.jpeg",
    "p14.jpeg", "p15.jpeg", "p16.jpeg", "p17.jpeg", "p18.jpeg", "p19.jpeg", "p23.jpeg", "p24.webp",
    "p25.webp", "p26.webp", "p27.jpeg", "p28.jpeg", "p29.jpeg", "p30.jpeg", "p31.jpeg", "p32.jpeg",
    "p33.jpeg", "p34.jpeg", "p35.webp", "p36.webp", "p37.webp", "p38.webp", "p39.webp", "p40.webp",
    "p41.webp", "p42.webp", "p43.webp", "p44.webp", "p45.jpeg", "p46.jpeg", "p47.jpeg", "p48.jpeg",
    "p49.jpeg", "p50.jpeg", "p51.jpeg", "p52.jpeg", "p53.jpeg", "p54.jpeg", "p55.jpeg", "p56.jpeg",
    "17.jpeg", "p.webp"
  ];

  useEffect(() => {
    // Create content items from gallery images
    const items = galleryImageNames.map((imageName, index) => ({
      id: index + 1,
      title: `Gallery Photo ${index + 1}`,
      category: "gallery",
      image: `/images/gallery/${imageName}`,
      description: "Community event and workshop moments",
      date: "July 10, 2025"
    }));
    setGalleryImages(items);
  }, []);

  // Filter content based on active filter and search
  const filteredContent = useMemo(() => {
    let filtered = galleryImages;

    // Apply category filter
    if (activeFilter && activeFilter !== 'all') {
      filtered = filtered.filter(item => item.category === activeFilter);
    }

    // Apply search filter
    if (searchTerm) {
      const searchLower = searchTerm.toLowerCase();
      filtered = filtered.filter(item => 
        item.title.toLowerCase().includes(searchLower) ||
        item.description.toLowerCase().includes(searchLower) ||
        item.category.toLowerCase().includes(searchLower)
      );
    }

    return filtered;
  }, [activeFilter, searchTerm, galleryImages]);

  return (
    <>
    <section className="py-12 bg-gray-50">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        
        {/* Section Header */}
        <div className="mb-8">
          <h2 className="text-3xl sm:text-4xl font-bold text-black mb-2">
            Explore Our Gallery
          </h2>
          <p className="text-gray-600 text-base sm:text-lg">
            Discover moments from workshops, projects, and community events.
          </p>
        </div>
        
        {filteredContent.length === 0 ? (
          <div className="text-center py-12">
            <h3 className="text-lg font-medium text-gray-900 mb-2">No content found</h3>
            <p className="text-gray-600">Try adjusting your search or filter selection.</p>
          </div>
        ) : (
          /* Photo Gallery Grid - Image Focused */
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-3 sm:gap-4">
            {filteredContent.map((item, index) => (
              <div 
                key={item.id} 
                className="group cursor-pointer animate-fadeIn relative overflow-hidden rounded-lg shadow-md hover:shadow-xl transition-shadow duration-300"
                style={{ animationDelay: `${index * 0.05}s` }}
                onClick={() => setSelectedImage(item)}
              >
                {/* Image */}
                <div className="relative aspect-square overflow-hidden bg-gray-100">
                  <img decoding="async"
                    src={item.image}
                    alt={item.title}
                    className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-500"
                    loading="lazy"
                  />
                  
                  {/* Hover Overlay with Title */}
                  <div className="absolute inset-0 bg-white from-black/70 via-black/20 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300">
                    <div className="absolute bottom-0 left-0 right-0 p-4">
                      <h3 className="text-white font-semibold text-sm sm:text-base leading-tight">
                        {item.title}
                      </h3>
                      <p className="text-white/80 text-xs mt-1">
                        {item.date}
                      </p>
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        )}
        
      </div>
    </section>

    {/* Lightbox Modal */}
    {selectedImage && (
      <div 
        className="fixed inset-0 bg-black/90 z-50 flex items-center justify-center p-4 animate-fadeIn"
        onClick={() => setSelectedImage(null)}
      >
        <div 
          className="relative max-w-4xl w-full max-h-[90vh] flex flex-col"
          onClick={(e) => e.stopPropagation()}
        >
          {/* Close Button */}
          <button
            onClick={() => setSelectedImage(null)}
            className="absolute -top-10 right-0 text-white hover:text-gray-300 transition-colors text-2xl font-bold"
          >
            Γ£ò
          </button>

          {/* Image */}
          <div className="flex-1 flex items-center justify-center overflow-hidden rounded-lg">
            <img decoding="async"
              src={selectedImage.image}
              alt={selectedImage.title}
              className="max-w-full max-h-full object-contain"
            />
          </div>

          {/* Image Info */}
          <div className="bg-black/50 text-white p-4 mt-4 rounded-lg">
            <h3 className="text-lg font-semibold">{selectedImage.title}</h3>
            <p className="text-sm text-gray-300 mt-1">{selectedImage.date}</p>
          </div>
        </div>
      </div>
    )}
    
    {/* Animation Styles */}
    <style jsx>{`
      @keyframes fadeIn {
        from {
          opacity: 0;
          transform: translateY(20px);
        }
        to {
          opacity: 1;
          transform: translateY(0);
        }
      }
      
      .animate-fadeIn {
        animation: fadeIn 0.5s ease-out forwards;
        opacity: 0;
      }
    `}</style>
    </>
  );
};

export default OrganizedContentGrid;

import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import heroService from '../../../services/heroService';

const Hero = () => {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [slides, setSlides] = useState([]);
  const [loading, setLoading] = useState(true);

  const preloadImage = (src) => {
    return new Promise((resolve) => {
      const img = new Image();
      img.src = src;
      img.onload = resolve;
      img.onerror = resolve; // Ignore errors for preloading
    });
  };

  useEffect(() => {
    const fetchSlides = async () => {
      try {
        // Γ£à Use PUBLIC endpoint for public site (no authentication)
        const response = await heroService.getPublicSlides();
        const visibleSlides = response.data.filter(s => s.isVisible);
        if (visibleSlides.length > 0) {
          setSlides(visibleSlides);
        }
      } catch (error) {
        console.error('Failed to fetch hero slides:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchSlides();
  }, []);

  // Auto-rotate slides
  useEffect(() => {
    if (slides.length <= 1) return;

    // Preload next image
    const nextIndex = (currentSlide + 1) % slides.length;
    preloadImage(slides[nextIndex].backgroundImage);

    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % slides.length);
    }, 5000); // Change slide every 5 seconds

    return () => clearInterval(timer);
  }, [slides.length, currentSlide]);

  // Show skeleton while loading
  if (loading || slides.length === 0) {
    return (
      <section className="relative w-full text-white overflow-hidden" style={{ height: 'calc(100vh - 88px)' }}>
        {/* Skeleton Background */}
        <div className="absolute inset-0 bg-gradient-to-r from-gray-300 via-gray-200 to-gray-300 animate-pulse"></div>
        
        {/* Skeleton Content */}
        <div className="relative z-10 w-full h-full flex items-center justify-start px-6 md:px-16 lg:px-24 pt-20 pb-20">
          <div className="max-w-5xl w-full space-y-6">
            {/* Skeleton Title */}
            <div className="space-y-4">
              <div className="h-16 md:h-20 bg-gray-400 rounded-lg animate-pulse w-3/4"></div>
              <div className="h-6 md:h-8 bg-gray-400 rounded-lg animate-pulse w-2/3"></div>
            </div>
            
            {/* Skeleton Description */}
            <div className="space-y-3 max-w-2xl">
              <div className="h-4 bg-gray-400 rounded animate-pulse"></div>
              <div className="h-4 bg-gray-400 rounded animate-pulse"></div>
              <div className="h-4 bg-gray-400 rounded animate-pulse w-4/5"></div>
            </div>
            
            {/* Skeleton Buttons */}
            <div className="flex gap-4 pt-4">
              <div className="h-12 bg-gray-400 rounded-lg animate-pulse w-40"></div>
              <div className="h-12 bg-gray-400 rounded-lg animate-pulse w-40"></div>
            </div>
          </div>
        </div>

        {/* Skeleton Dots */}
        <div className="absolute bottom-12 left-6 md:left-16 lg:left-24 z-20 flex gap-2">
          {[...Array(4)].map((_, i) => (
            <div key={i} className="h-1.5 bg-gray-400 rounded-full animate-pulse" style={{ width: i === 0 ? '32px' : '16px' }}></div>
          ))}
        </div>
      </section>
    );
  }

  const slide = slides[currentSlide];

  // Guard against null backgroundImage
  if (!slide?.backgroundImage) {
    return null;
  }

  // Helper to convert ALL CAPS to Title Case (and keep IT uppercase)
  const formatTitle = (title) => {
    if (!title) return '';
    if (title === title.toUpperCase()) {
      return title
        .toLowerCase()
        .split(' ')
        .map(word => {
          if (word === 'it') return 'IT';
          return word.charAt(0).toUpperCase() + word.slice(1);
        })
        .join(' ');
    }
    return title;
  };

  // Helper to shorten description to make it punchy like AmaliTech
  const formatDescription = (desc) => {
    if (!desc) return '';
    // If there's a period, cut it off after the first sentence
    const firstPeriod = desc.indexOf('.');
    if (firstPeriod > -1 && firstPeriod < desc.length - 1) {
      return desc.substring(0, firstPeriod + 1);
    }
    return desc;
  };

  return (
    <section className="relative w-full text-white overflow-hidden" style={{ height: 'calc(100vh - 88px)' }}>
      {/* Background Image - NO ANIMATION, INSTANT SWAP */}
      <div className="absolute inset-0 overflow-hidden">
        <img
          key={currentSlide}
          decoding="async"
          src={slide.backgroundImage}
          alt={slide.pillar}
          className="absolute inset-0 w-full h-full object-cover object-center"
          loading="eager"
          onError={(e) => {
            e.target.src = "/images/hero2.webp";
          }}
        />

        {/* Overlay - Light gradient from left to dark for text readability ONLY */}
        <div className="absolute inset-0 bg-gradient-to-r from-black/25 via-black/10 to-transparent"></div>
      </div>

      {/* Content with animations - Left aligned */}
      <div className="relative z-10 w-full h-full flex items-center justify-start px-6 md:px-16 lg:px-24 pt-20 pb-20">
        {/* Motion container with key to re-trigger animation on slide change */}
        <motion.div
          key={currentSlide}
          className="max-w-5xl w-full"
          initial={{ opacity: 0, x: -20 }}
          animate={{ opacity: 1, x: 0 }}
          transition={{ duration: 0.6 }}
        >
          {/* Main Headline */}
          <motion.h1
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0 }}
            className="text-4xl md:text-5xl lg:text-6xl xl:text-7xl font-bold leading-tight mb-4 tracking-tight text-white"
            style={{
              textShadow: '2px 2px 8px rgba(0,0,0,0.5)',
            }}
          >
            {formatTitle(slide.title)}
          </motion.h1>

          {/* Pillar (Sub-heading) */}
          {slide.pillar && (
            <motion.h3
              initial={{ opacity: 0, y: 20 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: 0.1 }}
              className="text-lg md:text-xl font-bold text-white mb-3"
              style={{
                textShadow: '1px 1px 4px rgba(0,0,0,0.5)',
              }}
            >
              {formatTitle(slide.pillar)}
            </motion.h3>
          )}

          {/* Description */}
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.2 }}
            className="text-base md:text-lg lg:text-xl font-normal text-gray-200 mb-8 leading-relaxed max-w-2xl"
            style={{
              textShadow: '1px 1px 4px rgba(0,0,0,0.5)',
            }}
          >
            {formatDescription(slide.description)}
          </motion.p>

          {/* CTA Buttons */}
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.6, delay: 0.3 }}
            className="flex flex-col sm:flex-row gap-4 md:gap-6 mb-8"
          >
            {slide.cta1Text && (
              <Link
                to={slide.cta1Link || '#'}
                className="bg-[#004fa2] hover:bg-[#003b7a] text-white px-8 py-3.5 rounded text-base md:text-lg font-medium transition-all duration-300 transform hover:-translate-y-1 inline-flex items-center justify-center shadow-lg"
              >
                {slide.cta1Text}
              </Link>
            )}

            {slide.cta2Text && (
              <Link
                to={slide.cta2Link || '#'}
                className="bg-white/10 hover:bg-white/20 backdrop-blur-sm border border-white/30 text-white px-8 py-3.5 rounded text-base md:text-lg font-medium transition-all duration-300 transform hover:-translate-y-1 inline-flex items-center justify-center"
              >
                {slide.cta2Text}
              </Link>
            )}
          </motion.div>
        </motion.div>
      </div>

      {/* Slideshow Controls (Dots) - Bottom left */}
      <div className="absolute bottom-12 left-6 md:left-16 lg:left-24 z-20">
        {/* Dots */}
        <div className="flex items-center gap-2">
          {slides.map((_, index) => (
            <button
              key={index}
              onClick={() => setCurrentSlide(index)}
              className={`transition-all duration-300 rounded-full ${
                index === currentSlide
                  ? 'bg-[#004fa2] w-8 h-1.5 shadow-lg'
                  : 'bg-white/40 w-4 h-1.5 hover:bg-white/70'
              }`}
              aria-label={`Go to slide ${index + 1}`}
            />
          ))}
        </div>
      </div>
    </section>
  );
};

export default Hero;

import React, { useState, useEffect, useRef } from 'react';
import { Users, Recycle, Lightbulb, Globe, DollarSign, BookOpen, Briefcase, Award } from 'lucide-react';
import { motion } from 'framer-motion';
import { useScrollAnimation } from '../../../hooks/useScrollAnimation';
import impactService from '../../../services/impactService';

const ImpactStats = () => {
  const [isVisible, setIsVisible] = useState(false);
  const [animatedNumbers, setAnimatedNumbers] = useState({});
  const [stats, setStats] = useState([]);
  const [loading, setLoading] = useState(true);
  const sectionRef = useRef();
  const titleAnimation = useScrollAnimation({ type: 'slideUp', delay: 0 });

  // Icon mapping helper
  const getIconForCategory = (category, title) => {
    const lowerTitle = title?.toLowerCase() || '';

    if (category === 'students' || lowerTitle.includes('student')) return Users;
    if (category === 'partnerships' || lowerTitle.includes('partner')) return Recycle; // Using Recycle as in original or Handshake
    if (category === 'projects' || lowerTitle.includes('project')) return Globe;
    if (category === 'financial' || lowerTitle.includes('fee')) return DollarSign;
    if (category === 'courses') return BookOpen;
    if (category === 'employment') return Briefcase;
    if (category === 'awards') return Award;
    return Lightbulb; // Default
  };

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const metrics = await impactService.fetchMetricsByLocation('home');

        const formattedStats = metrics.map(m => ({
          icon: getIconForCategory(m.category, m.title),
          number: typeof m.value === 'number' ? m.value : parseFloat(m.value) || 0,
          displayValue: m.value, // Keep original value for text types
          isNumeric: typeof m.value === 'number',
          suffix: m.suffix || '',
          prefix: m.prefix || '',
          label: m.title,
          color: '#004fa2' // Default color
        }));

        setStats(formattedStats);
      } catch (error) {
        console.error('Failed to fetch impact stats:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, []);

  // Intersection Observer for scroll-triggered animation
  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting && !isVisible) {
          setIsVisible(true);
          startCountingAnimation();
        }
      },
      { threshold: 0.5 }
    );

    if (sectionRef.current) {
      observer.observe(sectionRef.current);
    }

    return () => observer.disconnect();
  }, [isVisible, stats]); // Add stats dependnecy

  // Animated number counting
  const startCountingAnimation = () => {
    stats.forEach((stat, index) => {
      if (stat.isNumeric && stat.number > 0) {
        let start = 0;
        const end = stat.number;
        const duration = 2000;
        const increment = end / (duration / 16);

        const timer = setInterval(() => {
          start += increment;
          if (start >= end) {
            start = end;
            clearInterval(timer);
          }

          setAnimatedNumbers(prev => ({
            ...prev,
            [index]: Math.floor(start)
          }));
        }, 16);
      }
    });
  };

  if (loading) return null; // Or a skeleton loader

  return (
    <section
      ref={sectionRef}
      className="py-12 bg-white from-gray-100 to-white"
    >
      <div className="max-w-6xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section Title */}
        <motion.div
          ref={titleAnimation.ref}
          initial={titleAnimation.initial}
          animate={titleAnimation.animate}
          variants={titleAnimation.variants}
          transition={titleAnimation.transition}
          className="text-left mb-8"
        >
          <h2 className="text-3xl sm:text-4xl lg:text-5xl font-extrabold text-black tracking-tight mb-4">
            Our Impact
          </h2>
          <p className="text-lg text-gray-600 max-w-2xl">
            We measure success not by numbers, but by transformation. Our achievements in education, internships, and professional services.
          </p>
        </motion.div>

        <motion.div
          className="grid grid-cols-2 lg:grid-cols-4 gap-3"
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, amount: 0.2 }}
          variants={{
            visible: {
              transition: {
                staggerChildren: 0.1
              }
            }
          }}
        >
          {stats.map((stat, index) => {
            const IconComponent = stat.icon;
            return (
              <motion.div
                key={index}
                variants={{
                  hidden: { opacity: 0, y: 20 },
                  visible: { opacity: 1, y: 0 }
                }}
                transition={{ duration: 0.5 }}
                className="group relative bg-white p-3 sm:p-4 rounded-xl border border-gray-100 shadow-md hover:shadow-lg transition-all duration-300 hover:-translate-y-1 overflow-hidden"
              >
                {/* Gradient background on hover */}
                <div
                  className="absolute inset-0 opacity-0 group-hover:opacity-5 transition-opacity duration-300"
                  style={{ background: `linear-gradient(135deg, ${stat.color}20, ${stat.color}10)` }}
                ></div>

                {/* Content */}
                <div className="flex items-center space-x-2 sm:space-x-3 relative z-10">
                  <div
                    className="w-9 h-9 sm:w-10 sm:h-10 rounded-lg flex items-center justify-center group-hover:scale-105 transition-transform duration-300 bg-gray-50 group-hover:bg-gray-100 flex-shrink-0"
                  >
                    <IconComponent
                      size={20}
                      className="sm:w-6 sm:h-6"
                      style={{ color: stat.color }}
                    />
                  </div>
                  <div className="flex-1 min-w-0">
                    <div className="flex items-baseline space-x-1">
                      <span
                        className="text-xl sm:text-xl md:text-2xl font-extrabold leading-tight truncate"
                        style={{ color: stat.color }}
                      >
                        {stat.prefix}
                        {stat.isNumeric ? (isVisible ? (animatedNumbers[index] || 0) : 0) : stat.displayValue}
                      </span>
                      {stat.isNumeric && stat.suffix && (
                        <span
                          className="text-base sm:text-lg md:text-xl font-bold"
                          style={{ color: stat.color }}
                        >
                          {stat.suffix}
                        </span>
                      )}
                    </div>
                    <div className="text-xs sm:text-sm md:text-sm font-semibold text-black mt-0.5 sm:mt-1 leading-tight line-clamp-2">
                      {stat.label}
                    </div>
                  </div>
                </div>
              </motion.div>
            );
          })}
        </motion.div>

        {/* Partner CTA */}
        <div className="flex justify-center mt-8">
          <a
            href="/partner"
            className="bg-gradient-to-r from-[#004fa2] to-[#003a7a] hover:from-[#003a7a] hover:to-[#002855] text-white font-bold text-base px-8 py-4 rounded-lg shadow-lg hover:shadow-xl transition-all duration-300 hover:-translate-y-1 inline-flex items-center gap-2"
          >
            Support Our Mission
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 5l7 7-7 7" />
            </svg>
          </a>
        </div>
      </div>
    </section>
  );
};

export default ImpactStats;

