const LoginPage = () => {
  // ΓöÇΓöÇΓöÇ All state declarations (hooks MUST come first, before any returns) ΓöÇΓöÇΓöÇ
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [rememberMe, setRememberMe] = useState(false);
  const [view, setView] = useState('login'); // 'login' | 'forgot' | 'change_password' | 'kyc' | '2fa'
  const [forgotEmail, setForgotEmail] = useState('');
  const [forgotSent, setForgotSent] = useState(false);
  const [forgotLoading, setForgotLoading] = useState(false);
  const [forgotError, setForgotError] = useState(null);
  const [twoFactorCode, setTwoFactorCode] = useState('');
  const [twoFactorLoading, setTwoFactorLoading] = useState(false);
  const [twoFactorError, setTwoFactorError] = useState(null);
  const [loginSuccess, setLoginSuccess] = useState(false);

  const dispatch = useDispatch();
  const navigate = useNavigate();
  const {
    user, loading, error, isAuthenticated,
    passwordChangeLoading, passwordChangeError,
    kycLoading, kycError
  } = useSelector((state) => state.auth);

  // ΓöÇΓöÇΓöÇ Load remembered email (hook MUST be before any conditional returns) ΓöÇΓöÇΓöÇ
  useEffect(() => {
    const remembered = localStorage.getItem('zyra_remember_email');
    if (remembered) {
      setEmail(remembered);
      setRememberMe(true);
    }
  }, []);

  // ΓöÇΓöÇΓöÇ After login, check if we need password change or KYC ΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (isAuthenticated && user && view === 'login') {
      if (user.mustChangePassword) {
        setView('change_password');
      } else if (user.role !== 'super_admin' && (user.kycStatus === 'not_submitted' || user.kycStatus === 'rejected')) {
        setView('kyc');
      } else {
        setLoginSuccess(true);
      }
    }
  }, [isAuthenticated, user, view]);

  // ΓöÇΓöÇΓöÇ Navigate to dashboard when everything is ready ΓöÇΓöÇΓöÇ
  useEffect(() => {
    if (loginSuccess) {
      const timer = setTimeout(() => {
        navigate('/admin/dashboard');
      }, 800);
      return () => clearTimeout(timer);
    }
  }, [loginSuccess, navigate]);

  // ΓöÇΓöÇΓöÇ Handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const handleLogin = async (e) => {
    e.preventDefault();

    if (rememberMe) {
      localStorage.setItem('zyra_remember_email', email);
    } else {
      localStorage.removeItem('zyra_remember_email');
    }

    const result = await dispatch(loginUser({ email, password }));
    if (result.payload && !result.error) {
      if (result.payload.requires2FA) {
        setView('2fa');
        return;
      }
      const loggedUser = result.payload.user;

      // Determine next step based on user status
      if (loggedUser?.mustChangePassword) {
        setView('change_password');
      } else if (loggedUser?.role !== 'super_admin' && (loggedUser?.kycStatus === 'not_submitted' || loggedUser?.kycStatus === 'rejected')) {
        setView('kyc');
      } else {
        // Fully verified or super admin ΓÇö go to dashboard
        setLoginSuccess(true);
      }
    }
  };

  const handleTwoFactorSubmit = async (e) => {
    e.preventDefault();
    setTwoFactorLoading(true);
    setTwoFactorError(null);
    const result = await dispatch(verify2FACode({ code: twoFactorCode }));
    setTwoFactorLoading(false);
    if (result.payload && !result.error) {
      const loggedUser = result.payload.user;
      if (loggedUser?.mustChangePassword) {
        setView('change_password');
      } else if (loggedUser?.role !== 'super_admin' && (loggedUser?.kycStatus === 'not_submitted' || loggedUser?.kycStatus === 'rejected')) {
        setView('kyc');
      } else {
        setLoginSuccess(true);
      }
    } else {
      setTwoFactorError(result.payload || 'Invalid verification code.');
    }
  };

  const handlePasswordChange = async ({ currentPassword, newPassword }) => {
    const result = await dispatch(changePassword({ currentPassword, newPassword }));
    if (result.payload && !result.error) {
      // Password changed ΓÇö now check KYC
      const updatedUser = result.payload.user;
      if (updatedUser?.role !== 'super_admin' && (updatedUser?.kycStatus === 'not_submitted' || updatedUser?.kycStatus === 'rejected')) {
        setView('kyc');
      } else {
        setLoginSuccess(true);
      }
    }
  };

  const handleKycSubmit = async (formDataOrFiles) => {
    let formData = formDataOrFiles;
    if (!(formDataOrFiles instanceof FormData)) {
      formData = new FormData();
      if (formDataOrFiles.governmentId) formData.append('documents', formDataOrFiles.governmentId);
      if (formDataOrFiles.proofOfAddress) formData.append('documents', formDataOrFiles.proofOfAddress);
    }
    const result = await dispatch(submitKyc(formData));
    if (result.payload && !result.error) {
      // KYC submitted ΓÇö allow user to proceed
      setLoginSuccess(true);
    }
  };

  const handleKycSkip = () => {
    setLoginSuccess(true);
  };

  const handleForgotPassword = async (e) => {
    e.preventDefault();
    setForgotLoading(true);
    setForgotError(null);
    try {
      await authService.forgotPassword(forgotEmail);
      
      // Send password reset email confirmation
      try {
        await emailNotificationService.sendPasswordResetEmail(forgotEmail);
      } catch (emailError) {
        console.error('Failed to send password reset email:', emailError);
        // Don't fail if email fails
      }

      setForgotSent(true);
    } catch (err) {
      setForgotError(err.userMessage || 'Failed to send reset instructions. Please check your email and try again.');
    } finally {
      setForgotLoading(false);
    }
  };

  const switchToForgot = () => {
    dispatch(clearError());
    setForgotError(null);
    setView('forgot');
    setForgotEmail(email);
    setForgotSent(false);
  };

  const switchToLogin = () => {
    dispatch(clearError());
    setTwoFactorError(null);
    setView('login');
  };

  // ΓöÇΓöÇΓöÇ Determine card title and icon based on current view ΓöÇΓöÇΓöÇ
  const getCardHeader = () => {
    switch (view) {
      case '2fa':
        return { title: 'Security Verification', subtitle: 'Enter your 6-digit authentication code', icon: <ShieldCheck size={24} className="text-[#004fa2]" />, iconBg: 'bg-blue-50' };
      case 'change_password':
        return { title: 'Password Required', subtitle: 'Set a new secure password to continue', icon: <KeyRound size={24} className="text-amber-600" />, iconBg: 'bg-amber-50' };
      case 'kyc':
        return { title: 'Identity Verification', subtitle: 'Complete KYC to verify your account', icon: <IdCard size={24} className="text-blue-600" />, iconBg: 'bg-blue-50' };
      case 'forgot':
        return { title: 'Reset Password', subtitle: 'Enter your email to receive reset instructions', icon: <KeyRound size={24} className="text-amber-600" />, iconBg: 'bg-amber-50' };
      default:
        return { title: 'Welcome Back', subtitle: 'Sign in to access your admin dashboard', icon: <Lock size={24} className="text-[#004fa2]" />, iconBg: 'bg-blue-50' };
    }
  };

  // ΓöÇΓöÇΓöÇ Success Overlay ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  if (loginSuccess) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-[#004fa2]">
        <div className="text-center animate-[fadeIn_0.4s_ease-out]">
          <div className="mx-auto w-24 h-24 bg-white/20 backdrop-blur-sm rounded-full flex items-center justify-center mb-6 animate-[pulse_1s_ease-in-out_infinite]">
            <CheckCircle size={48} className="text-white" />
          </div>
          <h2 className="text-2xl font-bold text-white mb-2">Welcome Back!</h2>
          <p className="text-blue-200">Redirecting to your dashboard...</p>
          <div className="mt-6 flex justify-center">
            <div className="w-48 h-1 bg-white/20 rounded-full overflow-hidden">
              <div className="h-full bg-white rounded-full animate-[progressBar_0.8s_ease-in-out_forwards]" />
            </div>
          </div>
        </div>
      </div>
    );
  }

  const cardHeader = getCardHeader();

  return (
    <div className="min-h-screen relative overflow-hidden flex flex-col lg:flex-row items-center justify-center p-4">
      {/* ΓöÇΓöÇΓöÇ Background ΓöÇΓöÇΓöÇ */}
      <div className="absolute inset-0 bg-gradient-to-br from-[#001a3d] via-[#003068] to-[#004fa2]" />
      <div className="absolute top-0 left-0 w-full h-full bg-[radial-gradient(ellipse_at_top_left,rgba(0,79,162,0.4),transparent_60%)]" />
      <div className="absolute bottom-0 right-0 w-full h-full bg-[radial-gradient(ellipse_at_bottom_right,rgba(56,189,248,0.15),transparent_60%)]" />
      <ParticlesBackground />

      {/* ΓöÇΓöÇΓöÇ Logo: Stacked on Mobile, Absolute on Desktop ΓöÇΓöÇΓöÇ */}

      {/* Mobile Logo (Stacked) */}
      <div className="lg:hidden w-full flex justify-center mb-8 relative z-20">
        <img decoding="async"
          src="/zyrateclogopng.webp"
          alt="ZyraTech Hub"
          loading="eager"
          fetchPriority="high"
          className="h-24 w-auto object-contain drop-shadow-lg"
        />
      </div>

      {/* Desktop Logo (Absolute Top-Left) */}
      <div className="hidden lg:flex absolute top-8 left-8 z-20 items-center gap-3 transition-all duration-500">
        <img decoding="async"
          src="/zyrateclogopng.webp"
          alt="ZyraTech Hub"
          loading="eager"
          fetchPriority="high"
          className="h-48 w-auto object-contain drop-shadow-lg transition-all duration-500"
        />
      </div>

      {/* ΓöÇΓöÇΓöÇ Centered Login Card ΓöÇΓöÇΓöÇ */}
      <div className="w-full max-w-lg relative z-10">
        {/* Card */}
        <div
          className="bg-white/95 backdrop-blur-xl rounded-2xl md:rounded-3xl shadow-2xl shadow-black/20 overflow-hidden"
          style={{ animation: 'cardEntrance 0.6s cubic-bezier(0.16, 1, 0.3, 1) forwards' }}
        >
          {/* Card Header */}
          <div className="px-6 py-8 md:px-10 md:pt-10 md:pb-3">
            <div className="flex items-center justify-between mb-1.5">
              <h2 className="text-2xl md:text-3xl font-black text-gray-900 transition-all">{cardHeader.title}</h2>
              <div className={`w-6 h-6 md:w-8 md:h-8 md:w-12 md:h-12 ${cardHeader.iconBg} rounded-xl flex items-center justify-center transition-all`}>
                {cardHeader.icon}
              </div>
            </div>
            <p className="text-gray-500 text-[11px] md:text-base transition-all">{cardHeader.subtitle}</p>
          </div>

          {/* Card Body */}
          <div className="px-6 pb-8 md:px-10 md:py-8">
            {view === 'login' && (
              <LoginView
                onSubmit={handleLogin}
                email={email}
                setEmail={setEmail}
                password={password}
                setPassword={setPassword}
                showPassword={showPassword}
                setShowPassword={setShowPassword}
                rememberMe={rememberMe}
                setRememberMe={setRememberMe}
                loading={loading}
                error={error}
                onForgotPassword={switchToForgot}
              />
            )}

            {view === '2fa' && (
              <TwoFactorView
                onBack={switchToLogin}
                onSubmit={handleTwoFactorSubmit}
                code={twoFactorCode}
                setCode={setTwoFactorCode}
                loading={twoFactorLoading}
                error={twoFactorError}
              />
            )}

            {view === 'forgot' && (
              <ForgotPasswordView
                onBack={switchToLogin}
                onSubmit={handleForgotPassword}
                email={forgotEmail}
                setEmail={setForgotEmail}
                loading={forgotLoading}
                sent={forgotSent}
                error={forgotError}
              />
            )}

            {view === 'change_password' && (
              <ChangePasswordView
                user={user}
                onSubmit={handlePasswordChange}
                loading={passwordChangeLoading}
                error={passwordChangeError}
              />
            )}

            {view === 'kyc' && (
              <KycView
                user={user}
                kycStatus={user?.kycStatus}
                onSubmit={handleKycSubmit}
                onSkip={handleKycSkip}
                loading={kycLoading}
                error={kycError}
              />
            )}
          </div>

          {/* Card Footer */}
          <div className="px-6 py-4 md:px-10 md:py-5 bg-gray-50/80 border-t border-gray-100">
            <div className="flex items-center justify-center gap-2 text-xs md:text-sm text-gray-400">
              <Lock size={14} />
              <span>Protected by 256-bit SSL encryption</span>
            </div>
          </div>
        </div>

        {/* Bottom text */}
        <div className="mt-6 text-center text-sm text-blue-300/60">
          <p>┬⌐ 2026 ZyraTech</p>
        </div>
      </div>

      {/* ΓöÇΓöÇΓöÇ Custom Animations ΓöÇΓöÇΓöÇ */}
      <style>{`
        @keyframes cardEntrance {
          from { opacity: 0; transform: translateY(20px) scale(0.98); }
          to { opacity: 1; transform: translateY(0) scale(1); }
        }
        @keyframes slideDown {
          from { opacity: 0; transform: translateY(-8px); }
          to { opacity: 1; transform: translateY(0); }
        }
        @keyframes fadeIn {
          from { opacity: 0; }
          to { opacity: 1; }
        }
        @keyframes progressBar {
          from { width: 0%; }
          to { width: 100%; }
        }
      `}</style>
    </div>
  );
};

export default LoginPage;

/**
 * Password Reset Page
 * Users click the reset link from their email and land here to set a new password
 * 
 * URL: /reset-password?token=ABC123...
 */

import React, { useState, useEffect } from 'react';
import { useSearchParams, useNavigate, Link } from 'react-router-dom';
import { Lock, Eye, EyeOff, AlertCircle, CheckCircle, Loader2, ArrowLeft } from 'lucide-react';
import { useDispatch } from 'react-redux';
import { addNotification } from '../../store/slices/uiSlice';
import authService from '../../services/authService';
import useSEO from '../../hooks/useSEO';

const ResetPasswordPage = () => {
  useSEO({
    title: 'Reset Your Password',
    description: 'Set a new password for your ZyraTech Hub account.',
    url: '/reset-password',
    keywords: 'reset password, forgot password, account recovery'
  });

  const navigate = useNavigate();
  const dispatch = useDispatch();
  const [searchParams] = useSearchParams();
  const token = searchParams.get('token');

  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState(false);
  const [errors, setErrors] = useState({});

  // Password validation
  const validatePassword = (pwd) => {
    const newErrors = {};

    if (!pwd) {
      newErrors.password = 'Password is required';
    } else if (pwd.length < 8) {
      newErrors.password = 'Password must be at least 8 characters long';
    } else if (!/[A-Z]/.test(pwd)) {
      newErrors.password = 'Password must contain at least one uppercase letter';
    } else if (!/[a-z]/.test(pwd)) {
      newErrors.password = 'Password must contain at least one lowercase letter';
    } else if (!/[0-9]/.test(pwd)) {
      newErrors.password = 'Password must contain at least one number';
    } else if (!/[!@#$%^&*]/.test(pwd)) {
      newErrors.password = 'Password must contain at least one special character (!@#$%^&*)';
    }

    return newErrors;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErrors({});

    // Validate inputs
    const newErrors = validatePassword(password);

    if (!confirmPassword) {
      newErrors.confirmPassword = 'Please confirm your password';
    } else if (password !== confirmPassword) {
      newErrors.confirmPassword = 'Passwords do not match';
    }

    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      return;
    }

    if (!token) {
      dispatch(addNotification({
        message: 'Invalid or expired reset link. Please request a new password reset.',
        type: 'error'
      }));
      return;
    }

    setLoading(true);
    try {
      await authService.resetPassword(token, password);

      setSuccess(true);
      dispatch(addNotification({
        message: 'Your password has been reset successfully! Redirecting to login...',
        type: 'success'
      }));

      // Redirect to login after 2 seconds
      setTimeout(() => {
        navigate('/admin/login');
      }, 2000);
    } catch (error) {
      console.error('Password reset error:', error);
      const errorMessage = error.response?.data?.message || error.message || 'Failed to reset password. Please try again.';
      
      dispatch(addNotification({
        message: errorMessage,
        type: 'error'
      }));

      // If token is invalid/expired, show error and link to request new reset
      if (error.response?.status === 400 || error.response?.status === 401) {
        setErrors({
          general: 'This reset link is invalid or has expired. Please request a new password reset.'
        });
      }
    } finally {
      setLoading(false);
    }
  };

  // If no token, show error
  if (!token) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center px-4 py-12">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-xl p-8">
          <div className="flex justify-center mb-6">
            <div className="w-16 h-16 bg-red-100 rounded-full flex items-center justify-center">
              <AlertCircle className="w-8 h-8 text-red-600" />
            </div>
          </div>

          <h1 className="text-2xl font-bold text-gray-900 text-center mb-4">Invalid Reset Link</h1>
          <p className="text-gray-600 text-center mb-6">
            The password reset link is missing or invalid. Please request a new password reset from the login page.
          </p>

          <Link
            to="/admin/login"
            className="block w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-4 rounded-lg text-center transition-colors"
          >
            Go to Login
          </Link>
        </div>
      </div>
    );
  }

  // Success state
  if (success) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center px-4 py-12">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-xl p-8">
          <div className="flex justify-center mb-6">
            <div className="w-16 h-16 bg-green-100 rounded-full flex items-center justify-center">
              <CheckCircle className="w-8 h-8 text-green-600" />
            </div>
          </div>

          <h1 className="text-2xl font-bold text-gray-900 text-center mb-4">Password Reset Successful!</h1>
          <p className="text-gray-600 text-center mb-2">
            Your password has been reset successfully.
          </p>
          <p className="text-gray-600 text-center mb-6">
            Redirecting to login page...
          </p>

          <Link
            to="/admin/login"
            className="block w-full bg-blue-600 hover:bg-blue-700 text-white font-semibold py-3 px-4 rounded-lg text-center transition-colors"
          >
            Go to Login Now
          </Link>
        </div>
      </div>
    );
  }

  // Reset form
  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100 flex items-center justify-center px-4 py-12">
      <div className="max-w-md w-full bg-white rounded-2xl shadow-xl p-8">
        {/* Header */}
        <div className="flex justify-between items-center mb-8">
          <h1 className="text-2xl font-bold text-gray-900">Reset Password</h1>
        </div>

        <p className="text-gray-600 text-sm mb-6">
          Enter a new password for your account. Make sure it's strong and unique.
        </p>

        {/* General Error */}
        {errors.general && (
          <div className="mb-6 p-4 bg-red-50 border border-red-200 rounded-lg flex gap-3">
            <AlertCircle className="w-5 h-5 text-red-600 flex-shrink-0 mt-0.5" />
            <p className="text-sm text-red-700">{errors.general}</p>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-5">
          {/* New Password */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              New Password
            </label>
            <div className="relative">
              <Lock className="absolute left-3 top-3.5 w-5 h-5 text-gray-400" />
              <input
                type={showPassword ? 'text' : 'password'}
                value={password}
                onChange={(e) => {
                  setPassword(e.target.value);
                  if (errors.password) {
                    const newErrors = { ...errors };
                    delete newErrors.password;
                    setErrors(newErrors);
                  }
                }}
                placeholder="Enter new password"
                className={`w-full pl-10 pr-10 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all ${
                  errors.password ? 'border-red-300 bg-red-50' : 'border-gray-300'
                }`}
              />
              <button
                type="button"
                onClick={() => setShowPassword(!showPassword)}
                className="absolute right-3 top-3.5 text-gray-400 hover:text-gray-600"
              >
                {showPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
              </button>
            </div>
            {errors.password && (
              <p className="text-sm text-red-600 mt-1">{errors.password}</p>
            )}
          </div>

          {/* Confirm Password */}
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">
              Confirm Password
            </label>
            <div className="relative">
              <Lock className="absolute left-3 top-3.5 w-5 h-5 text-gray-400" />
              <input
                type={showConfirmPassword ? 'text' : 'password'}
                value={confirmPassword}
                onChange={(e) => {
                  setConfirmPassword(e.target.value);
                  if (errors.confirmPassword) {
                    const newErrors = { ...errors };
                    delete newErrors.confirmPassword;
                    setErrors(newErrors);
                  }
                }}
                placeholder="Confirm new password"
                className={`w-full pl-10 pr-10 py-3 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all ${
                  errors.confirmPassword ? 'border-red-300 bg-red-50' : 'border-gray-300'
                }`}
              />
              <button
                type="button"
                onClick={() => setShowConfirmPassword(!showConfirmPassword)}
                className="absolute right-3 top-3.5 text-gray-400 hover:text-gray-600"
              >
                {showConfirmPassword ? <EyeOff className="w-5 h-5" /> : <Eye className="w-5 h-5" />}
              </button>
            </div>
            {errors.confirmPassword && (
              <p className="text-sm text-red-600 mt-1">{errors.confirmPassword}</p>
            )}
          </div>

          {/* Password Requirements */}
          <div className="bg-blue-50 p-4 rounded-lg">
            <p className="text-xs font-medium text-gray-700 mb-2">Password must contain:</p>
            <ul className="text-xs text-gray-600 space-y-1">
              <li className={password.length >= 8 ? 'text-green-600' : ''}>
                Γ£ô At least 8 characters
              </li>
              <li className={/[A-Z]/.test(password) ? 'text-green-600' : ''}>
                Γ£ô At least one uppercase letter (A-Z)
              </li>
              <li className={/[a-z]/.test(password) ? 'text-green-600' : ''}>
                Γ£ô At least one lowercase letter (a-z)
              </li>
              <li className={/[0-9]/.test(password) ? 'text-green-600' : ''}>
                Γ£ô At least one number (0-9)
              </li>
              <li className={/[!@#$%^&*]/.test(password) ? 'text-green-600' : ''}>
                Γ£ô At least one special character (!@#$%^&*)
              </li>
            </ul>
          </div>

          {/* Submit Button */}
          <button
            type="submit"
            disabled={loading}
            className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-400 disabled:cursor-not-allowed text-white font-semibold py-3 px-4 rounded-lg transition-colors flex items-center justify-center gap-2 mt-6"
          >
            {loading ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" />
