                                <Copy size={14} />
                                Copy JSON
                            </button>
                            <button
                                onClick={() => setViewingLog(null)}
                                className="px-4 py-2 bg-[#004fa2] text-white rounded-lg hover:bg-[#003d7a] transition-colors font-medium text-sm"
                            >
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </AdminLayout>
    );
};

