                            <p>
                                Showing {((currentPage - 1) * itemsPerPage) + 1}├â┬ó├óΓÇÜ┬¼├óΓé¼┼ô{Math.min(currentPage * itemsPerPage, pagination.total)} of {pagination.total} articles
                            </p>
                            <div className="flex items-center gap-1.5">
                                <button
                                    onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
