/**
 * About Quote Management Page
 * Admin interface to manage the "About ZyraTech" quote and stats section on homepage
 */

import React, { useState, useEffect } from 'react';
import {
    Save,
    Quote,
    Loader,
    Image as ImageIcon
} from 'lucide-react';
import { useAuth } from '../../../hooks/useAuth';
import AdminLayout from '../../../components/admin/layout/AdminLayout';
import contentService from '../../../services/contentService';
import { useDispatch } from 'react-redux';
import { openConfirmDialog, addNotification } from '../../../store/slices/uiSlice';

const AboutQuoteManagementPage = () => {
    const dispatch = useDispatch();
    const { userPermissions, userRole } = useAuth();

    // Permission checks
    const canCreateContent = userRole === 'super_admin' || (userPermissions?.includes('content') ?? false);
    const handlePermissionDenied = () => {
        dispatch(addNotification({
            type: 'error',
            title: 'Permission Required',
            message: 'You do not have permission to manage this content.',
            description: 'Contact Super Admin at admin@zyratechhub.com',
            duration: 6000
        }));
    };
    const [loading, setLoading] = useState(true);
    const [saving, setSaving] = useState(false);
    const [uploading, setUploading] = useState(false);

    const [formData, setFormData] = useState({
        quote: '',
        authorName: '',
        authorTitle: '',
        authorImage: '',
        stat1Value: '',
        stat1Label: '',
        stat2Value: '',
        stat2Label: '',
        stat3Value: '',
        stat3Label: ''
    });

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const { data } = await contentService.getAboutQuote();
                console.log('├░┼╕ΓÇ£┼á AboutQuoteManagementPage - API response:', data); // DEBUG
                
                // API returns array, extract first item
                if (data && Array.isArray(data) && data.length > 0) {
                    console.log('├ó┼ôΓÇª Setting form from array:', data[0]); // DEBUG
                    setFormData(data[0]);
                } else if (data && !Array.isArray(data)) {
                    // Fallback: if data is already an object
                    console.log('├ó┼ôΓÇª Setting form from object:', data); // DEBUG
                    setFormData(data);
                }
            } catch (error) {
                console.error('Error fetching about quote data:', error);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, []);

    const handleChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setSaving(true);
        try {
            await contentService.updateAboutQuote(formData);
            dispatch(openConfirmDialog({
                title: 'Success',
                message: 'About section updated successfully.',
                confirmText: 'OK',
                hideCancelButton: true
            }));
        } catch (error) {
            console.error('Error updating about quote:', error);
        } finally {
            setSaving(false);
        }
    };

    const handleImageUpload = async (e) => {
        const file = e.target.files?.[0];
        if (!file) return;

        // File validation
        if (file.size > 5 * 1024 * 1024) {
            dispatch(openConfirmDialog({
                title: 'Error',
                message: 'File must be smaller than 5MB',
                confirmText: 'OK',
                hideCancelButton: true
            }));
            return;
        }

        try {
            setUploading(true);
            const imageUrl = await contentService.uploadImage(file);
            setFormData(prev => ({
                ...prev,
                authorImage: imageUrl
            }));
