} from 'lucide-react';
import { useAuth } from '../../../hooks/useAuth';
import AdminLayout from '../../../components/admin/layout/AdminLayout';
import contentService from '../../../services/contentService';
import { addNotification } from '../../../store/slices/uiSlice';
import { useActivityLogger } from '../../../hooks/useActivityLogger';
import LinkPicker from '../../../components/admin/common/LinkPicker';

const PartnershipStoryFormPage = () => {
    const dispatch = useDispatch();
    const { userPermissions, userRole } = useAuth();
    
    // Permission checks
    const canContent = userRole === 'super_admin' || (userPermissions?.includes('content') ?? false);

    const handlePermissionDenied = () => {
        dispatch(addNotification({
            type: 'error',
            title: 'Permission Required',
            message: 'You do not have permission to create or edit partnership stories.',
            description: 'Contact Super Admin at admin@zyratechhub.com',
            duration: 6000
        }));
    };
    const navigate = useNavigate();
    const { id } = useParams();
    const { logAction } = useActivityLogger();
    
    const [loading, setLoading] = useState(!!id);
    const [saving, setSaving] = useState(false);
    const [uploading, setUploading] = useState(false);
    const [formData, setFormData] = useState({
        title: '',
        category: '',
        description: '',
        impact: '',
        image: '',
        link: ''
    });
    const [error, setError] = useState(null);

    useEffect(() => {
        if (id) {
            fetchStory();
        }
    }, [id]);

    const fetchStory = async () => {
        try {
            setLoading(true);
            // contentService.getPartnershipStory already returns the story object directly
            const story = await contentService.getPartnershipStory(id);
            setFormData({
                title: story.title || '',
                category: story.category || '',
                description: story.description || '',
                impact: story.impact || '',
                image: story.image || '',
                link: story.link || ''
            });
        } catch (err) {
            console.error('Error fetching story:', err);
            setError('Failed to load story');
        } finally {
            setLoading(false);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleImageUpload = async (e) => {
        const file = e.target.files?.[0];
        if (!file) return;

        // Validate file type
        if (!file.type.startsWith('image/')) {
            setError('Please upload an image file');
            return;
        }

        // Validate file size (5MB max)
        if (file.size > 5 * 1024 * 1024) {
            setError('Image must be less than 5MB');
            return;
        }

        try {
            setUploading(true);
            setError(null);
            const imageUrl = await contentService.uploadImage(file);
            setFormData(prev => ({ ...prev, image: imageUrl }));
        } catch (err) {
            console.error('Upload error:', err);
            setError(err.message || 'Failed to upload image');
        } finally {
            setUploading(false);
        }
    };

    const removeImage = () => {
        setFormData(prev => ({ ...prev, image: '' }));
    };

    const handleSubmit = async (e) => {
        if (!canContent) { handlePermissionDenied(); return; }
        e.preventDefault();
        
        if (!formData.title.trim() || !formData.category.trim() || !formData.description.trim() || !formData.impact.trim()) {
            setError('Title, category, story, and impact are required');
            return;
        }

        if (!formData.image) {
            setError('Please upload a story image');
            return;
        }

        try {
            setSaving(true);
            setError(null);

            if (id) {
                await contentService.updatePartnershipStory(id, formData);
                logAction({
                    type: 'content_updated',
                    severity: 'info',
                    description: `Updated partnership story: "${formData.title}"`,
                    details: { contentType: 'PartnershipStory', contentId: id }
                });
            } else {
                await contentService.createPartnershipStory(formData);
                logAction({
                    type: 'content_created',
                    severity: 'success',
                    description: `Created new partnership story: "${formData.title}"`,
                    details: { contentType: 'PartnershipStory' }
                });
            }

            navigate('/admin/content/partnership');
        } catch (err) {
            console.error('Error saving story:', err);
            setError(err.message || 'Failed to save story');
        } finally {
            setSaving(false);
        }
    };

    return (
        <AdminLayout>
            <div className="max-w-2xl mx-auto">
                {/* Header */}
                <div className="flex items-center gap-4 mb-6">
                    <button
                        onClick={() => navigate('/admin/content/partnership')}
                        className="p-2 hover:bg-gray-100 rounded-lg transition-colors"
                        title="Go back"
                    >
                        <ArrowLeft size={24} className="text-gray-600" />
