    { value: 'DollarSign', label: 'Dollar Sign', icon: DollarSign }
];

const ServiceFormPage = () => {
    const dispatch = useDispatch();
    const { userPermissions, userRole } = useAuth();
    
    // Permission checks
    const canContent = userRole === 'super_admin' || (userPermissions?.includes('content') ?? false);

    const handlePermissionDenied = () => {
        dispatch(addNotification({
            type: 'error',
            title: 'Permission Required',
            message: 'You do not have permission to create or edit services.',
            description: 'Contact Super Admin at admin@zyratechhub.com',
            duration: 6000
        }));
    };
    const navigate = useNavigate();
    const { id } = useParams();
    const { logAction } = useActivityLogger();
    
    const [loading, setLoading] = useState(!!id);
    const [saving, setSaving] = useState(false);
    const [formData, setFormData] = useState({
        title: '',
        description: '',
        icon: 'Code2',
        highlights: ''
    });
    const [error, setError] = useState(null);

    useEffect(() => {
        if (id) {
            fetchService();
        }
    }, [id]);

    const fetchService = async () => {
        try {
            setLoading(true);
            // contentService.getService already returns the service object directly
            const service = await contentService.getService(id);
            setFormData({
                title: service.title || '',
                description: service.description || '',
                icon: service.icon || 'Code2',
                highlights: Array.isArray(service.highlights) ? service.highlights.join('\n') : ''
            });
        } catch (err) {
            console.error('Error fetching service:', err);
            setError('Failed to load service');
        } finally {
            setLoading(false);
        }
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: value
        }));
    };

    const handleSubmit = async (e) => {
        if (!canContent) { handlePermissionDenied(); return; }
        e.preventDefault();
        
        if (!formData.title.trim() || !formData.description.trim()) {
            setError('Title and description are required');
            return;
        }

        try {
            setSaving(true);
            setError(null);

            const apiData = {
                title: formData.title,
                description: formData.description,
                icon: formData.icon,
                highlights: formData.highlights.split('\n').filter(line => line.trim() !== '')
            };

            if (id) {
                await contentService.updateService(id, apiData);
                logAction({
                    type: 'content_updated',
                    severity: 'info',
                    description: `Updated service: "${apiData.title}"`,
                    details: { contentType: 'Service', contentId: id }
                });
