import { useDispatch } from 'react-redux';
import { addNotification } from '../../../store/slices/uiSlice';
import { useAuth } from '../../../hooks/useAuth';
import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import AdminLayout from '../../../components/admin/layout/AdminLayout';
import {
    ArrowLeft,
    Save,
    X,
    BarChart3,
    AlertCircle,
    TrendingUp,
    Star,
    Hash,
    Percent,
    DollarSign
} from 'lucide-react';
import impactService, { IMPACT_CATEGORIES, METRIC_TYPES, DISPLAY_LOCATIONS } from '../../../services/impactService';

const ImpactMetricFormPage = () => {
    const dispatch = useDispatch();
    const { userPermissions, userRole } = useAuth();
    
    // Permission checks
    const canImpact = userRole === 'super_admin' || (userPermissions?.includes('impact') ?? false);

    const handlePermissionDenied = () => {
        dispatch(addNotification({
            type: 'error',
            title: 'Permission Required',
            message: 'You do not have permission to create or edit impact metrics.',
            description: 'Contact Super Admin at admin@zyratechhub.com',
            duration: 6000
        }));
    };
    const { id } = useParams();
    const navigate = useNavigate();
    const isEditing = id && id !== 'new';

    const [metric, setMetric] = useState(null);
    const [loading, setLoading] = useState(isEditing);
    const [submitting, setSubmitting] = useState(false);
    const [errors, setErrors] = useState({});

    const [formData, setFormData] = useState({
        title: '',
        value: '',
        previousValue: '',
        type: 'number',
        category: 'students',
        description: '',
        suffix: '',
        prefix: '',
        featured: false,
        active: true,
        displayOrder: 0,
        displayLocations: [],
        trend: 'up'
    });

    // Load metric if editing
    useEffect(() => {
        if (isEditing) {
            const loadMetric = async () => {
                try {
                    const data = await impactService.fetchImpactMetric(id);
                    if (data) {
                        setMetric(data);
                        setFormData({
                            title: data.title,
                            value: data.value,
                            previousValue: data.previousValue || '',
                            type: data.type,
                            category: data.category,
                            description: data.description,
                            suffix: data.suffix || '',
                            prefix: data.prefix || '',
                            featured: data.featured,
                            active: data.active,
                            displayOrder: data.displayOrder || 0,
                            displayLocations: data.displayLocations || [],
                            trend: data.trend || 'up'
                        });
                    }
                } catch (error) {
                    console.error('Error loading metric:', error);
                    setErrors({ submit: 'Failed to load metric' });
                } finally {
                    setLoading(false);
                }
            };
            loadMetric();
        }
    }, [isEditing, id]);

    const validateForm = () => {
        const newErrors = {};

        if (!formData.title.trim()) newErrors.title = 'Title is required';
        if (formData.value === '') newErrors.value = 'Value is required';
        if (!formData.type) newErrors.type = 'Metric type is required';
        if (!formData.category) newErrors.category = 'Category is required';
        if (!formData.description.trim()) newErrors.description = 'Description is required';
        if (!formData.displayLocations || formData.displayLocations.length === 0) {
            newErrors.displayLocations = 'Select at least one display location';
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

