    Save,
    Quote,
    AlertCircle,
    Star,
    Image as ImageIcon
} from 'lucide-react';
import impactService from '../../../services/impactService';

const ImpactStoryFormPage = () => {
    const dispatch = useDispatch();
    const { userPermissions, userRole } = useAuth();
    
    // Permission checks
    const canImpact = userRole === 'super_admin' || (userPermissions?.includes('impact') ?? false);

    const handlePermissionDenied = () => {
        dispatch(addNotification({
            type: 'error',
            title: 'Permission Required',
            message: 'You do not have permission to create or edit impact stories.',
            description: 'Contact Super Admin at admin@zyratechhub.com',
            duration: 6000
        }));
    };
    const { id } = useParams();
    const navigate = useNavigate();
    const isEditing = id && id !== 'new';

    const [story, setStory] = useState(null);
    const [loading, setLoading] = useState(isEditing);
    const [submitting, setSubmitting] = useState(false);
    const [errors, setErrors] = useState({});

    const [formData, setFormData] = useState({
        name: '',
        title: '',
        role: '',
        organization: '',
        location: '',
        quote: '',
        image: null,
        featured: false,
        active: true,
        datePublished: new Date().toISOString().split('T')[0]
    });

    // Load story if editing
    useEffect(() => {
        if (isEditing) {
            const loadStory = async () => {
                try {
                    const data = await impactService.fetchSuccessStory(id);
                    if (data) {
                        setStory(data);
                        setFormData({
                            name: data.name,
                            title: data.title || '',
                            role: data.role,
                            organization: data.organization || '',
                            location: data.location || '',
                            quote: data.quote,
                            image: data.image || null,
                            featured: data.featured ?? false,
                            active: data.active ?? true,
                            datePublished: data.datePublished || new Date().toISOString().split('T')[0]
                        });
                    }
                } catch (error) {
                    console.error('Error loading story:', error);
                    setErrors({ submit: 'Failed to load story' });
                } finally {
                    setLoading(false);
                }
            };
            loadStory();
        }
    }, [isEditing, id]);

    const validateForm = () => {
        const newErrors = {};

        if (!formData.name.trim()) newErrors.name = 'Full name is required';
        if (!formData.role.trim()) newErrors.role = 'Role/position is required';
        if (!formData.organization.trim()) newErrors.organization = 'Organization is required';
        if (!formData.location.trim()) newErrors.location = 'Location is required';
        if (!formData.quote.trim()) newErrors.quote = 'Quote/testimonial is required';
        if (formData.quote.length < 20) newErrors.quote = 'Quote should be at least 20 characters';

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleChange = (e) => {
        const { name, value, type, checked } = e.target;
        setFormData(prev => ({
            ...prev,
            [name]: type === 'checkbox' ? checked : (type === 'number' ? parseInt(value) : value)
        }));
        // Clear error for this field
        if (errors[name]) {
            setErrors(prev => ({ ...prev, [name]: '' }));
        }
    };

    const handleImageChange = (e) => {
        const file = e.target.files?.[0];
        if (file) {
            // In a real app, you'd upload the file to storage
            // For now, we'll just store the filename
            setFormData(prev => ({
                ...prev,
                image: file.name
            }));
        }
    };

    const handleSubmit = async (e) => {
        if (!canImpact) { handlePermissionDenied(); return; }
        e.preventDefault();

        if (!validateForm()) {
            return;
        }

        setSubmitting(true);
        try {
            if (isEditing) {
                await impactService.updateSuccessStory(id, formData);
            } else {
                await impactService.createSuccessStory(formData);
            }
            navigate('/admin/impact');
        } catch (error) {
            console.error('Error saving story:', error);
            setErrors({ submit: 'Failed to save story. Please try again.' });
        } finally {
            setSubmitting(false);
        }
    };

    if (loading) {
        return (
            <AdminLayout>
                <div className="flex items-center justify-center min-h-screen">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#004fa2]"></div>
                </div>
            </AdminLayout>
        );
    }

    return (
        <AdminLayout>
            <div className="max-w-4xl mx-auto pb-8">
                {/* Header */}
                <div className="flex items-center gap-3 mb-6">
