import { useParams, useNavigate } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { openConfirmDialog } from '../../../store/slices/uiSlice';
import AdminLayout from '../../../components/admin/layout/AdminLayout';
import jobsService from '../../../services/jobsService';
import {
    ChevronLeft,
    ChevronRight,
    Save,
    X,
    Plus,
    Trash2,
    Briefcase,
    FileText,
    MapPin,
    Users,
    Target,
    Zap,
    List,
    AlertCircle,
    Check,
    DollarSign
} from 'lucide-react';

// Job type options
const JOB_TYPES = [
    { value: 'Full-time', label: 'Full-time' },
    { value: 'Part-time', label: 'Part-time' },
    { value: 'Contract', label: 'Contract' },
    { value: 'Internship', label: 'Internship' },
    { value: 'National Service', label: 'National Service' },
    { value: 'Remote', label: 'Remote' }
];

// Step definitions
const STEPS = [
    { key: 'basic', title: 'Basic Info', icon: Briefcase },
    { key: 'details', title: 'Responsibilities & Qualifications', icon: List },
    { key: 'salary', title: 'Salary', icon: DollarSign },
    { key: 'locations', title: 'Benefits', icon: MapPin },
    { key: 'review', title: 'Review', icon: Check }
];

const JobFormPage = () => {
    const dispatch = useDispatch();
    const { userPermissions, userRole } = useAuth();
    
    // Permission checks
    const canJobs = userRole === 'super_admin' || (userPermissions?.includes('jobs') ?? false);

    const handlePermissionDenied = () => {
        dispatch(addNotification({
            type: 'error',
            title: 'Permission Required',
            message: 'You do not have permission to create or edit jobs.',
            description: 'Contact Super Admin at admin@zyratechhub.com',
            duration: 6000
        }));
    };
    const { id } = useParams();
    const navigate = useNavigate();
    

    const isEditing = Boolean(id);

    // Step state
    const [currentStep, setCurrentStep] = useState(0);
    const [isLoading, setIsLoading] = useState(isEditing);
    const [jobId, setJobId] = useState(id || null); // Track job ID for PATCH requests

    // Form state
    const [formData, setFormData] = useState({
        // Basic Info
        title: '',
        type: 'Full-time',
        description: '',
        department: 'Engineering',
        level: 'Junior',

        // Salary Range
        salaryMin: '',
        salaryMax: '',
        salaryCurrency: 'GHS',

        // Responsibilities and Qualifications (comma-separated for simplicity)
        responsibilitiesText: '',
        qualificationsText: '',

        // Locations and Perks (comma-separated)
        locationsText: '',
        perksText: ''
    });

    const [errors, setErrors] = useState({});
    const [isSaving, setIsSaving] = useState(false);

    // Load existing job data for editing
    useEffect(() => {
        if (isEditing) {
            let isMounted = true;
            const loadJob = async () => {
                try {
                    setIsLoading(true);
                    const job = await jobsService.getJob(id);
                    if (isMounted && job) {
                        setFormData({
                            title: job.title || '',
                            type: job.type || 'Full-time',
                            description: job.description || '',
                            jobDescription: job.jobDescription || '',
                            companyDescription: job.companyDescription || '',
                            responsibilitiesText: job.responsibilities?.join('\n') || '',
                            qualificationsText: job.qualifications?.join('\n') || '',
                            locationsText: job.locations?.join(', ') || '',
                            perksText: job.perks?.join('\n') || '',
                            salaryMin: job.salaryMin || '',
                            salaryMax: job.salaryMax || '',
                            salaryCurrency: job.salaryCurrency || 'GHS'
                        });
                    } else if (isMounted) {
                        console.error('Job not found');
                    }
                } catch (err) {
                    console.error('Failed to load job:', err);
                } finally {
                    if (isMounted) {
                        setIsLoading(false);
                    }
                }
            };
            loadJob();
            return () => { isMounted = false; };
        }
    }, [isEditing, id]);

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setFormData(prev => ({ ...prev, [name]: value }));
        // Clear error when user types
        if (errors[name]) {
            setErrors(prev => ({ ...prev, [name]: undefined }));
        }
    };

    // Save current step data using PATCH (or POST for first step)
    const saveStepData = async () => {
        const stepKey = STEPS[currentStep]?.key;
        let stepData = {};

        // Collect data for current step
        if (stepKey === 'basic') {
            stepData = {
                title: formData.title,
                type: formData.type,
                description: formData.description,
                department: formData.department || 'Engineering',
                level: formData.level || 'Junior',
                location: formData.locationsText.split(',')[0]?.trim() || 'Remote',
            };
        } else if (stepKey === 'details') {
            stepData = {
                requirements: formData.qualificationsText.split('\n').map(q => q.trim()).filter(Boolean),
                responsibilities: formData.responsibilitiesText.split('\n').map(r => r.trim()).filter(Boolean),
            };
        } else if (stepKey === 'salary') {
            stepData = {
                salary: formData.salaryMin && formData.salaryMax 
                    ? `${formData.salaryCurrency}${Number(formData.salaryMin).toLocaleString()} - ${formData.salaryCurrency}${Number(formData.salaryMax).toLocaleString()}`
                    : '',
            };
        } else if (stepKey === 'locations') {
            stepData = {
                benefits: formData.perksText.split('\n').map(p => p.trim()).filter(Boolean),
            };
        }

        try {
            if (!jobId && stepKey === 'basic') {
                // First step: Create new job
                console.log('├░┼╕ΓÇ£┬¥ Creating new job with Step 1 data:', stepData);
                const response = await jobsService.createJob({ ...stepData, status: 'draft' });
                const newJobId = response.id;
                setJobId(newJobId);
                console.log('├ó┼ôΓÇª Job created with ID:', newJobId);
            } else if (jobId) {
                // Subsequent steps: Update existing job with PATCH
                console.log(`├░┼╕ΓÇ£┬¥ Updating job ${jobId} with ${stepKey} data:`, stepData);
                await jobsService.updateJob(jobId, stepData);
                console.log(`├ó┼ôΓÇª Job ${jobId} updated successfully`);
            }
        } catch (error) {
            console.error(`Failed to save step data: ${stepKey}`, error);
            throw error;
        }
    };

    const validateStep = (stepIndex) => {
        const newErrors = {};
        const stepKey = STEPS[stepIndex]?.key;

        if (stepKey === 'basic') {
            if (!formData.title.trim()) newErrors.title = 'Job title is required';
            if (!formData.description.trim()) newErrors.description = 'Job description is required';
        }

        if (stepKey === 'details') {
            if (!formData.responsibilitiesText.trim()) newErrors.responsibilitiesText = 'At least one responsibility is required';
            if (!formData.qualificationsText.trim()) newErrors.qualificationsText = 'At least one qualification is required';
        }

        if (stepKey === 'locations') {
            if (!formData.locationsText.trim()) newErrors.locationsText = 'At least one location is required';
        }

        setErrors(newErrors);
        return Object.keys(newErrors).length === 0;
    };

    const handleNext = async () => {
        if (validateStep(currentStep)) {
            // Auto-save current step data before moving to next
            try {
                await saveStepData();
                setCurrentStep(prev => Math.min(prev + 1, STEPS.length - 1));
            } catch (error) {
                console.error('Failed to save step before proceeding:', error);
                dispatch(openConfirmDialog({
                    title: 'Save Error',
                    message: 'Failed to save your changes. Please try again.',
                    isDangerous: true,
                    confirmText: 'OK',
                    hideCancelButton: true
                }));
            }
        }
    };

    const handlePrev = () => {
        setCurrentStep(prev => Math.max(prev - 1, 0));
    };

    const handleSubmit = async () => {
        if (!canJobs) { handlePermissionDenied(); return; }
        // Validate all steps
        let hasErrors = false;
        for (let i = 0; i < STEPS.length - 1; i++) {
            if (!validateStep(i)) {
                hasErrors = true;
                setCurrentStep(i);
                break;
            }
        }

        if (hasErrors) return;

        setIsSaving(true);

        try {
            // If we haven't saved the job yet (not on review step with jobId), save all remaining steps
            if (!jobId) {
                console.log('├░┼╕ΓÇ£┬¥ First-time submission: Creating job with all data');
                const jobData = {
                    title: formData.title,
                    type: formData.type,
                    description: formData.description,
                    department: formData.department || 'Engineering',
                    level: formData.level || 'Junior',
                    location: formData.locationsText.split(',')[0]?.trim() || 'Remote',
                    requirements: formData.qualificationsText.split('\n').map(q => q.trim()).filter(Boolean),
                    responsibilities: formData.responsibilitiesText.split('\n').map(r => r.trim()).filter(Boolean),
                    benefits: formData.perksText.split('\n').map(p => p.trim()).filter(Boolean),
                    salary: formData.salaryMin && formData.salaryMax 
                        ? `${formData.salaryCurrency}${Number(formData.salaryMin).toLocaleString()} - ${formData.salaryCurrency}${Number(formData.salaryMax).toLocaleString()}`
                        : '',
                    status: 'draft'
                };
                const response = await jobsService.createJob(jobData);
                setJobId(response.id);
            } else {
                // Job exists, make final PATCH to set status to active
                console.log(`├░┼╕ΓÇ£┬¥ Final submission: Publishing job ${jobId}`);
                await jobsService.updateJob(jobId, { status: 'draft' });
            }

            setIsSaving(false);

            // Show success and navigate back
            dispatch(openConfirmDialog({
                title: isEditing ? 'Job Updated' : 'Job Created',
                message: isEditing
                    ? `"${formData.title}" has been updated successfully.`
                    : `"${formData.title}" has been posted successfully. You can publish it from the Jobs page.`,
                confirmText: 'OK',
                hideCancelButton: true,
                onConfirm: () => navigate('/admin/jobs')
            }));
        } catch (error) {
            setIsSaving(false);
            console.error('Failed to save job:', error);

            dispatch(openConfirmDialog({
                title: 'Error',
                message: `Failed to ${isEditing ? 'update' : 'create'} job. Please try again.`,
                isDangerous: true,
                confirmText: 'OK',
                hideCancelButton: true
            }));
        }
    };

    const handleCancel = () => {
        if (formData.title || formData.description) {
            dispatch(openConfirmDialog({
                title: 'Discard Changes?',
                message: 'You have unsaved changes. Are you sure you want to leave?',
                isDangerous: true,
                confirmText: 'Discard',
                onConfirm: () => navigate('/admin/jobs')
            }));
        } else {
            navigate('/admin/jobs');
        }
    };

    // If editing and loading
    if (isEditing && isLoading) {
        return (
            <AdminLayout>
                <div className="flex flex-col items-center justify-center min-h-[60vh]">
                    <div className="animate-spin">
                        <div className="w-12 h-12 border-4 border-gray-200 border-t-[#004fa2] rounded-full"></div>
                    </div>
                    <p className="text-gray-500 mt-4">Loading job...</p>
                </div>
            </AdminLayout>
        );
    }

    // Render step content
    const renderStepContent = () => {
        const stepKey = STEPS[currentStep]?.key;

        switch (stepKey) {
            case 'basic':
                return (
                    <div className="space-y-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Job Title <span className="text-red-500">*</span>
                            </label>
                            <input
                                type="text"
                                name="title"
                                value={formData.title}
                                onChange={handleInputChange}
                                placeholder="e.g., Senior Software Engineer"
                                className={`w-full px-4 py-3 border rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all ${errors.title ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                            />
                            {errors.title && <p className="text-red-500 text-sm mt-1">{errors.title}</p>}
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">Job Type</label>
                                <select
                                    name="type"
                                    value={formData.type}
                                    onChange={handleInputChange}
                                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all bg-white"
                                >
                                    {JOB_TYPES.map(type => (
                                        <option key={type.value} value={type.value}>{type.label}</option>
                                    ))}
                                </select>
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">Level</label>
                                <select
                                    name="level"
                                    value={formData.level}
                                    onChange={handleInputChange}
                                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all bg-white"
                                >
                                    <option value="Junior">Junior</option>
                                    <option value="Mid-level">Mid-level</option>
                                    <option value="Senior">Senior</option>
                                    <option value="Lead">Lead</option>
                                    <option value="Manager">Manager</option>
                                </select>
                            </div>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">Department</label>
                                <input
                                    type="text"
                                    name="department"
                                    value={formData.department}
                                    onChange={handleInputChange}
                                    placeholder="e.g., Engineering, Design, Sales"
                                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">Location</label>
                                <input
                                    type="text"
                                    name="locationsText"
                                    value={formData.locationsText}
                                    onChange={handleInputChange}
                                    placeholder="e.g., Accra, Kumasi, Remote"
                                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all"
                                />
                            </div>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">Job Description <span className="text-red-500">*</span></label>
                            <textarea
                                name="description"
                                value={formData.description}
                                onChange={handleInputChange}
                                rows={5}
                                placeholder="Detailed description of the position, responsibilities, and what the role entails"
                                className={`w-full px-4 py-3 border rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all resize-none ${errors.description ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                            />
                            {errors.description && <p className="text-red-500 text-sm mt-1">{errors.description}</p>}
                        </div>
                    </div>
                );

            case 'details':
                return (
                    <div className="space-y-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Key Responsibilities <span className="text-red-500">*</span>
                            </label>
                            <textarea
                                name="responsibilitiesText"
                                value={formData.responsibilitiesText}
                                onChange={handleInputChange}
                                rows={5}
                                placeholder="One responsibility per line. e.g.&#10;Develop and maintain software solutions&#10;Collaborate with team members&#10;Contribute to code reviews"
                                className={`w-full px-4 py-3 border rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all resize-none ${errors.responsibilitiesText ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                            />
                            {errors.responsibilitiesText && <p className="text-red-500 text-sm mt-1">{errors.responsibilitiesText}</p>}
                            <p className="text-xs text-gray-500 mt-2">Enter each responsibility on a new line</p>
                        </div>

                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">
                                Required Qualifications <span className="text-red-500">*</span>
                            </label>
                            <textarea
                                name="qualificationsText"
                                value={formData.qualificationsText}
                                onChange={handleInputChange}
                                rows={5}
                                placeholder="One qualification per line. e.g.&#10;Bachelor's degree in Computer Science&#10;2+ years of experience&#10;Strong problem-solving skills"
                                className={`w-full px-4 py-3 border rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all resize-none ${errors.qualificationsText ? 'border-red-300 bg-red-50' : 'border-gray-200'}`}
                            />
                            {errors.qualificationsText && <p className="text-red-500 text-sm mt-1">{errors.qualificationsText}</p>}
                            <p className="text-xs text-gray-500 mt-2">Enter each qualification on a new line</p>
                        </div>
                    </div>
                );

            case 'locations':
                return (
                    <div className="space-y-6">
                        <div>
                            <label className="block text-sm font-medium text-gray-700 mb-2">Perks & Benefits (Optional)</label>
                            <textarea
                                name="perksText"
                                value={formData.perksText}
                                onChange={handleInputChange}
                                rows={5}
                                placeholder="One perk per line. e.g.&#10;Competitive salary&#10;Health insurance&#10;Flexible work hours&#10;Professional development budget"
                                className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all resize-none"
                            />
                            <p className="text-xs text-gray-500 mt-2">Enter each perk on a new line</p>
                        </div>
                    </div>
                );

            case 'salary':
                return (
                    <div className="space-y-6">
                        <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 mb-6">
                            <p className="text-sm text-blue-800">
                                <span className="font-semibold">Transparency Matters:</span> Providing salary information helps attract qualified candidates and demonstrates your commitment to fair compensation.
                            </p>
                        </div>

                        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Minimum Salary (Optional)
                                </label>
                                <input
                                    type="number"
                                    name="salaryMin"
                                    value={formData.salaryMin}
                                    onChange={handleInputChange}
                                    placeholder="e.g., 2500"
                                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">
                                    Maximum Salary (Optional)
                                </label>
                                <input
                                    type="number"
                                    name="salaryMax"
                                    value={formData.salaryMax}
                                    onChange={handleInputChange}
                                    placeholder="e.g., 5000"
                                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all"
                                />
                            </div>

                            <div>
                                <label className="block text-sm font-medium text-gray-700 mb-2">Currency</label>
                                <select
                                    name="salaryCurrency"
                                    value={formData.salaryCurrency}
                                    onChange={handleInputChange}
                                    className="w-full px-4 py-3 border border-gray-200 rounded-xl focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all bg-white"
                                >
                                    <option value="GHS">GHS (Ghana Cedis)</option>
                                    <option value="USD">USD (US Dollars)</option>
                                    <option value="EUR">EUR (Euros)</option>
                                    <option value="GBP">GBP (British Pounds)</option>
                                </select>
                            </div>
                        </div>

                        <div className="bg-gray-50 rounded-xl p-4">
                            <h4 className="font-semibold text-gray-900 mb-2">Salary Display Preview</h4>
                            {formData.salaryMin && formData.salaryMax ? (
                                <p className="text-lg font-bold text-[#004fa2]">
                                    {formData.salaryCurrency} {Number(formData.salaryMin).toLocaleString()} - {Number(formData.salaryMax).toLocaleString()}
                                </p>
                            ) : formData.salaryMin || formData.salaryMax ? (
                                <p className="text-lg font-bold text-[#004fa2]">
                                    {formData.salaryCurrency} {Number(formData.salaryMin || formData.salaryMax).toLocaleString()}
                                </p>
                            ) : (
                                <p className="text-sm text-gray-500">Enter salary amounts to see preview</p>
                            )}
                        </div>
                    </div>
                );

            case 'review':
                return (
                    <div className="space-y-6">
                        <div className="bg-gradient-to-r from-[#004fa2]/5 to-[#0066cc]/5 rounded-xl p-6 border border-[#004fa2]/10">
                            <h3 className="font-bold text-gray-900 text-lg mb-4">Review Your Job Listing</h3>

                            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                                <div>
                                    <p className="text-xs text-gray-500 mb-1">Job Title</p>
                                    <p className="font-semibold text-gray-900">{formData.title || '-'}</p>
                                </div>
                                <div>
                                    <p className="text-xs text-gray-500 mb-1">Job Type</p>
                                    <p className="font-semibold text-gray-900">{formData.type || '-'}</p>
                                </div>
                            </div>

                            <div className="mt-6 pt-6 border-t border-gray-200">
                                <p className="text-xs text-gray-500 mb-2">Description</p>
                                <p className="text-sm text-gray-700 bg-white rounded-lg p-3">{formData.description || '-'}</p>
                            </div>

                            {formData.locationsText && (
                                <div className="mt-6 pt-6 border-t border-gray-200">
                                    <p className="text-xs text-gray-500 mb-2">Locations</p>
                                    <div className="flex flex-wrap gap-2">
                                        {formData.locationsText.split(',').map((loc, i) => (
                                            <span key={i} className="px-3 py-1 bg-[#004fa2]/10 text-[#004fa2] rounded-full text-sm font-medium">
                                                {loc.trim()}
                                            </span>
                                        ))}
                                    </div>
                                </div>
                            )}

                            {formData.responsibilitiesText && (
                                <div className="mt-6 pt-6 border-t border-gray-200">
                                    <p className="text-xs text-gray-500 mb-2">Key Responsibilities ({formData.responsibilitiesText.split('\n').filter(r => r.trim()).length})</p>
                                    <ul className="space-y-1">
                                        {formData.responsibilitiesText.split('\n').filter(r => r.trim()).slice(0, 3).map((resp, i) => (
                                            <li key={i} className="flex items-start gap-2 text-sm text-gray-700">
                                                <Check size={14} className="text-green-500 mt-0.5 flex-shrink-0" />
                                                {resp.trim()}
                                            </li>
                                        ))}
                                        {formData.responsibilitiesText.split('\n').filter(r => r.trim()).length > 3 && (
                                            <li className="text-sm text-gray-500">+{formData.responsibilitiesText.split('\n').filter(r => r.trim()).length - 3} more</li>
                                        )}
                                    </ul>
                                </div>
                            )}

                            {formData.perksText && (
                                <div className="mt-6 pt-6 border-t border-gray-200">
                                    <p className="text-xs text-gray-500 mb-2">Perks & Benefits ({formData.perksText.split('\n').filter(p => p.trim()).length})</p>
                                    <div className="flex flex-wrap gap-2">
                                        {formData.perksText.split('\n').filter(p => p.trim()).slice(0, 3).map((perk, i) => (
                                            <span key={i} className="px-2 py-1 bg-amber-50 text-amber-700 text-xs font-medium rounded-full">
                                                <Zap size={10} className="inline mr-1" />
                                                {perk.trim()}
                                            </span>
                                        ))}
                                        {formData.perksText.split('\n').filter(p => p.trim()).length > 3 && (
