                                    <p className="text-[11px] font-medium text-gray-800 line-clamp-1">{transaction.course}</p>
                                    <div className="flex items-center gap-2 mt-1">
                                        <span className={`inline-flex items-center gap-1 px-1.5 py-0.5 rounded text-[9px] font-medium ${methodConfig.color}`}>
                                            <span>{methodConfig.icon}</span> {methodConfig.label}
                                        </span>
                                        <span className="text-[9px] text-gray-400 font-mono tracking-wider">{formatDate(transaction.date)}</span>
                                    </div>
                                </div>

                                <div className="flex items-center justify-between xl:justify-end gap-4 xl:w-1/3 shrink-0">
                                    <div className="text-left xl:text-right">
                                        <p className={`text-sm font-black ${transaction.status === 'refunded' ? 'text-purple-600' : transaction.status === 'completed' ? 'text-green-600' : transaction.status === 'failed' ? 'text-red-500' : 'text-gray-900'}`}>
                                            {transaction.status === 'refunded' && '-'}
                                            {formatCurrency(transaction.amount, transaction.currency)}
                                        </p>
                                        <div className="mt-0.5">
                                            <StatusBadge status={transaction.status} />
                                        </div>
                                    </div>
                                    
                                    <div className="flex items-center gap-0.5 ml-2 border-l border-gray-100 pl-2">
                                        <button className="p-1.5 hover:bg-blue-50 rounded-lg text-gray-400 hover:text-[#004fa2] transition-colors"><Eye size={14} /></button>
                                        {transaction.status === 'completed' && (
                                            <button onClick={() => handleRefund(transaction)} className="p-1.5 hover:bg-purple-50 rounded-lg text-gray-400 hover:text-purple-600 transition-colors"><RefreshCcw size={14} /></button>
                                        )}
                                        <button className="p-1.5 hover:bg-gray-100 rounded-lg text-gray-400 hover:text-gray-900 transition-colors"><Receipt size={14} /></button>
                                    </div>
                                </div>
                            </div>
                        );
                    })}

                    {filteredTransactions.length === 0 && (
                        <div className="bg-white rounded-xl p-8 text-center border border-gray-100 shadow-sm">
                            <CreditCard className="mx-auto text-gray-300 mb-2" size={24} />
                            <h3 className="text-sm font-bold text-gray-900 mb-1">No transactions found</h3>
                            <button onClick={resetFilters} className="text-[11px] text-[#004fa2] hover:underline font-semibold mt-2">Clear filters</button>
                        </div>
                    )}
                </div>

                {/* Pagination */}
                {totalPages > 1 && (
                    <div className="flex flex-col sm:flex-row items-center justify-between bg-white rounded-xl p-3 shadow-sm border border-gray-100 gap-3 mt-4">
                        <p className="text-[10px] text-gray-500 uppercase tracking-widest font-semibold">
                            Showing <span className="text-gray-900">{(currentPage - 1) * itemsPerPage + 1}</span> to{' '}
                            <span className="text-gray-900">{Math.min(currentPage * itemsPerPage, filteredTransactions.length)}</span> of{' '}
                            <span className="text-gray-900">{filteredTransactions.length}</span>
                        </p>
                        <div className="flex items-center gap-1">
                            <button
                                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                                disabled={currentPage === 1}
                                className="p-1 text-gray-400 hover:text-[#004fa2] hover:bg-blue-50 rounded transition-colors disabled:opacity-40"
                            >
                                <ChevronLeft size={16} />
                            </button>
                            <div className="flex items-center gap-1">
                                {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                                    <button
                                        key={page}
                                        onClick={() => setCurrentPage(page)}
                                        className={`min-w-[24px] h-6 flex items-center justify-center rounded text-[10px] font-bold transition-all ${currentPage === page
                                            ? 'bg-[#004fa2] text-white shadow-sm'
                                            : 'text-gray-500 hover:bg-gray-100'
                                            }`}
                                    >
                                        {page}
                                    </button>
                                ))}
                            </div>
                            <button
                                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                                disabled={currentPage === totalPages}
                                className="p-1 text-gray-400 hover:text-[#004fa2] hover:bg-blue-50 rounded transition-colors disabled:opacity-40"
                            >
                                <ChevronRight size={16} />
                            </button>
                        </div>
                    </div>
                )}
            </div>

        </AdminLayout>
    );
};

export default PaymentsManagementPage;

/**
 * Admin Profile Page
 * Professional interface for managing admin profile, security settings, and preferences.
 * Connected directly to live ZyraTech API and Redux auth store.
 */

import React, { useState, useEffect, useRef } from 'react';
import { useDispatch } from 'react-redux';
import AdminLayout from '../../../components/admin/layout/AdminLayout';
import { useAuth } from '../../../hooks/useAuth';
import { isSuperAdmin } from '../../../utils/permissionHelper';
import { updateUserProfile, changePassword, verifySession, uploadUserAvatar } from '../../../store/slices/authSlice';
import authService from '../../../services/authService';
import activityLogService from '../../../services/activityLogService';
import { normalizeAvatarUrl } from '../../../utils/avatar';
import { validatePhoneNumber, getPhoneInputAttributes } from '../../../utils/phoneValidation';
import {
    User,
    Mail,
    Phone,
    MapPin,
    Shield,
    Key,
    Lock,
    Bell,
    Monitor,
    Smartphone,
    Camera,
    Save,
    Edit,
    CheckCircle,
    AlertCircle,
    Briefcase,
    Calendar,
    Clock,
    Activity,
    Loader2
} from 'lucide-react';


// Helper function to get department display color
const getDepartmentColor = (dept) => {
  switch(dept) {
    case 'Media': return 'bg-purple-100 text-purple-700';
    case 'Software': return 'bg-blue-100 text-blue-700';
    case 'Training': return 'bg-green-100 text-green-700';
    case 'CAO': return 'bg-orange-100 text-orange-700';
    default: return 'bg-gray-100 text-gray-700';
  }
};
const AdminProfilePage = () => {
    const { user, userRole } = useAuth();
    const dispatch = useDispatch();
    const isSuperAdminUser = isSuperAdmin(userRole);

    // Track if form has been initialized
    const initializedRef = useRef(false);

    // Tab & state
    const [activeTab, setActiveTab] = useState('profile');
    const [isSaving, setIsSaving] = useState(false);
    const [showSuccess, setShowSuccess] = useState(false);
    const [successMessage, setSuccessMessage] = useState('Profile updated successfully!');
    const [errorMessage, setErrorMessage] = useState('');
    const [isUploadingAvatar, setIsUploadingAvatar] = useState(false);
    const [imageError, setImageError] = useState(false);
    const [isEditMode, setIsEditMode] = useState(false);

    // User profile state
    const [userData, setUserData] = useState({
        firstName: '',
        lastName: '',
        name: '',
        email: '',
        phone: '',
        role: '',
        department: '',
        location: '',
        avatar: null,
        bio: '',
        joinedDate: '',
        lastLogin: '',
        accountStatus: 'active',
        twoFactorEnabled: false
    });

    // Password change state
    const [passwordData, setPasswordData] = useState({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [passwordLoading, setPasswordLoading] = useState(false);
    const [passwordSuccess, setPasswordSuccess] = useState('');
    const [passwordError, setPasswordError] = useState('');

    // Notification settings
    const [notifications, setNotifications] = useState({
        emailAlerts: true,
        browserPush: true,
        newsletters: false,
        securityAlerts: true,
        newEnrollments: true,
        paymentConfirmations: true,
        reportSummaries: false
    });

    // Fetch fresh session on mount
    useEffect(() => {
        dispatch(verifySession());
    }, [dispatch]);

    // Sync state with live user data from Redux / API
    useEffect(() => {
        if (user && !initializedRef.current) {
            initializedRef.current = true;
            const firstName = user.firstName || (user.name ? user.name.split(' ')[0] : '') || '';
            const lastName = user.lastName || (user.name ? user.name.split(' ').slice(1).join(' ') : '') || '';
            const displayName = (firstName && lastName)
                ? `${firstName} ${lastName}`.trim()
                : (user.name || `${firstName} ${lastName}`.trim());
            const formattedRole = user.role === 'super_admin' ? 'Super Admin'
                : user.role === 'admin' ? 'Administrator'
                : (user.role || 'Admin');

            const savedAvatar = normalizeAvatarUrl(localStorage.getItem('admin_avatar'));
            setImageError(false);

            setUserData(prev => {
                const resolvedAvatar = normalizeAvatarUrl(user.avatar) || savedAvatar || normalizeAvatarUrl(prev.avatar) || null;
                return {
                    ...prev,
                    firstName,
                    lastName,
                    name: displayName,
                    email: user.email || '',
                    phone: user.phone || '',
                    role: formattedRole,
                    department: user.department || 'Software Engineering',
                    location: user.location || 'Ghana',
                    avatar: resolvedAvatar,
                    bio: user.bio || '',
                    joinedDate: user.createdAt || user.joinedDate || '',
                    lastLogin: user.lastLogin || '',
                    accountStatus: user.accountStatus || 'active',
                    twoFactorEnabled: !!user.twoFactorEnabled
                };
            });

            if (user.notificationPreferences && typeof user.notificationPreferences === 'object') {
                setNotifications(prev => ({
                    ...prev,
                    ...user.notificationPreferences
                }));
            }
        }
    }, [user]);

    // Handle avatar upload via official POST /api/auth/profile/avatar endpoint
    const handleAvatarUpload = async (e) => {
        const file = e.target.files?.[0];
        if (!file) return;

        // Validation per backend doc: JPG, PNG, WebP only, max 10MB
        const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/webp'];
        if (!validTypes.includes(file.type.toLowerCase())) {
            setErrorMessage('Please select a valid image file (JPG, PNG, or WebP).');
            setTimeout(() => setErrorMessage(''), 5000);
            return;
        }

        const MAX_SIZE = 10 * 1024 * 1024; // 10MB
        if (file.size > MAX_SIZE) {
            setErrorMessage('Image size exceeds 10MB limit. Please choose a smaller image.');
            setTimeout(() => setErrorMessage(''), 5000);
            return;
        }

        setIsUploadingAvatar(true);
        setErrorMessage('');
        setShowSuccess(false);

        // Instant local preview for immediate visual feedback
        const localPreviewUrl = URL.createObjectURL(file);
        const previousAvatar = userData.avatar;
        setUserData(prev => ({ ...prev, avatar: localPreviewUrl }));

        try {
            const actionResult = await dispatch(uploadUserAvatar(file)).unwrap();
            const rawPersistentAvatarUrl =
                actionResult?.avatar ||
                actionResult?.user?.avatar ||
                actionResult?.user?.avatarUrl ||
                actionResult?.url ||
                actionResult?.avatarUrl ||
                actionResult?.imageUrl;

            const persistentAvatarUrl = normalizeAvatarUrl(rawPersistentAvatarUrl);

            if (persistentAvatarUrl) {
                setUserData(prev => ({
                    ...prev,
                    avatar: persistentAvatarUrl
                }));
                setImageError(false);
            }

            setSuccessMessage('Avatar uploaded successfully!');
            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 4000);
        } catch (err) {
            console.error('Avatar upload failed:', err);
            // Revert preview on failure
            setUserData(prev => ({ ...prev, avatar: previousAvatar }));
            const msg = typeof err === 'string' ? err : err?.message || 'Failed to upload avatar. Please try again.';
            setErrorMessage(msg);
            setTimeout(() => setErrorMessage(''), 6000);
        } finally {
            setIsUploadingAvatar(false);
            if (e.target) {
                e.target.value = '';
            }
        }
    };

    // Handle profile text inputs
    const handleInputChange = (e) => {
        const { name, value } = e.target;
        setUserData(prev => {
            const next = {
                ...prev,
                [name]: value
            };
            if (name === 'firstName' || name === 'lastName') {
                const fn = name === 'firstName' ? value : prev.firstName;
                const ln = name === 'lastName' ? value : prev.lastName;
                next.name = `${fn || ''} ${ln || ''}`.trim();
            }
            return next;
        });
    };

    // Handle save profile changes with automatic name sync
    const handleSave = async () => {
        setIsSaving(true);
        setErrorMessage('');
        setShowSuccess(false);

        try {
            const fn = userData.firstName.trim();
            const ln = userData.lastName.trim();
            const currentAvatar = normalizeAvatarUrl(userData.avatar) || normalizeAvatarUrl(localStorage.getItem('admin_avatar')) || null;

            const payload = {
                firstName: fn,
                lastName: ln,
                phone: userData.phone.trim(),
                department: userData.department.trim(),
                location: userData.location.trim(),
                bio: userData.bio.trim()
            };

            // Only pass avatar if it's a valid remote URL (never blob or base64)
            if (currentAvatar && /^https?:\/\//i.test(currentAvatar)) {
                payload.avatar = currentAvatar;
            }

            const result = await dispatch(updateUserProfile(payload)).unwrap();
            
            if (result?.user) {
                const u = result.user;
                setUserData(prev => ({
                    ...prev,
                    firstName: u.firstName ?? fn,
                    lastName: u.lastName ?? ln,
                    name: u.name || `${fn} ${ln}`.trim(),
                    avatar: u.avatar || currentAvatar || prev.avatar,
                    phone: u.phone ?? prev.phone,
                    department: u.department ?? prev.department,
                    location: u.location ?? prev.location,
                    bio: u.bio ?? prev.bio
                }));
            }

            try {
                await authService.updateNotificationPreferences(notifications);
            } catch {
                // Non-blocking
            }

            setSuccessMessage('Profile updated successfully!');
            setShowSuccess(true);
            setTimeout(() => setShowSuccess(false), 4000);
        } catch (err) {
            const msg = typeof err === 'string' ? err : err?.message || 'Failed to update profile. Please try again.';
            setErrorMessage(msg);
            setTimeout(() => setErrorMessage(''), 6000);
        } finally {
            setIsSaving(false);
        }
    };


    // Handle edit mode
    const handleEditMode = () => {
        setIsEditMode(true);
    };

    // Handle cancel
    const handleCancel = () => {
        setIsEditMode(false);
        setErrorMessage('');
    };
    // Handle password change
    const handlePasswordChange = async (e) => {
        e.preventDefault();
        setPasswordError('');
        setPasswordSuccess('');

        if (!passwordData.currentPassword) {
            setPasswordError('Please enter your current password.');
            return;
        }
        if (!passwordData.newPassword) {
            setPasswordError('Please enter a new password.');
            return;
        }
        if (passwordData.newPassword.length < 8) {
            setPasswordError('New password must be at least 8 characters long.');
            return;
        }
        if (passwordData.newPassword !== passwordData.confirmPassword) {
            setPasswordError('New password and confirmation password do not match.');
            return;
        }

        setPasswordLoading(true);
        try {
            await dispatch(changePassword({
                currentPassword: passwordData.currentPassword,
                newPassword: passwordData.newPassword
            })).unwrap();

            setPasswordSuccess('Password changed successfully!');
            setPasswordData({
                currentPassword: '',
                newPassword: '',
                confirmPassword: ''
            });
            setTimeout(() => setPasswordSuccess(''), 5000);
        } catch (err) {
            const msg = typeof err === 'string' ? err : err?.message || 'Failed to change password. Please verify your current password.';
            setPasswordError(msg);
        } finally {
            setPasswordLoading(false);
        }
    };

    // Helper: Compute initials
    const getInitials = () => {
        if (userData.firstName && userData.lastName) {
            return `${userData.firstName[0]}${userData.lastName[0]}`.toUpperCase();
        }
        const displayName = getDisplayName();
        if (displayName && displayName !== 'Admin User') {
            const parts = displayName.trim().split(/\s+/);
            if (parts.length >= 2) {
                return `${parts[0][0]}${parts[parts.length - 1][0]}`.toUpperCase();
            }
            return parts[0].slice(0, 2).toUpperCase();
        }
        if (userData.email) {
            return userData.email.slice(0, 2).toUpperCase();
        }
        return 'AU';
    };

    const getDisplayName = () => {
        const combined = `${userData.firstName || ''} ${userData.lastName || ''}`.trim();
        if (combined) return combined;
        if (userData.name) return userData.name;
        return userData.email || 'Admin User';
    };

    // Format date
    const formatDate = (dateString) => {
        if (!dateString) return '';
        const date = new Date(dateString);
        if (isNaN(date.getTime())) return dateString;
        return date.toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'long',
            day: 'numeric'
        });
    };

    // Format time
    const formatTime = (dateString) => {
        if (!dateString) return '';
        const date = new Date(dateString);
        if (isNaN(date.getTime())) return '';
        return date.toLocaleTimeString('en-US', {
            hour: '2-digit',
            minute: '2-digit'
        });
    };

    // Activity logs from service or fallback
    const activityLogs = activityLogService.getLogs ? activityLogService.getLogs({ limit: 6 }) : [];

    return (
        <AdminLayout>
            <div className="max-w-5xl mx-auto space-y-3 md:space-y-6 pb-8">
                {/* Page Header */}
                <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
                    <div>
                        <h1 className="text-2xl font-bold text-gray-900 flex items-center gap-3">
                            <div className="w-8 h-8 md:w-10 md:h-10 bg-gradient-to-br from-[#004fa2] to-[#0066cc] rounded-xl flex items-center justify-center shadow-sm">
                                <User className="text-white" size={20} />
                            </div>
                            My Profile
                        </h1>
                        <p className="text-sm text-gray-500 mt-1 ml-[44px] md:ml-[52px]">
                            Manage your account settings and preferences
                        </p>
                    </div>

                    {activeTab === 'profile' && null}
                </div>

                {/* Alerts */}
                {showSuccess && (
                    <div className="bg-green-50 border border-green-200 rounded-xl p-4 flex items-center gap-3 text-green-700 animate-in fade-in slide-in-from-top-4 duration-300 shadow-sm">
                        <CheckCircle size={20} className="shrink-0" />
                        <span className="font-medium text-sm">{successMessage}</span>
                    </div>
                )}

                {errorMessage && (
                    <div className="bg-red-50 border border-red-200 rounded-xl p-4 flex items-center gap-3 text-red-700 animate-in fade-in slide-in-from-top-4 duration-300 shadow-sm">
                        <AlertCircle size={20} className="shrink-0" />
                        <span className="font-medium text-sm">{errorMessage}</span>
                    </div>
                )}

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Left Column: Profile Card & Menu */}
                    <div className="space-y-6">
                        {/* Profile Summary Card */}
                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden p-5">
                            <div className="flex items-center gap-4">
                                {/* Avatar */}
                                <div className="w-16 h-16 rounded-full border-2 border-gray-200 shadow-sm shrink-0 overflow-hidden relative group">
                                    {userData.avatar && !imageError ? (
                                        <img
                                            key={userData.avatar}
                                            decoding="async"
                                            src={normalizeAvatarUrl(userData.avatar)}
                                            alt="Profile"
                                            className="w-full h-full object-cover"
                                            onError={() => setImageError(true)}
                                        />
                                    ) : (
                                        <div className="w-full h-full bg-gradient-to-br from-[#004fa2] to-[#0066cc] flex items-center justify-center text-white font-bold text-lg">
                                            {getInitials()}
                                        </div>
                                    )}
                                    {isUploadingAvatar ? (
                                        <div className="absolute inset-0 bg-black/60 flex items-center justify-center">
                                            <Loader2 className="text-white animate-spin" size={22} />
                                        </div>
                                    ) : (
                                        <div
                                            className="absolute inset-0 bg-black/40 flex items-center justify-center opacity-0 group-hover:opacity-100 transition-opacity cursor-pointer"
                                            onClick={() => document.getElementById('avatar-upload').click()}
                                            title="Change Photo"
                                        >
                                            <Camera className="text-white" size={16} />
                                        </div>
                                    )}
                                    <input
                                        id="avatar-upload"
                                        type="file"
                                        accept="image/jpeg,image/png,image/webp"
                                        className="hidden"
                                        disabled={isUploadingAvatar}
                                        onChange={handleAvatarUpload}
                                    />
                                </div>
                                {/* Info */}
                                <div className="flex-1 min-w-0">
                                    <h2 className="text-base font-bold text-gray-900 truncate">
                                        {getDisplayName()}
                                    </h2>
                                    <p className="text-xs text-gray-500 mb-2 truncate">{userData.email || 'Loading...'}</p>
                                    <div className="flex items-center flex-wrap gap-1.5">
                                        <span className={`px-2 py-0.5 rounded-full text-[10px] font-bold ${
                                            userData.role.toLowerCase().includes('super')
                                                ? 'bg-purple-100 text-purple-700'
                                                : 'bg-blue-100 text-blue-700'
                                        }`}>
                                            {userData.role || 'Admin'}
                                        </span>
                                        <span className="px-2 py-0.5 bg-green-100 text-green-700 rounded-full text-[10px] font-bold flex items-center gap-1 capitalize">
                                            <div className="w-1.5 h-1.5 rounded-full bg-green-500 animate-pulse"></div>
                                            {userData.accountStatus || 'Active'}
                                        </span>
                                    </div>
                                    <button
                                        onClick={() => document.getElementById('avatar-upload').click()}
                                        disabled={isUploadingAvatar}
                                        className="mt-2 text-xs text-[#004fa2] hover:underline font-medium block disabled:opacity-50"
                                    >
                                        {isUploadingAvatar ? (
                                            <span className="flex items-center gap-1">
                                                <Loader2 size={12} className="animate-spin" /> Uploading...
                                            </span>
                                        ) : (
                                            'Change Photo'
                                        )}
                                    </button>
                                </div>
                            </div>
                        </div>

                        {/* Navigation Menu */}
                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                            <nav className="flex lg:flex-col overflow-x-auto p-2 gap-1">
                                <button
                                    onClick={() => setActiveTab('profile')}
                                    className={`flex items-center gap-2 px-3 lg:px-4 py-2.5 lg:py-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${
                                        activeTab === 'profile'
                                            ? 'bg-blue-50 text-[#004fa2] font-semibold'
                                            : 'text-gray-600 hover:bg-gray-50'
                                    }`}
                                >
                                    <User size={18} />
                                    <span>Personal Info</span>
                                </button>
                                <button
                                    onClick={() => setActiveTab('security')}
                                    className={`flex items-center gap-2 px-3 lg:px-4 py-2.5 lg:py-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${
                                        activeTab === 'security'
                                            ? 'bg-blue-50 text-[#004fa2] font-semibold'
                                            : 'text-gray-600 hover:bg-gray-50'
                                    }`}
                                >
                                    <Shield size={18} />
                                    <span>Security</span>
                                </button>
                                <button
                                    onClick={() => setActiveTab('notifications')}
                                    className={`flex items-center gap-2 px-3 lg:px-4 py-2.5 lg:py-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${
                                        activeTab === 'notifications'
                                            ? 'bg-blue-50 text-[#004fa2] font-semibold'
                                            : 'text-gray-600 hover:bg-gray-50'
                                    }`}
                                >
                                    <Bell size={18} />
                                    <span>Notifications</span>
                                </button>
                                <button
                                    onClick={() => setActiveTab('activity')}
                                    className={`flex items-center gap-2 px-3 lg:px-4 py-2.5 lg:py-3 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${
                                        activeTab === 'activity'
                                            ? 'bg-blue-50 text-[#004fa2] font-semibold'
                                            : 'text-gray-600 hover:bg-gray-50'
                                    }`}
                                >
                                    <Activity size={18} />
                                    <span>Activity</span>
                                </button>
                            </nav>
                        </div>

                        {/* Quick Info */}
                        <div className="bg-white rounded-xl shadow-sm border border-gray-100 p-5 space-y-4">
                            <h3 className="font-semibold text-gray-900 text-sm">Account Info</h3>
                            <div className="space-y-3">
                                <div className="flex items-center gap-3 text-sm text-gray-600">
                                    <Calendar size={16} className="text-gray-400 shrink-0" />
                                    <span>{userData.joinedDate ? `Joined ${formatDate(userData.joinedDate)}` : 'Status: Verified Admin'}</span>
                                </div>
                                <div className="flex items-center gap-3 text-sm text-gray-600">
