 * Project Details Page (Admin)
 * For viewing and managing a specific project
 */

import React, { useState, useEffect } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { openConfirmDialog, addNotification } from '../../../store/slices/uiSlice';
import { useAuth } from '../../../hooks/useAuth';
import AdminLayout from '../../../components/admin/layout/AdminLayout';

import projectsService from '../../../services/projectsService';
import {
    ArrowLeft,
    Edit,
    Trash2,
    ExternalLink,
    Calendar,
    Users,
    Zap,
    Target,
    CheckCircle,
    AlertCircle
} from 'lucide-react';

const ProjectDetailsPage = () => {
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const { userPermissions, userRole } = useAuth();
    const { id } = useParams();
  const isSuperAdmin = userRole?.toLowerCase() === 'super_admin' || userRole?.toLowerCase() === 'super admin';

    const [project, setProject] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);

    // Load project data from API
    useEffect(() => {
        const fetchProject = async () => {
            try {
                setLoading(true);
                setError(null);
                let data = await projectsService.getProjectById(id);
                
                if (data) {
                    // Normalize backend field names to match frontend expectations
                    // Backend returns: coverImageUrl, teamSize, projectLink
