                                    {formData.image ? (
                                        <div className="relative rounded-lg overflow-hidden border border-gray-200 bg-gray-50 shadow-sm mb-3">
                                            <img decoding="async" src={formData.image} alt="Preview" className="w-full h-48 object-cover" loading="lazy" />
                                            <button
                                                type="button"
                                                onClick={() => setFormData(prev => ({ ...prev, image: '' }))}
                                                className="absolute top-2 right-2 p-1.5 bg-red-600 text-white rounded-lg hover:bg-red-700 transition-colors"
                                            >
                                                <X size={16} />
                                            </button>
                                        </div>
                                    ) : (
                                        <label className="block w-full p-6 border-2 border-dashed border-gray-300 rounded-lg cursor-pointer hover:border-[#004fa2] hover:bg-[#004fa2]/5 transition-all mb-3">
                                            <div className="flex flex-col items-center justify-center">
                                                <Upload className="text-gray-400 mb-2" size={24} />
                                                <p className="text-xs font-semibold text-gray-600 mb-1">
                                                    {isUploadingImage ? 'Uploading...' : 'Click to upload or drag & drop'}
                                                </p>
                                                <p className="text-[10px] text-gray-500">PNG, JPG, or WebP up to 10MB</p>
                                            </div>
                                            <input
                                                type="file"
                                                accept="image/png,image/jpeg,image/webp,image/jpg"
                                                onChange={handleImageUpload}
                                                disabled={isUploadingImage}
                                                className="hidden"
                                            />
                                        </label>
                                    )}

                                    {imageUploadError && (
                                        <div className="flex items-center gap-2 p-2 bg-red-50 border border-red-200 rounded-lg mb-3">
                                            <AlertCircle className="text-red-600" size={14} />
                                            <p className="text-[10px] text-red-700">{imageUploadError}</p>
                                        </div>
                                    )}

                                    <p className="text-[10px] text-gray-600 mb-3">Or paste image URL directly:</p>
                                    <input
                                        type="text"
                                        name="image"
                                        value={formData.image}
                                        onChange={handleChange}
                                        placeholder="https://example.com/image.webp"
                                        className={`w-full px-3 py-1.5 text-sm border rounded-lg focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all bg-gray-50 hover:bg-white focus:bg-white ${
                                            errors.image ? 'border-red-500' : 'border-gray-200'
                                        }`}
                                    />
                                    {errors.image && <p className="text-[10px] text-red-600 mt-1">{errors.image}</p>}
                                    
                                    <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1 mt-3">
                                        Project Link (Optional) - External URL
                                    </label>
                                    <input
                                        type="text"
                                        name="link"
                                        value={formData.link}
                                        onChange={handleChange}
                                        placeholder="https://example.com/project"
                                        className="w-full px-3 py-1.5 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all bg-gray-50 hover:bg-white focus:bg-white"
                                    />
                                </div>
                            </div>

                            {/* Technologies */}
                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">
                                    Technologies *
                                </label>
                                <div className="flex gap-2 mb-2">
                                    <input
                                        type="text"
                                        value={technologiesInput}
                                        onChange={handleTechnologiesChange}
                                        onKeyPress={(e) => {
                                            if (e.key === 'Enter') {
                                                e.preventDefault();
                                                handleAddTechnology(technologiesInput.trim());
                                            }
                                        }}
                                        placeholder="Type tech and press Enter"
                                        className="flex-1 px-3 py-1.5 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all bg-gray-50 hover:bg-white focus:bg-white"
                                    />
                                    <button
                                        type="button"
                                        onClick={() => handleAddTechnology(technologiesInput.trim())}
                                        className="px-3 py-1.5 bg-[#004fa2] text-white rounded-lg hover:bg-[#003d7a] transition-colors flex items-center gap-1 text-xs font-semibold shrink-0"
                                    >
                                        <Plus size={14} /> Add
                                    </button>
                                </div>
                                
                                {formData.technologies.length > 0 && (
                                    <div className="flex flex-wrap gap-1.5">
                                        {formData.technologies.map((tech, index) => (
                                            <div
                                                key={index}
                                                className="flex items-center gap-1.5 px-2 py-1 bg-blue-50 text-blue-700 rounded-md border border-blue-100"
                                            >
                                                <span className="text-xs font-semibold">{tech}</span>
                                                <button
                                                    type="button"
                                                    onClick={() => handleRemoveTechnology(index)}
                                                    className="hover:text-red-500 transition-colors"
                                                >
                                                    <X size={12} />
                                                </button>
                                            </div>
                                        ))}
                                    </div>
                                )}
                                {errors.technologies && <p className="text-[10px] text-red-600 mt-1">{errors.technologies}</p>}
                            </div>

                            {/* Team, Start Date, Progress */}
                            <div>
                                <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">
                                    Team Size *
                                </label>
                                <input
                                    type="number"
                                    name="team"
                                    value={formData.team}
                                    onChange={handleChange}
                                    min="1"
                                    max="100"
                                    className={`w-full px-3 py-1.5 text-sm border rounded-lg focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all bg-gray-50 hover:bg-white focus:bg-white ${
                                        errors.team ? 'border-red-500' : 'border-gray-200'
                                    }`}
                                />
                                {errors.team && <p className="text-[10px] text-red-600 mt-1">{errors.team}</p>}
                            </div>

                            <div>
                                <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">
                                    Start Date *
                                </label>
                                <input
                                    type="date"
                                    name="startDate"
                                    value={formData.startDate}
                                    onChange={handleChange}
                                    className="w-full px-3 py-1.5 text-sm border border-gray-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all bg-gray-50 hover:bg-white focus:bg-white"
                                />
                            </div>

                            <div className="md:col-span-2">
                                <label className="block text-[10px] font-bold text-gray-500 uppercase tracking-wider mb-1">
                                    Progress (%) *
                                </label>
                                <div className="flex items-center gap-3">
                                    <input
                                        type="number"
                                        name="progress"
                                        value={formData.progress}
                                        onChange={handleChange}
                                        min="0"
                                        max="100"
                                        className={`w-20 px-3 py-1.5 text-sm border rounded-lg focus:outline-none focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] transition-all bg-gray-50 hover:bg-white focus:bg-white ${
                                            errors.progress ? 'border-red-500' : 'border-gray-200'
                                        }`}
                                    />
                                    <div className="flex-1 bg-gray-100 rounded-full h-2">
                                        <div
                                            className="bg-[#004fa2] h-2 rounded-full transition-all"
                                            style={{ width: `${formData.progress}%` }}
                                        />
                                    </div>
                                </div>
                                {errors.progress && <p className="text-[10px] text-red-600 mt-1">{errors.progress}</p>}
                            </div>
                        </div>

                        {/* Featured Checkbox */}
                        <div className="flex items-center gap-3 p-3 bg-gray-50 rounded-lg border border-gray-100 mt-2 hover:border-[#004fa2]/30 transition-colors">
                            <input
                                type="checkbox"
                                name="featured"
                                id="featured"
                                checked={formData.featured}
                                onChange={handleChange}
                                className="w-4 h-4 text-[#004fa2] rounded border-gray-300 focus:ring-[#004fa2]"
                            />
                            <div>
                                <label htmlFor="featured" className="text-xs font-bold text-gray-700 cursor-pointer uppercase tracking-wide">
                                    Mark as Featured
                                </label>
                                <p className="text-[10px] text-gray-500">Highlighted on the portfolio overview</p>
                            </div>
                        </div>

                        {/* Action Buttons */}
                        <div className="flex gap-2 justify-end pt-4 border-t border-gray-100">
                            <button
                                type="button"
                                onClick={handleCancel}
                                className="px-4 py-1.5 text-xs font-semibold text-gray-600 bg-gray-100 hover:bg-gray-200 rounded-lg transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                type="submit"
                                disabled={isUploadingImage}
                                className="flex items-center gap-1.5 px-4 py-1.5 bg-[#004fa2] text-white text-xs font-semibold rounded-lg hover:bg-[#003d7a] disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-sm"
                            >
                                <Save size={14} />
                                {isUploadingImage ? 'Uploading...' : id ? 'Update Project' : 'Create Project'}
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        </AdminLayout>
    );
};

export default ProjectFormPage;

/**
 * Project Request Details Page - COMPACT VERSION
 * Full-page display of a single project request with all information
 * Compact layout, no overlapping text, no gradients
 */

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { openConfirmDialog, addNotification } from '../../../store/slices/uiSlice';
import AdminLayout from '../../../components/admin/layout/AdminLayout';
import projectRequestService from '../../../services/projectRequestService';
import { useAuth } from '../../../hooks/useAuth';
import { canAccessFeature, isSuperAdmin, checkPermissionAndShowError } from '../../../utils/permissionHelper';
import {
    ArrowLeft,
    AlertCircle,
    Check,
    X,
    Trash2,
    Loader,
} from 'lucide-react';

// Status configuration - simple, no colors
const STATUS_CONFIG = {
    'pending': { label: 'Pending' },
    'approved': { label: 'Approved' },
    'rejected': { label: 'Rejected' }
};

// Status badge component - minimal
const StatusBadge = ({ status }) => {
    const config = STATUS_CONFIG[status] || STATUS_CONFIG['pending'];
    
    return (
        <span className="inline-block px-3 py-1 bg-gray-100 text-gray-700 rounded text-xs font-semibold">
            {config.label}
        </span>
    );
};

const ProjectRequestDetailsPage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    const { userRole, userPermissions, userDepartment } = useAuth();

    // Permission check for projects management
    const hasProjectsPermission = canAccessFeature(userPermissions, userRole, 'projects');
    const isSuperAdminUser = isSuperAdmin(userRole);

    const [request, setRequest] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [statusModal, setStatusModal] = useState(null);
    const [statusNotes, setStatusNotes] = useState('');
    const [updatingStatus, setUpdatingStatus] = useState(false);

    // Fetch project request details
    useEffect(() => {
        fetchRequestDetails();
    }, [id]);

    const fetchRequestDetails = async () => {
        try {
            setLoading(true);
            setError(null);
            const response = await projectRequestService.getProjectRequestById(id);
            setRequest(response);
        } catch (err) {
            console.error('Failed to fetch project request:', err);
            setError(err.message || 'Failed to load project request details');
            dispatch(addNotification({
                type: 'error',
                message: 'Failed to load project request details'
            }));
        } finally {
            setLoading(false);
        }
    };

    const handleDelete = () => {
        // Permission check
        if (!isSuperAdminUser && !hasProjectsPermission) {
            checkPermissionAndShowError(
                userPermissions,
                userRole,
                'projects',
                dispatch,
                'Software Projects',
                'Software'
            );
            return;
        }

        dispatch(openConfirmDialog({
            title: 'Delete Project Request',
            message: `Are you sure you want to delete this project request from ${request.fullName}? This action cannot be undone.`,
            isDangerous: true,
            onConfirm: async () => {
                try {
                    await projectRequestService.deleteProjectRequest(id);
                    dispatch(addNotification({
                        type: 'success',
                        message: 'Project request deleted successfully'
                    }));
                    navigate('/admin/project-requests');
                } catch (err) {
                    console.error('Failed to delete request:', err);
                    dispatch(addNotification({
                        type: 'error',
                        message: `Failed to delete request: ${err.message}`
                    }));
                }
            }
        }));
    };

    const handleStatusUpdate = async (newStatus) => {
        // Permission check
        if (!isSuperAdminUser && !hasProjectsPermission) {
            checkPermissionAndShowError(
                userPermissions,
                userRole,
                'projects',
                dispatch,
                'Software Projects',
                'Software'
            );
            return;
        }

        try {
            setUpdatingStatus(true);
            await projectRequestService.updateProjectRequestStatus(id, {
                status: newStatus,
                reviewNotes: statusNotes
            });

            // Update local state
            setRequest(prev => ({
                ...prev,
                status: newStatus,
                reviewNotes: statusNotes
            }));

            setStatusModal(null);
            setStatusNotes('');

            dispatch(addNotification({
                type: 'success',
                message: `Request status updated to ${newStatus}`
            }));
        } catch (err) {
            console.error('Failed to update status:', err);
            dispatch(addNotification({
                type: 'error',
                message: `Failed to update status: ${err.message}`
            }));
        } finally {
            setUpdatingStatus(false);
        }
    };

    const formatDate = (dateString) => {
        return new Date(dateString).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
        });
    };

    const formatTime = (dateString) => {
        return new Date(dateString).toLocaleTimeString('en-US', {
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
        });
    };

    if (loading) {
        return (
            <AdminLayout>
                <div className="flex items-center justify-center min-h-screen">
                    <div className="text-center">
                        <Loader className="w-12 h-12 text-blue-600 animate-spin mx-auto mb-4" />
                        <p className="text-gray-600 text-sm">Loading request details...</p>
                    </div>
                </div>
            </AdminLayout>
        );
    }

    if (error) {
        return (
            <AdminLayout>
                <div className="max-w-2xl mx-auto px-4 py-4">
                    <button
                        onClick={() => navigate('/admin/project-requests')}
                        className="flex items-center gap-2 text-blue-600 hover:text-blue-800 text-sm font-medium mb-4"
                    >
                        <ArrowLeft size={16} />
                        Back
                    </button>
                    <div className="bg-white border border-gray-200 rounded p-4 flex items-start gap-3">
                        <AlertCircle className="text-red-600 flex-shrink-0 mt-0.5" size={20} />
                        <div>
                            <h2 className="font-semibold text-gray-900 text-sm mb-1">Error Loading Request</h2>
                            <p className="text-gray-700 text-xs">{error}</p>
                        </div>
                    </div>
                </div>
            </AdminLayout>
        );
    }

    if (!request) {
        return (
            <AdminLayout>
                <div className="max-w-2xl mx-auto px-4 py-4">
                    <button
                        onClick={() => navigate('/admin/project-requests')}
                        className="flex items-center gap-2 text-blue-600 hover:text-blue-800 text-sm font-medium mb-4"
                    >
                        <ArrowLeft size={16} />
                        Back
                    </button>
                    <div className="bg-white border border-gray-200 rounded p-4 flex items-start gap-3">
                        <AlertCircle className="text-yellow-600 flex-shrink-0 mt-0.5" size={20} />
                        <div>
                            <h2 className="font-semibold text-gray-900 text-sm mb-1">Request Not Found</h2>
                            <p className="text-gray-700 text-xs">The project request you're looking for doesn't exist or has been deleted.</p>
                        </div>
                    </div>
                </div>
            </AdminLayout>
        );
    }

    return (
        <AdminLayout>
            <div className="max-w-7xl mx-auto px-4 py-6 pb-8">
                {/* HEADER */}
                <div className="flex items-center justify-between gap-4 mb-6">
                    <button
                        onClick={() => navigate('/admin/project-requests')}
                        className="flex items-center gap-2 text-blue-600 hover:text-blue-800 text-sm font-medium transition-colors"
                    >
                        <ArrowLeft size={16} />
                        Back to Requests
                    </button>
                    <h1 className="text-2xl font-bold text-gray-900">Project Request Details</h1>
                    <div className="w-32" />
                </div>

                {/* TWO-COLUMN LAYOUT */}
                <div className="grid grid-cols-3 gap-6">
                    {/* LEFT COLUMN - 60% (2/3) */}
                    <div className="col-span-2 space-y-6">
                        {/* APPLICANT CARD */}
                        <div className="bg-white border border-gray-100 rounded-lg shadow-md hover:shadow-lg transition-shadow duration-200 hover:-translate-y-0.5">
                            {/* Header Section */}
                            <div className="px-6 py-5 flex items-start justify-between gap-4 border-b border-gray-300">
                                <div className="flex-1 min-w-0">
                                    <h2 className="text-2xl font-bold text-gray-900">{request.fullName}</h2>
                                    <a 
                                        href={`mailto:${request.email}`} 
                                        className="text-base text-blue-600 hover:text-blue-800 font-medium mt-2 block"
                                    >
                                        {request.email}
                                    </a>
                                </div>
                                <div className="flex-shrink-0">
                                    <StatusBadge status={request.status} />
                                </div>
                            </div>

                            {/* Contact Info Section */}
                            <div className="px-6 py-5">
                                <div className="grid grid-cols-3 gap-0 divide-x divide-gray-300">
                                    {/* Phone */}
                                    <div className="pr-6">
                                        <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Phone</p>
                                        <a href={`tel:${request.phone}`} className="text-sm text-blue-600 hover:text-blue-800 font-medium block break-all">
                                            {request.phone}
                                        </a>
                                    </div>

                                    {/* Project Type */}
                                    <div className="px-6">
                                        <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Project Type</p>
                                        <p className="text-sm text-gray-900 font-medium capitalize">{request.projectType}</p>
                                    </div>

                                    {/* Package Type */}
                                    <div className="pl-6">
                                        <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Package Type</p>
                                        <p className="text-sm text-gray-900 font-medium capitalize">{request.packageType?.replace('-', ' ')}</p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* PROJECT DESCRIPTION */}
                        <div className="bg-white border border-gray-100 rounded-lg p-6 shadow-md hover:shadow-lg transition-shadow duration-200 hover:-translate-y-0.5">
                            <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wide mb-4 pb-3 border-b border-gray-100">
                                Project Overview
                            </h3>
                            
                            <div className="space-y-4">
                                <div>
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Project Title</p>
                                    <p className="text-base font-semibold text-gray-900">{request.projectTitle}</p>
                                </div>
                                
                                <div>
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Description</p>
                                    <div className="text-sm text-gray-700 leading-relaxed bg-gray-50 p-3 rounded border border-gray-100 break-words whitespace-normal max-w-full overflow-hidden">
                                        {request.description}
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* PROJECT DETAILS */}
                        <div className="bg-white border border-gray-100 rounded-lg p-6 shadow-md hover:shadow-lg transition-shadow duration-200 hover:-translate-y-0.5">
                            <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wide mb-4 pb-3 border-b border-gray-100">
                                Project Details
                            </h3>

                            <div className="space-y-4">
                                {/* Budget and Timeline */}
                                <div className="grid grid-cols-2 gap-4">
                                    {request.budget && (
                                        <div>
                                            <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Budget</p>
                                            <p className="text-base text-gray-900 font-semibold">{request.budget}</p>
                                        </div>
                                    )}
                                    {request.timeline && (
                                        <div>
                                            <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Timeline</p>
                                            <p className="text-base text-gray-900 font-semibold">{request.timeline}</p>
                                        </div>
                                    )}
                                </div>

                                {/* Technologies */}
                                {request.technologies && request.technologies.length > 0 && (
                                    <div>
                                        <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-3">Technologies</p>
                                        <div className="flex flex-wrap gap-2">
                                            {request.technologies.map((tech, idx) => (
                                                <span key={idx} className="inline-block px-3 py-1.5 bg-gray-100 text-gray-700 rounded text-xs font-medium">
                                                    {tech}
                                                </span>
                                            ))}
                                        </div>
                                    </div>
                                )}

                                {/* Additional Notes */}
                                {request.additionalNotes && (
                                    <div>
                                        <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Additional Notes</p>
                                        <div className="text-sm text-gray-700 leading-relaxed bg-gray-50 p-3 rounded border border-gray-100 break-words whitespace-normal max-w-full overflow-hidden">
                                            {request.additionalNotes}
                                        </div>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* RIGHT SIDEBAR - 40% (1/3) */}
                    <div className="col-span-1 space-y-6">
                        {/* ACTION BUTTONS */}
                        <div className="space-y-3">
                            {request.status !== 'approved' && (
                                <button
                                    onClick={() => {
                                        if (isSuperAdminUser || hasProjectsPermission) {
                                            setStatusModal('approved');
                                        } else {
                                            checkPermissionAndShowError(
                                                userPermissions,
                                                userRole,
                                                'projects',
                                                dispatch,
                                                'Software Projects',
                                                'Software'
                                            );
                                        }
                                    }}
                                    disabled={!isSuperAdminUser && !hasProjectsPermission}
                                    className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-green-600 text-white text-sm font-semibold rounded-lg hover:bg-green-700 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    <Check size={16} />
                                    Approve
                                </button>
                            )}
                            {request.status !== 'rejected' && (
                                <button
                                    onClick={() => {
                                        if (isSuperAdminUser || hasProjectsPermission) {
                                            setStatusModal('rejected');
                                        } else {
                                            checkPermissionAndShowError(
                                                userPermissions,
                                                userRole,
                                                'projects',
                                                dispatch,
                                                'Software Projects',
                                                'Software'
                                            );
                                        }
                                    }}
                                    disabled={!isSuperAdminUser && !hasProjectsPermission}
                                    className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-red-600 text-white text-sm font-semibold rounded-lg hover:bg-red-700 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                                >
                                    <X size={16} />
                                    Reject
                                </button>
                            )}
                            <button
                                onClick={handleDelete}
                                disabled={!isSuperAdminUser && !hasProjectsPermission}
                                className="w-full flex items-center justify-center gap-2 px-4 py-3 bg-gray-200 text-gray-700 text-sm font-semibold rounded-lg hover:bg-gray-300 transition-colors shadow-sm disabled:opacity-50 disabled:cursor-not-allowed"
                            >
                                <Trash2 size={16} />
                                Delete
                            </button>
                        </div>

                        {/* REQUEST INFO CARD */}
                        <div className="bg-white border border-gray-100 rounded-lg p-6 shadow-md hover:shadow-lg transition-shadow duration-200 hover:-translate-y-0.5">
                            <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wide mb-4 pb-3 border-b border-gray-100">
                                Request Info
                            </h3>

                            <div className="space-y-4">
                                <div>
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-1">Request ID</p>
                                    <p className="text-sm text-gray-900 font-mono bg-gray-50 px-2 py-1.5 rounded border border-gray-100 break-all">
                                        {request.id}
                                    </p>
                                </div>

                                <div>
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-2">Status</p>
                                    <StatusBadge status={request.status} />
                                </div>

                                <div>
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-1">Package Type</p>
                                    <p className="text-sm text-gray-900 font-medium capitalize">{request.packageType?.replace('-', ' ')}</p>
                                </div>

                                <div>
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-1">Budget</p>
                                    <p className="text-sm text-gray-900 font-semibold">{request.budget || 'ΓÇö'}</p>
                                </div>
                            </div>
                        </div>

                        {/* TIMELINE CARD */}
                        <div className="bg-white border border-gray-100 rounded-lg p-6 shadow-md hover:shadow-lg transition-shadow duration-200 hover:-translate-y-0.5">
                            <h3 className="text-sm font-bold text-gray-900 uppercase tracking-wide mb-4 pb-3 border-b border-gray-100">
                                Timeline
                            </h3>

                            <div className="space-y-4">
                                <div>
                                    <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-1">Submitted</p>
                                    <p className="text-sm text-gray-900 font-medium">{formatDate(request.createdAt)}</p>
                                    <p className="text-xs text-gray-600">{formatTime(request.createdAt)}</p>
                                </div>

                                {request.updatedAt && (
                                    <div className="pt-3 border-t border-gray-100">
                                        <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide mb-1">Last Updated</p>
                                        <p className="text-sm text-gray-900 font-medium">{formatDate(request.updatedAt)}</p>
                                        <p className="text-xs text-gray-600">{formatTime(request.updatedAt)}</p>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                </div>

                {/* Status Update Modal */}
                {statusModal && (
                    <div className="fixed inset-0 bg-black/40 z-50 flex items-center justify-center p-4">
                        <div className="bg-white rounded-lg shadow-xl max-w-md w-full">
                            {/* Modal Header */}
                            <div className={`${statusModal === 'approved' ? 'bg-green-600' : 'bg-red-600'} text-white px-6 py-4 flex items-center justify-between`}>
                                <h3 className="text-base font-bold">
                                    {statusModal === 'approved' ? 'Approve Request' : 'Reject Request'}
                                </h3>
                                <button onClick={() => setStatusModal(null)} className="text-white hover:bg-white/20 p-1 rounded transition-colors">
                                    <X size={18} />
                                </button>
                            </div>

                            {/* Modal Content */}
                            <div className="p-6 space-y-4">
                                {/* Status Info */}
                                <div className={`${statusModal === 'approved' ? 'bg-green-50 border-green-200' : 'bg-red-50 border-red-200'} border rounded-lg p-3`}>
                                    <p className={`text-sm font-medium ${statusModal === 'approved' ? 'text-green-900' : 'text-red-900'}`}>
                                        {statusModal === 'approved' 
                                            ? 'This request will be marked as Approved' 
                                            : 'This request will be marked as Rejected'}
                                    </p>
                                </div>

                                {/* Request Summary */}
                                <div className="bg-gray-50 border border-gray-200 rounded-lg p-4">
                                    <p className="text-xs text-gray-600 font-semibold uppercase tracking-wide mb-3">Request Summary</p>
                                    <div className="space-y-3">
                                        <div>
                                            <p className="text-xs text-gray-600 uppercase font-semibold mb-1">Applicant</p>
                                            <p className="text-sm text-gray-900 font-medium truncate">{request.fullName}</p>
                                        </div>
                                        <div>
                                            <p className="text-xs text-gray-600 uppercase font-semibold mb-1">Project</p>
                                            <p className="text-sm text-gray-900 font-medium line-clamp-1">{request.projectTitle}</p>
                                        </div>
                                    </div>
                                </div>

                                {/* Review Notes */}
                                <div>
                                    <label className="block text-sm font-semibold text-gray-900 mb-2">
                                        {statusModal === 'approved' ? 'Approval Notes' : 'Rejection Reason'}
                                    </label>
                                    <textarea
                                        value={statusNotes}
                                        onChange={(e) => setStatusNotes(e.target.value)}
                                        placeholder={statusModal === 'approved' 
                                            ? "Add any notes about this approval..." 
                                            : "Explain why this request is being rejected..."}
                                        rows="4"
                                        maxLength="300"
                                        className="w-full px-3 py-2 text-sm bg-white border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500/20 focus:border-blue-500 outline-none resize-none"
                                    />
                                    <p className="text-xs text-gray-500 mt-2">{statusNotes.length}/300 characters</p>
                                </div>
                            </div>

                            {/* Modal Footer */}
                            <div className="bg-gray-50 border-t border-gray-200 px-6 py-4 flex gap-3 justify-end rounded-b-lg">
                                <button
                                    onClick={() => setStatusModal(null)}
                                    className="px-4 py-2 bg-white text-gray-700 text-sm font-semibold rounded-lg border border-gray-300 hover:bg-gray-100 transition-colors"
                                >
                                    Cancel
                                </button>
                                <button
                                    onClick={() => handleStatusUpdate(statusModal)}
                                    disabled={updatingStatus}
                                    className={`px-4 py-2 text-white text-sm font-semibold rounded-lg flex items-center gap-2 transition-colors ${
                                        statusModal === 'approved'
                                            ? 'bg-green-600 hover:bg-green-700 disabled:bg-green-400'
                                            : 'bg-red-600 hover:bg-red-700 disabled:bg-red-400'
                                    }`}
                                >
                                    {updatingStatus && <Loader size={14} className="animate-spin" />}
                                    {statusModal === 'approved' ? 'Approve' : 'Reject'}
                                </button>
                            </div>
                        </div>
                    </div>
                )}
            </div>
        </AdminLayout>
    );
};

export default ProjectRequestDetailsPage;

/**
 * Project Requests Management Page (Admin)
 * Professional admin interface for managing submitted project requests
 * 
 * Improvements:
 * - Enhanced table layout with better spacing and readability
 * - Professional modal design with clear sections
 * - Better visual hierarchy and typography
 * - Improved mobile responsiveness
 * - Subtle shadows and borders for depth
 * - Professional status badges and visual indicators
 */

import React, { useState, useMemo, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { openConfirmDialog, addNotification } from '../../../store/slices/uiSlice';
import AdminLayout from '../../../components/admin/layout/AdminLayout';
import projectRequestService from '../../../services/projectRequestService';
import { useAuth } from '../../../hooks/useAuth';
import { canAccessFeature, isSuperAdmin, checkPermissionAndShowError } from '../../../utils/permissionHelper';
import {
    Inbox,
    Search,
    Filter,
    Eye,
    Trash2,
    ChevronLeft,
    ChevronRight,
    X,
    AlertCircle,
    CheckCircle,
    Clock,
    XCircle,
    Mail,
    Phone,
    Building2,
    FileText,
    Calendar,
    Zap,
    MoreVertical,
    Divider,
    ArrowRight,
} from 'lucide-react';

// Status configuration for project requests
const STATUS_CONFIG = {
    'pending': { label: 'Pending', color: 'bg-amber-100 text-amber-700 border-amber-200', icon: Clock, bg: 'bg-amber-50' },
    'approved': { label: 'Approved', color: 'bg-green-100 text-green-700 border-green-200', icon: CheckCircle, bg: 'bg-green-50' },
    'rejected': { label: 'Rejected', color: 'bg-red-100 text-red-700 border-red-200', icon: XCircle, bg: 'bg-red-50' }
};

// Package type configuration
const PACKAGE_TYPE_CONFIG = {
    'student-projects': { label: 'Student Projects', color: 'bg-blue-100 text-blue-700', icon: '≡ƒÄô' },
    'business-projects': { label: 'Business Projects', color: 'bg-purple-100 text-purple-700', icon: '≡ƒÆ╝' },
    'enterprise': { label: 'Enterprise', color: 'bg-red-100 text-red-700', icon: '≡ƒÅó' }
};

// Status badge component with improved styling
const StatusBadge = ({ status, size = 'sm' }) => {
    const config = STATUS_CONFIG[status] || STATUS_CONFIG['pending'];
    const Icon = config.icon;

    const sizeClasses = {
        xs: 'px-2 py-0.5 text-[9px]',
        sm: 'px-2.5 py-1 text-[10px]',
        md: 'px-3 py-1.5 text-xs',
        lg: 'px-3.5 py-2 text-sm'
    };

    return (
        <span className={`inline-flex items-center gap-1.5 rounded-lg font-semibold uppercase tracking-wide border ${config.color} transition-all ${sizeClasses[size]}`}>
            <Icon size={size === 'xs' ? 10 : size === 'sm' ? 12 : size === 'md' ? 14 : 16} className="flex-shrink-0" />
            {config.label}
        </span>
    );
};

// Package type badge component with improved styling
const PackageTypeBadge = ({ packageType, size = 'sm' }) => {
    const config = PACKAGE_TYPE_CONFIG[packageType] || PACKAGE_TYPE_CONFIG['student-projects'];
    
    const sizeClasses = {
        xs: 'px-2 py-0.5 text-[9px]',
        sm: 'px-2.5 py-1 text-[10px]',
        md: 'px-3 py-1.5 text-xs',
        lg: 'px-3.5 py-2 text-sm'
    };

    return (
        <span className={`inline-flex items-center gap-1.5 rounded-lg font-semibold uppercase tracking-wide ${config.color} transition-all ${sizeClasses[size]}`}>
            {config.label}
        </span>
    );
};

const ProjectRequestsManagementPage = () => {
    const dispatch = useDispatch();
    const navigate = useNavigate();
    const { user, userRole, userPermissions, userDepartment } = useAuth();

    // Permission check for projects management
    const hasProjectsPermission = canAccessFeature(userPermissions, userRole, 'projects');
    const isSuperAdminUser = isSuperAdmin(userRole);

    // State management
    const [requests, setRequests] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedPackageType, setSelectedPackageType] = useState('all');
    const [selectedStatus, setSelectedStatus] = useState('all');
    const [currentPage, setCurrentPage] = useState(1);
    const [statusModal, setStatusModal] = useState(null);
    const [statusNotes, setStatusNotes] = useState('');

    const itemsPerPage = 10;

    // Fetch project requests from API on component mount
    useEffect(() => {
        fetchRequests();
    }, []);

    const fetchRequests = async () => {
        try {
            setLoading(true);
            setError(null);
            const response = await projectRequestService.getAdminProjectRequests({ limit: 1000 });
            console.log('[ProjectRequestsManagementPage] Full API Response:', response);
            console.log('[ProjectRequestsManagementPage] Requests Array:', response.requests);
            console.log('[ProjectRequestsManagementPage] Requests Length:', response.requests?.length);
            setRequests(response.requests || []);
        } catch (err) {
            console.error('Failed to fetch project requests:', err);
            setError(err.message || 'Failed to load project requests');
            dispatch(addNotification({
                type: 'error',
                message: 'Failed to load project requests from server'
            }));
        } finally {
            setLoading(false);
        }
    };

    // Filter and search requests
    const filteredRequests = useMemo(() => {
        let result = [...requests];

        // Search filter
        if (searchQuery) {
            const query = searchQuery.toLowerCase();
            result = result.filter(req =>
                req.fullName.toLowerCase().includes(query) ||
                req.email.toLowerCase().includes(query) ||
                req.projectTitle.toLowerCase().includes(query) ||
                (req.company && req.company.toLowerCase().includes(query))
            );
        }

        // Package type filter
        if (selectedPackageType !== 'all') {
            result = result.filter(req => req.packageType === selectedPackageType);
        }

        // Status filter
        if (selectedStatus !== 'all') {
            result = result.filter(req => req.status === selectedStatus);
        }

        // Sort by date (newest first)
        result.sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt));

        return result;
    }, [requests, searchQuery, selectedPackageType, selectedStatus]);

    // Pagination
    const totalPages = Math.ceil(filteredRequests.length / itemsPerPage);
    const paginatedRequests = filteredRequests.slice(
        (currentPage - 1) * itemsPerPage,
        currentPage * itemsPerPage
    );

    // Statistics
    const stats = useMemo(() => ({
        total: requests.length,
        pending: requests.filter(r => r.status === 'pending').length,
        approved: requests.filter(r => r.status === 'approved').length,
        rejected: requests.filter(r => r.status === 'rejected').length,
        student: requests.filter(r => r.packageType === 'student-projects').length,
        business: requests.filter(r => r.packageType === 'business-projects').length,
        enterprise: requests.filter(r => r.packageType === 'enterprise').length
    }), [requests]);

    // Handlers
    const handleDelete = (request) => {
        // Permission check
        if (!isSuperAdminUser && !hasProjectsPermission) {
            checkPermissionAndShowError(
                userPermissions,
                userRole,
                'projects',
                dispatch,
                'Software Projects',
                'Software'
            );
            return;
        }

        dispatch(openConfirmDialog({
            title: 'Delete Project Request',
            message: `Are you sure you want to delete the request from ${request.fullName}? This action cannot be undone.`,
            isDangerous: true,
            onConfirm: async () => {
                try {
                    await projectRequestService.deleteProjectRequest(request.id);
                    setRequests(prev => prev.filter(r => r.id !== request.id));
                    dispatch(addNotification({
                        type: 'success',
                        message: `Request from ${request.fullName} deleted successfully`
                    }));
                } catch (err) {
                    console.error('Failed to delete request:', err);
                    dispatch(addNotification({
                        type: 'error',
                        message: `Failed to delete request: ${err.message}`
                    }));
                }
            }
        }));
    };

    const handleStatusUpdate = async (request, newStatus) => {
        // Permission check
        if (!isSuperAdminUser && !hasProjectsPermission) {
            checkPermissionAndShowError(
                userPermissions,
                userRole,
                'projects',
                dispatch,
                'Software Projects',
                'Software'
            );
            return;
        }

        try {
            await projectRequestService.updateProjectRequestStatus(request.id, {
                status: newStatus,
                reviewNotes: statusNotes
            });

            // Update local state
            setRequests(prev => prev.map(r =>
                r.id === request.id
                    ? { ...r, status: newStatus, reviewNotes: statusNotes }
                    : r
            ));

            setStatusModal(null);
            setStatusNotes('');

            dispatch(addNotification({
                type: 'success',
                message: `Request status updated to ${newStatus}`
            }));
        } catch (err) {
            console.error('Failed to update status:', err);
            dispatch(addNotification({
                type: 'error',
                message: `Failed to update status: ${err.message}`
            }));
        }
    };

    const handleView = (request) => {
        navigate(`/admin/project-requests/${request.id}`);
    };

    const resetFilters = () => {
        setSearchQuery('');
        setSelectedPackageType('all');
        setSelectedStatus('all');
        setCurrentPage(1);
    };

    const formatDate = (dateString) => {
        return new Date(dateString).toLocaleDateString('en-US', {
            year: 'numeric',
            month: 'short',
            day: 'numeric'
        });
    };

    const formatTime = (dateString) => {
        return new Date(dateString).toLocaleTimeString('en-US', {
            hour: '2-digit',
            minute: '2-digit',
            hour12: true
        });
    };

    return (
        <AdminLayout>
            <div className="space-y-3 md:space-y-6 pb-8">
                {/* Error Alert */}
                {error && (
                    <div className="bg-red-50 border border-red-200 rounded-xl p-4 flex items-start gap-3">
                        <AlertCircle className="text-red-600 flex-shrink-0 mt-0.5" size={18} />
                        <div>
                            <h3 className="font-semibold text-red-900">Error Loading Requests</h3>
                            <p className="text-sm text-red-700 mt-1">{error}</p>
                        </div>
                    </div>
                )}

                {/* Loading State */}
                {loading && (
                    <div className="bg-blue-50 border border-blue-200 rounded-xl p-4 flex items-center gap-3">
                        <div className="animate-spin">
                            <Clock className="text-blue-600" size={18} />
                        </div>
                        <div>
                            <p className="font-semibold text-blue-900">Loading requests...</p>
                            <p className="text-sm text-blue-700">Fetching project requests from the server</p>
                        </div>
                    </div>
                )}

                {/* Page Header */}
                <div className="flex flex-col md:flex-row justify-between items-start md:items-center bg-white p-2 md:p-4 rounded-xl border border-gray-100 shadow-sm gap-3 mb-4">
                    <div className="flex items-center gap-3">
                        <div className="bg-blue-50 p-2 rounded-lg shrink-0">
                            <Inbox size={18} className="text-blue-600" />
                        </div>
                        <div>
                            <h1 className="text-[11px] md:text-base font-bold text-gray-900 leading-tight">Project Requests</h1>
                            <p className="text-[10px] text-gray-500">Manage incoming project request submissions</p>
                        </div>
                    </div>
                </div>

                {/* Statistics Cards */}
                <div className="grid grid-cols-3 md:grid-cols-6 lg:grid-cols-6 gap-2 md:gap-3 mb-4">
                    {[
                        { title: 'Total', count: stats.total, icon: Inbox, color: 'text-blue-600', bg: 'bg-blue-50', onClick: () => { setSelectedStatus('all'); setCurrentPage(1); } },
                        { title: 'Pending', count: stats.pending, icon: Clock, color: 'text-amber-600', bg: 'bg-amber-50', onClick: () => { setSelectedStatus('pending'); setCurrentPage(1); } },
                        { title: 'Approved', count: stats.approved, icon: CheckCircle, color: 'text-green-600', bg: 'bg-green-50', onClick: () => { setSelectedStatus('approved'); setCurrentPage(1); } },
                        { title: 'Rejected', count: stats.rejected, icon: XCircle, color: 'text-red-600', bg: 'bg-red-50', onClick: () => { setSelectedStatus('rejected'); setCurrentPage(1); } },
                        { title: 'Student', count: stats.student, icon: FileText, color: 'text-blue-600', bg: 'bg-blue-50', onClick: () => { setSelectedPackageType('student-projects'); setCurrentPage(1); } },
                        { title: 'Business', count: stats.business, icon: Building2, color: 'text-purple-600', bg: 'bg-purple-50', onClick: () => { setSelectedPackageType('business-projects'); setCurrentPage(1); } },
                        { title: 'Enterprise', count: stats.enterprise, icon: Building2, color: 'text-red-600', bg: 'bg-red-50', onClick: () => { setSelectedPackageType('enterprise'); setCurrentPage(1); } },
                    ].map((stat, i) => (
                        <div key={i} onClick={stat.onClick} className="bg-white border border-gray-100 rounded-xl p-2 md:p-2.5 flex flex-col md:flex-row items-center md:items-start justify-center md:justify-start gap-1 md:gap-2 shadow-sm hover:border-[#004fa2] transition-colors cursor-pointer text-center md:text-left group">
                            <div className={`w-6 h-6 md:w-7 md:h-7 rounded-md shrink-0 flex items-center justify-center ${stat.bg}`}>
                                <stat.icon className={stat.color} size={14} />
                            </div>
                            <div className="min-w-0">
                                <p className="text-[9px] md:text-[10px] text-gray-500 font-medium uppercase tracking-wide truncate group-hover:text-[#004fa2] transition-colors">{stat.title}</p>
                                <p className="text-xs md:text-sm font-bold text-gray-900 leading-none mt-0.5 md:mt-0">{stat.count}</p>
                            </div>
                        </div>
                    ))}
                </div>

                {/* Filters and Search */}
                <div className="grid grid-cols-2 md:grid-cols-12 gap-2 mb-4">
                    <div className="col-span-2 md:col-span-6 relative">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" size={14} />
                        <input
                            type="text"
                            placeholder="Search by name, email, title..."
                            value={searchQuery}
                            onChange={(e) => { setSearchQuery(e.target.value); setCurrentPage(1); }}
                            className="w-full pl-8 pr-3 py-2 text-[11px] bg-white border border-gray-100 shadow-sm rounded-xl focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] outline-none transition-all"
                        />
                    </div>

                    <div className="col-span-1 md:col-span-3 relative">
                        <Filter size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-400" />
                        <select
                            value={selectedPackageType}
                            onChange={(e) => { setSelectedPackageType(e.target.value); setCurrentPage(1); }}
                            className="w-full pl-8 pr-3 py-2 text-[11px] bg-white border border-gray-100 shadow-sm rounded-xl focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] outline-none appearance-none transition-all"
                        >
                            <option value="all">All Packages</option>
                            <option value="student-projects">Student Projects</option>
                            <option value="business-projects">Business Projects</option>
                            <option value="enterprise">Enterprise</option>
                        </select>
                    </div>

                    <div className="col-span-1 md:col-span-3 flex items-center justify-end gap-1">
                        <select
                            value={selectedStatus}
                            onChange={(e) => { setSelectedStatus(e.target.value); setCurrentPage(1); }}
                            className="flex-1 px-3 py-2 text-[11px] bg-white border border-gray-100 shadow-sm rounded-xl focus:ring-2 focus:ring-[#004fa2]/20 focus:border-[#004fa2] outline-none appearance-none transition-all"
                        >
                            <option value="all">All Status</option>
                            <option value="pending">Pending</option>
                            <option value="approved">Approved</option>
                            <option value="rejected">Rejected</option>
                        </select>
                        {(searchQuery || selectedPackageType !== 'all' || selectedStatus !== 'all') && (
                            <button onClick={resetFilters} className="bg-white border border-gray-100 hover:bg-gray-50 text-gray-600 h-[34px] w-[34px] rounded-xl transition-colors shadow-sm flex items-center justify-center shrink-0">
                                <X size={14} />
                            </button>
                        )}
                    </div>
                </div>

                {/* Requests Table */}
                {loading || error ? (
                    <div className="bg-white rounded-xl p-12 text-center shadow-sm border border-gray-100">
                        <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            {loading ? (
                                <Clock className="text-gray-400 animate-spin" size={28} />
                            ) : (
                                <AlertCircle className="text-red-400" size={28} />
                            )}
                        </div>
                        <h3 className="text-lg font-semibold text-gray-900 mb-2">{loading ? 'Loading Requests' : 'Error Loading Requests'}</h3>
                        <p className="text-sm text-gray-500">{loading ? 'Fetching project requests from the server...' : error}</p>
                    </div>
                ) : paginatedRequests.length === 0 ? (
                    <div className="bg-white rounded-xl p-12 text-center shadow-sm border border-gray-100">
                        <Inbox className="text-gray-300 mx-auto mb-4" size={48} />
                        <h3 className="text-lg font-semibold text-gray-900 mb-2">No Requests Found</h3>
                        <p className="text-sm text-gray-500">No project requests match your current filters.</p>
                    </div>
                ) : (
                    <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                        {/* Desktop Table View */}
                        <div className="hidden md:block overflow-x-auto">
                            <table className="w-full">
                                <thead className="bg-gray-50 border-b border-gray-200">
                                    <tr>
                                        <th className="px-6 py-4 text-left">
                                            <span className="text-xs font-semibold text-gray-600 uppercase tracking-wider">Name</span>
                                        </th>
                                        <th className="px-6 py-4 text-left">
                                            <span className="text-xs font-semibold text-gray-600 uppercase tracking-wider">Email</span>
