                                                        <div className="flex-shrink-0 w-5 h-5 bg-gradient-to-r from-amber-400 to-yellow-500 rounded-full flex items-center justify-center" title="Featured">
                                                            <Star className="text-white fill-white" size={12} />
                                                        </div>
                                                    )}
                                                </div>
                                                <p className="text-sm text-gray-600 truncate font-medium">{testimonial.role}</p>
                                                {testimonial.organization && (
                                                    <p className="text-xs text-gray-500 truncate mt-0.5">{testimonial.organization}</p>
                                                )}
                                            </div>
                                            <StatusBadge status={testimonial.status} />
                                        </div>
                                        
                                        {/* Star Rating */}
                                        <div className="flex items-center gap-2">
                                            <StarRating rating={testimonial.rating} size={16} />
                                            <span className="text-sm font-bold text-gray-700">{testimonial.rating}.0</span>
                                        </div>
                                    </div>
                                    
                                    {/* Quote Content */}
                                    <div className="p-5 flex-1 bg-white">
                                        <div className="relative">
                                            <Quote className="absolute -top-1 -left-1 text-blue-100" size={28} />
                                            <p className="text-sm text-gray-700 leading-relaxed line-clamp-4 relative z-10 pl-6">
                                                {testimonial.content}
                                            </p>
                                        </div>
                                    </div>
                                    
                                    {/* Action Buttons Footer */}
                                    <div className="p-4 bg-gradient-to-br from-gray-50 to-white border-t border-gray-100">
                                        <div className="flex items-center justify-between gap-2">
                                            <div className="flex items-center gap-1">
                                                <button 
                                                    onClick={() => handleView(testimonial)} 
                                                    className="p-2 hover:bg-blue-100 rounded-lg text-gray-500 hover:text-blue-600 transition-all group/btn"
                                                    title="View Details"
                                                >
                                                    <Eye size={16} className="group-hover/btn:scale-110 transition-transform" />
                                                </button>
                                                <button 
                                                    onClick={() => { if (!canManageTestimonials) { handlePermissionDenied(); return; } handleEdit(testimonial); }} 
                                                    className="p-2 hover:bg-green-100 rounded-lg text-gray-500 hover:text-green-600 transition-all group/btn"
                                                    title="Edit"
                                                >
                                                    <Edit size={16} className="group-hover/btn:scale-110 transition-transform" />
                                                </button>
                                                {testimonial.status !== 'published' && (
                                                    <button 
                                                        onClick={() => { if (!canManageTestimonials) { handlePermissionDenied(); return; } handlePublish(testimonial); }} 
                                                        className="p-2 rounded-lg text-gray-500 hover:bg-emerald-100 hover:text-emerald-600 transition-all group/btn"
                                                        title="Publish"
                                                    >
                                                        <Send size={16} className="group-hover/btn:scale-110 transition-transform" />
                                                    </button>
                                                )}
                                            </div>
                                            <div className="flex items-center gap-1 border-l border-gray-200 pl-2">
                                                <button 
                                                    onClick={() => { if (!canManageTestimonials) { handlePermissionDenied(); return; } handleToggleFeatured(testimonial); }} 
                                                    className={`p-2 rounded-lg transition-all group/btn ${
                                                        testimonial.isFeatured 
                                                            ? 'bg-gradient-to-r from-amber-100 to-yellow-100 text-amber-600 hover:from-amber-200 hover:to-yellow-200' 
                                                            : 'text-gray-500 hover:bg-amber-50 hover:text-amber-500'
                                                    }`}
                                                    title={testimonial.isFeatured ? "Remove Featured" : "Mark as Featured"}
                                                >
                                                    <Star size={16} className={`${testimonial.isFeatured ? "fill-amber-500" : ""} group-hover/btn:scale-110 transition-transform`} />
                                                </button>
                                                <button 
                                                    onClick={() => { if (!canManageTestimonials) { handlePermissionDenied(); return; } handleDelete(testimonial); }} 
                                                    className="p-2 hover:bg-red-100 rounded-lg text-gray-500 hover:text-red-600 transition-all group/btn"
                                                    title="Delete"
                                                >
                                                    <Trash2 size={16} className="group-hover/btn:scale-110 transition-transform" />
                                                </button>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                ) : (
                    /* List View */
                    <div className="flex flex-col gap-2">
                        {(Array.isArray(paginatedTestimonials) ? paginatedTestimonials : []).map((testimonial) => {
                            return (
                                <div key={testimonial.id} className="bg-white rounded-xl shadow-sm border border-gray-100 flex flex-col md:flex-row md:items-center p-3 gap-3 hover:border-[#004fa2] transition-colors group">
                                    <div className="flex items-center gap-3 md:w-1/4 shrink-0">
                                        <AvatarDisplay name={testimonial.name} avatarUrl={testimonial.avatarUrl} size="sm" />
                                        <div className="min-w-0">
                                            <div className="flex items-center gap-1">
                                                <h3 className="text-xs font-bold text-gray-900 truncate">{testimonial.name}</h3>
                                                {testimonial.isFeatured && <Star className="text-amber-500 fill-amber-500" size={10} />}
                                            </div>
                                            <p className="text-[10px] text-gray-500 truncate">{testimonial.role}</p>
                                        </div>
                                    </div>
                                    <p className="text-[11px] text-gray-600 line-clamp-2 md:w-2/5 flex-1 italic relative">
                                        "{testimonial.content}"
                                    </p>
                                    <div className="flex items-center justify-between md:justify-end gap-3 md:w-1/3 shrink-0">
                                        <StarRating rating={testimonial.rating} size={10} />
                                        <StatusBadge status={testimonial.status} />
                                        <div className="flex items-center gap-0.5 border-l border-gray-100 pl-2">
                                            <button onClick={() => handleView(testimonial)} className="p-1.5 hover:bg-blue-50 rounded text-gray-400 hover:text-[#004fa2] transition-colors" title="View"><Eye size={14} /></button>
                                            <button onClick={() => { if (!canManageTestimonials) { handlePermissionDenied(); return; } handleEdit(testimonial); }} className="p-1.5 hover:bg-green-50 rounded text-gray-400 hover:text-green-600 transition-colors" title="Edit"><Edit size={14} /></button>
                                            {testimonial.status !== 'published' && (
                                                <button onClick={() => { if (!canManageTestimonials) { handlePermissionDenied(); return; } handlePublish(testimonial); }} className="p-1.5 hover:bg-emerald-50 rounded text-gray-400 hover:text-emerald-600 transition-colors" title="Publish"><Send size={14} /></button>
                                            )}
                                            <button onClick={() => { if (!canManageTestimonials) { handlePermissionDenied(); return; } handleDelete(testimonial); }} className="p-1.5 hover:bg-red-50 rounded text-gray-400 hover:text-red-600 transition-colors" title="Delete"><Trash2 size={14} /></button>
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}

                {/* Empty State */}
                {filteredTestimonials.length === 0 && (
                    <div className="bg-white rounded-xl p-12 text-center shadow-sm border border-gray-100">
                        <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center mx-auto mb-4">
                            <MessageCircle className="text-gray-400" size={28} />
                        </div>
                        <h3 className="text-lg font-semibold text-gray-900 mb-2">No testimonials found</h3>
                        <p className="text-sm text-gray-500 mb-4">
                            Try adjusting your search or filter criteria
                        </p>
                        <button
                            onClick={resetFilters}
                            className="px-4 py-2 text-sm text-[#004fa2] hover:bg-blue-50 rounded-lg transition-colors font-medium"
                        >
                            Reset Filters
                        </button>
                    </div>
                )}

                {/* Pagination */}
                {totalPages > 1 && (
                    <div className="flex flex-col sm:flex-row items-center justify-between bg-white rounded-xl p-3 shadow-sm border border-gray-100 gap-3">
                        <p className="text-[10px] text-gray-500 uppercase tracking-widest font-semibold">
                            Showing <span className="text-gray-900">{(currentPage - 1) * itemsPerPage + 1}</span> to{' '}
                            <span className="text-gray-900">{Math.min(currentPage * itemsPerPage, filteredTestimonials.length)}</span> of{' '}
                            <span className="text-gray-900">{filteredTestimonials.length}</span>
                        </p>
                        <div className="flex items-center gap-1">
                            <button
                                onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
                                disabled={currentPage === 1}
                                className="p-1 text-gray-400 hover:text-[#004fa2] hover:bg-blue-50 rounded transition-colors disabled:opacity-40"
                            >
                                <ChevronLeft size={16} />
                            </button>
                            <div className="flex items-center gap-1">
                                {Array.from({ length: totalPages }, (_, i) => i + 1).map(page => (
                                    <button
                                        key={page}
                                        onClick={() => setCurrentPage(page)}
                                        className={`min-w-[24px] h-6 flex items-center justify-center rounded text-[10px] font-bold transition-all ${currentPage === page
                                            ? 'bg-[#004fa2] text-white shadow-sm'
                                            : 'text-gray-500 hover:bg-gray-100'
                                            }`}
                                    >
                                        {page}
                                    </button>
                                ))}
                            </div>
                            <button
                                onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
                                disabled={currentPage === totalPages}
                                className="p-1 text-gray-400 hover:text-[#004fa2] hover:bg-blue-50 rounded transition-colors disabled:opacity-40"
                            >
                                <ChevronRight size={16} />
                            </button>
                        </div>
                    </div>
                )}
            </div>

            {/* View Testimonial Modal */}
            {viewingTestimonial && (
                <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[85vh] flex flex-col overflow-hidden">
                        {/* Modal Header */}
                        <div className="px-6 py-4 bg-gradient-to-r from-[#004fa2] to-[#0066cc] flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="w-6 h-6 md:w-8 md:h-8 md:w-10 md:h-10 bg-white/20 rounded-xl flex items-center justify-center">
                                    <MessageCircle className="text-white" size={22} />
                                </div>
                                <div>
                                    <h2 className="text-lg font-bold text-white">Testimonial Details</h2>
                                    <p className="text-blue-100 text-xs">{viewingTestimonial.program}</p>
                                </div>
                            </div>
                            <button
                                onClick={() => setViewingTestimonial(null)}
                                className="p-2 text-white/80 hover:text-white hover:bg-white/10 rounded-lg transition-colors"
                            >
                                <X size={20} />
                            </button>
                        </div>

                        {/* Modal Body */}
                        <div className="p-6 overflow-y-auto flex-1">
                            <div className="space-y-5">
                                {/* Author Info */}
                                <div className="flex items-center gap-4 pb-4 border-b border-gray-100">
                                    <AvatarDisplay name={viewingTestimonial.name} avatarUrl={viewingTestimonial.avatarUrl} size="lg" />
                                    <div>
                                        <div className="flex items-center gap-2">
                                            <h3 className="text-xl font-bold text-gray-900">{viewingTestimonial.name}</h3>
                                            {viewingTestimonial.verified && (
                                                <CheckCircle className="text-blue-500" size={18} />
                                            )}
                                            {viewingTestimonial.isFeatured && (
                                                <Star className="text-amber-500 fill-amber-500" size={18} />
                                            )}
                                        </div>
                                        <p className="text-gray-500">{viewingTestimonial.role}</p>
                                        {viewingTestimonial.organization && (
                                            <p className="text-sm text-gray-600 mt-1">{viewingTestimonial.organization}</p>
                                        )}
                                        <div className="flex items-center gap-2 mt-2">
                                            <StatusBadge status={viewingTestimonial.status} />
                                        </div>
                                    </div>
                                </div>

                                {/* Quote */}
                                <div className="bg-gray-50 rounded-xl p-5 relative">
                                    <Quote className="absolute top-4 left-4 text-gray-200" size={32} />
                                    <p className="text-lg text-gray-700 leading-relaxed pl-8 italic">
                                        "{viewingTestimonial.content}"
                                    </p>
                                </div>

                                {/* Rating */}
                                <div className="flex items-center justify-center gap-2">
                                    <StarRating rating={viewingTestimonial.rating} size={24} />
                                    <span className="text-lg font-bold text-gray-900 ml-2">{viewingTestimonial.rating}/5</span>
                                </div>

                                {/* Stats Grid */}
                                <div className="grid grid-cols-2 gap-4">
                                    <div className="bg-gray-50 rounded-xl p-4 text-center">
                                        <Calendar className="mx-auto text-gray-400 mb-2" size={20} />
                                        <p className="text-lg font-bold text-gray-900">{viewingTestimonial.date}</p>
                                        <p className="text-xs text-gray-500">Date Added</p>
                                    </div>
                                    <div className="bg-gray-50 rounded-xl p-4 text-center">
                                        <CheckCircle className="mx-auto text-gray-400 mb-2" size={20} />
                                        <p className="text-lg font-bold text-gray-900">{viewingTestimonial.verified ? 'Yes' : 'No'}</p>
                                        <p className="text-xs text-gray-500">Verified</p>
                                    </div>
                                </div>
                            </div>
                        </div>

                        {/* Modal Footer */}
                        <div className="px-6 py-4 border-t border-gray-100 flex items-center justify-between bg-gray-50">
                            <button
                                onClick={() => setViewingTestimonial(null)}
                                className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition-colors font-medium text-sm"
                            >
                                Close
                            </button>
                            <div className="flex items-center gap-2">
                                <button
                                    onClick={() => {
                                        setViewingTestimonial(null);
                                        handleEdit(viewingTestimonial);
                                    }}
                                    className="px-4 py-2 bg-white border border-gray-200 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors font-medium text-sm flex items-center gap-1.5"
                                >
                                    <Edit size={14} />
                                    Edit
                                </button>
                                <button
                                    onClick={() => { if (!canManageTestimonials) { handlePermissionDenied(); return; } handleToggleFeatured(viewingTestimonial); }}
                                    className="px-4 py-2 bg-amber-500 text-white rounded-lg hover:bg-amber-600 transition-colors font-medium text-sm flex items-center gap-1.5"
                                >
                                    <Star size={14} className={viewingTestimonial.isFeatured ? 'fill-white' : ''} />
                                    {viewingTestimonial.isFeatured ? 'Unfeature' : 'Feature'}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            )}

            {/* Add/Edit Testimonial Modal */}
            {showModal && (
                <div className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 p-4">
                    <div className="bg-white rounded-2xl shadow-2xl max-w-2xl w-full max-h-[85vh] flex flex-col overflow-hidden">
                        {/* Modal Header */}
                        <div className="px-6 py-4 border-b border-gray-100 flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <div className="w-6 h-6 md:w-8 md:h-8 md:w-10 md:h-10 bg-gradient-to-br from-[#004fa2] to-[#0066cc] rounded-xl flex items-center justify-center">
                                    {editingTestimonial ? <Edit className="text-white" size={20} /> : <Plus className="text-white" size={20} />}
                                </div>
                                <div>
                                    <h2 className="text-lg font-bold text-gray-900">
                                        {editingTestimonial ? 'Edit Testimonial' : 'Add New Testimonial'}
                                    </h2>
                                    <p className="text-gray-500 text-xs">
                                        {editingTestimonial ? 'Update testimonial information' : 'Create a new customer testimonial'}
                                    </p>
                                </div>
                            </div>
                            <button
                                onClick={() => { setShowModal(false); setEditingTestimonial(null); }}
                                className="p-2 text-gray-400 hover:text-gray-600 hover:bg-gray-100 rounded-lg transition-colors"
                            >
                                <X size={20} />
                            </button>
                        </div>

                        {/* Modal Body */}
                        <div className="p-6 overflow-y-auto flex-1">
                            <div className="text-center py-12">
                                <div className="w-16 h-16 bg-amber-100 rounded-full flex items-center justify-center mx-auto mb-4">
                                    <AlertCircle className="text-amber-500" size={32} />
                                </div>
                                <h3 className="text-lg font-semibold text-gray-900 mb-2">Coming Soon</h3>
                                <p className="text-sm text-gray-500 max-w-md mx-auto">
                                    The testimonial editor form will be available once the backend API is ready.
                                    Currently, testimonials are managed via the <code className="px-1.5 py-0.5 bg-gray-100 rounded text-xs">Testimonials.jsx</code> data file.
                                </p>
                            </div>
                        </div>

                        {/* Modal Footer */}
                        <div className="px-6 py-4 border-t border-gray-100 flex items-center justify-end gap-3 bg-gray-50">
                            <button
                                onClick={() => { setShowModal(false); setEditingTestimonial(null); }}
                                className="px-4 py-2 text-gray-600 hover:bg-gray-200 rounded-lg transition-colors font-medium text-sm"
                            >
                                Close
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </AdminLayout>
    );
};

export default TestimonialsManagementPage;

import React, { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import { openConfirmDialog, addNotification } from '../../../store/slices/uiSlice';
import AdminLayout from '../../../components/admin/layout/AdminLayout';
import trainingApplicationService from '../../../services/trainingApplicationService';
import api from '../../../services/api';
import LoadingSpinner from '../../../components/admin/shared/LoadingSpinner';
import RejectApplicationDialog from '../../../components/admin/training/RejectApplicationDialog';
import {
    Users,
    ChevronLeft,
    Mail,
    Phone,
    MapPin,
    GraduationCap,
    FileText,
    Download,
    Linkedin,
    Globe,
    ExternalLink,
    XCircle,
    CheckCircle,
    Calendar,
    Clock,
    CreditCard,
    DollarSign,
    Eye
} from 'lucide-react';

const ApplicationDetailsPage = () => {
    const { id } = useParams();
    const navigate = useNavigate();
    const dispatch = useDispatch();
    
    const [application, setApplication] = useState(null);
    const [payment, setPayment] = useState(null);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState(null);
    const [rejectDialogOpen, setRejectDialogOpen] = useState(false);
    const [paymentInfo, setPaymentInfo] = useState(null);

    useEffect(() => {
        fetchApplication();
    }, [id]);

    const fetchApplication = async () => {
        try {
            setLoading(true);
            setError(null);
            
            // Fetch application details
            const response = await trainingApplicationService.getApplication(id);
            const applicationData = response.data || response;
            
            console.log('≡ƒôï Full application data from backend:', applicationData);
            
            setApplication(applicationData);
            
            // Fetch payment separately using transactions endpoint
            const paymentData = await trainingApplicationService.getApplicationPayment(id);
            console.log('≡ƒÆ░ Payment data from backend:', paymentData);
            
            setPayment(paymentData);
        } catch (err) {
            console.error('Failed to fetch application:', err);
            setError(err.response?.data?.message || 'Failed to load application details');
        } finally {
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <AdminLayout>
                <LoadingSpinner text="Loading application details..." />
            </AdminLayout>
        );
    }

    if (error || !application) {
        return (
            <AdminLayout>
                <div className="flex flex-col items-center justify-center min-h-[60vh]">
                    <h2 className="text-xl font-bold text-gray-900 mb-2">Application Not Found</h2>
                    <p className="text-gray-500 mb-4">{error || 'The application you are looking for does not exist.'}</p>
                    <button
                        onClick={() => navigate('/admin/course-applications')}
                        className="text-[#004fa2] hover:underline"
                    >
                        Return to Training
                    </button>
                </div>
            </AdminLayout>
        );
    }

    const handleApprove = () => {
        dispatch(openConfirmDialog({
            title: 'Approve Application',
            message: `Approve ${application.applicantName}'s application for ${application.courseTitle || application.course?.title || 'this course'}?`,
            onConfirm: async () => {
                try {
                    await trainingApplicationService.updateApplicationStatus(application.id, 'approved');
                    dispatch(addNotification({
                        type: 'success',
                        message: 'Application approved successfully'
                    }));
                    navigate('/admin/course-applications');
                } catch (error) {
                    dispatch(addNotification({
                        type: 'error',
                        message: error.response?.data?.message || 'Failed to approve application'
                    }));
                }
            }
        }));
    };

    const handleReject = async () => {
        try {
            // Check payment status first
            const paymentStatus = await trainingApplicationService.checkPaymentStatus(application.id);
            console.log('≡ƒÆ░ Payment status:', paymentStatus);
            
            setPaymentInfo(paymentStatus);
            setRejectDialogOpen(true);
        } catch (error) {
            console.error('Failed to check payment status:', error);
            dispatch(addNotification({
                type: 'error',
                message: 'Failed to check payment status. Please try again.'
            }));
        }
    };
    
    const handleConfirmReject = async (shouldRefund, reviewNotes) => {
        try {
            await trainingApplicationService.updateApplicationStatus(
                application.id,
                'rejected',
                { shouldRefund, reviewNotes }
            );
            
            dispatch(addNotification({
                type: 'success',
                message: shouldRefund 
                    ? 'Application rejected and refund processed Γ£à'
                    : 'Application rejected'
            }));
            
            navigate('/admin/training');
        } catch (error) {
            dispatch(addNotification({
                type: 'error',
                message: error.response?.data?.message || 'Failed to reject application'
            }));
            throw error; // Re-throw to keep dialog open
        }
    };
    
    const handleRefundPayment = () => {
        if (!payment || !payment.reference) {
            dispatch(addNotification({
                type: 'error',
                message: 'No payment reference found'
            }));
            return;
        }
        
        dispatch(openConfirmDialog({
            title: 'Refund Payment',
            message: `Refund ${payment.currency} ${payment.amount} to ${application.applicantName}?`,
            confirmLabel: 'Process Refund',
            isDangerous: true,
            onConfirm: async () => {
                try {
                    // Call refund API
                    const response = await api.post(`/admin/transactions/${payment.reference}/refund`);
                    
                    dispatch(addNotification({
                        type: 'success',
                        message: 'Refund processed successfully! Money will be returned in 5-7 business days.'
                    }));
                    
                    // Refresh application data
                    fetchApplication();
                } catch (error) {
                    dispatch(addNotification({
                        type: 'error',
                        message: error.response?.data?.message || 'Failed to process refund'
                    }));
                }
            }
        }));
    };

    const handleDownloadCV = async () => {
        if (application.cvFileUrl) {
            try {
                // Fetch the file and trigger download
                const response = await fetch(application.cvFileUrl);
                const blob = await response.blob();
                const url = window.URL.createObjectURL(blob);
                const link = document.createElement('a');
                link.href = url;
                link.download = `${application.applicantName}_CV.pdf`;
                document.body.appendChild(link);
                link.click();
                document.body.removeChild(link);
                window.URL.revokeObjectURL(url);
            } catch (error) {
                console.error('Download failed:', error);
                // Fallback to opening in new tab
                window.open(application.cvFileUrl, '_blank');
            }
        }
    };
    
    const handlePreviewCV = () => {
        if (application.cvFileUrl) {
            window.open(application.cvFileUrl, '_blank');
        }
    };

    return (
        <AdminLayout>
            <div className="max-w-5xl mx-auto space-y-3 md:space-y-6 pb-8">
                {/* Header */}
                <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-4">
                    <div className="flex items-center gap-3">
                        <button
                            onClick={() => navigate('/admin/course-applications')}
                            className="w-6 h-6 md:w-8 md:h-8 md:w-10 md:h-10 bg-white border border-gray-200 rounded-xl flex items-center justify-center text-gray-500 hover:text-gray-900 hover:bg-gray-50 transition-colors"
                        >
                            <ChevronLeft size={20} />
