import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import {
  BadgeCheck, Globe, Layers, Code2, ServerCog, Shield, Users, BookOpen, GraduationCap,
  Smartphone, Database, Layout, Cpu, Briefcase, ShieldCheck, Cog, TrendingUp, DollarSign
} from 'lucide-react';

import contentService from '../../../../services/contentService';
import { containerVariants, itemVariants } from '../motionVariants';

// Icon mapping - MUST match ServiceFormPage ICON_OPTIONS
const ICON_MAP = {
  'Code2': Code2,
  'ServerCog': ServerCog,
  'BookOpen': BookOpen,
  'GraduationCap': GraduationCap,
  'Shield': Shield,
  'ShieldCheck': ShieldCheck,
  'Briefcase': Briefcase,
  'Globe': Globe,
  'Smartphone': Smartphone,
  'Database': Database,
  'Layout': Layout,
  'Cpu': Cpu,
  'Users': Users,
  'Layers': Layers,
  'BadgeCheck': BadgeCheck,
  'Cog': Cog,
  'TrendingUp': TrendingUp,
  'DollarSign': DollarSign
};

const ServicesGridSection = () => {
  const [services, setServices] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchServices = async () => {
      try {
        // Use public endpoint (no authentication required)
        const response = await contentService.getPublicServices();
        // getPublicServices already returns array directly
        setServices(Array.isArray(response) ? response : []);
      } catch (error) {
        console.error("Failed to fetch services:", error);
      } finally {
        setLoading(false);
      }
    };
    fetchServices();
